export default ", Tableflow Iceberg reader, Real-Time Context Engine MCP tools) as a standalone Langflow Extension Bundle.\\\"\\nreadme = \\\"README.md\\\"\\nrequires-python = \\\">=3.10,<3.15\\\"\\nlicense = { text = \\\"MIT\\\" }\\nauthors = [\\n    { name = \\\"Langflow\\\", email = \\\"contact@langflow.org\\\" },\\n]\\nkeywords = [\\\"langflow\\\", \\\"lfx\\\", \\\"extension\\\", \\\"bundle\\\", \\\"confluent\\\", \\\"kafka\\\", \\\"tableflow\\\", \\\"iceberg\\\", \\\"flink\\\", \\\"streaming\\\"]\\n\\n# Runtime deps: lfx (the BUNDLE_API surface) plus the third-party imports the\\n# components use directly.\\n#\\n# * ``confluent-kafka`` powers the Kafka producer/consumer components. It is\\n#   the vendor-supported client for Confluent Cloud/Platform; its wheels bundle\\n#   librdkafka so there is no system dependency. The ``avro``/``json``/\\n#   ``schemaregistry`` extras pull the light Schema Registry (de)serializer\\n#   deps (fastavro, jsonschema, httpx) so Avro / JSON-Schema topics decode out\\n#   of the box. It is imported lazily (inside the build methods) so the bundle\\n#   still loads -- and the MCP / Tableflow components still work -- on a\\n#   platform where the wheel is unavailable.\\n# * ``pyiceberg`` + ``pyarrow`` power the Tableflow reader (Iceberg REST\\n#   catalog -> Arrow -> DataFrame) without a JVM. Also imported lazily.\\n# * ``langchain-core`` is already an lfx dep but is listed as a direct runtime\\n#   dep because the MCP preset component types its tools as\\n#   ``langchain_core.tools.StructuredTool``.\\n# lfx is floored at the current major.minor line and capped below the next lfx\\n# major; the floor is re-synced on ``make patch`` via\\n# scripts/ci/sync_bundle_lfx_pin.py. Fine-grained BUNDLE_API compatibility is\\n# enforced via extension.json's lfx.compat list against BUNDLE_API_VERSION.\\ndependencies = [\\n    \\\"lfx>=1.12.0.dev0,<2.0.0\\\",\\n    \\\"confluent-kafka[avro,json,schemaregistry]>=2.8,<3\\\",\\n    \\\"pyiceberg>=0.10,<1\\\",\\n    \\\"pyarrow>=17\\\",\\n    \\\"langchain-core>=1.2.28,<2.0.0\\\",\\n]\\n\\n[project.urls]\\nHomepage = \\\"https://github.com/langflow-ai/langflow\\\"\\nDocumentation = \\\"https://docs.langflow.org/extensions\\\"\\nRepository = \\\"https://github.com/langflow-ai/langflow\\\"\\n\\n# Manifest-shipping distributions are discovered via the\\n# ``langflow.extensions`` entry-point.  Editable installs whose\\n# ``dist.files`` only surfaces dist-info entries fall back to this\\n# entry-point to find the manifest.\\n[project.entry-points.\\\"langflow.extensions\\\"]\\nlfx-confluent = \\\"lfx_confluent\\\"\\n\\n[build-system]\\nrequires = [\\\"hatchling==1.31.0\\\"]\\nbuild-backend = \\\"hatchling.build\\\"\\n\\n[tool.hatch.build.targets.wheel]\\n# extension.json + components live inside the lfx_confluent package so\\n# ``importlib.metadata.files(dist)`` finds them and the loader resolves\\n# bundles[].path relative to the manifest's directory.\\npackages = [\\\"src/lfx_confluent\\\"]\\ninclude = [\\\"src/lfx_confluent/extension.json\\\", \\\"src/lfx_confluent/components/**/*.py\\\"]\\n\\n[tool.hatch.build.targets.sdist]\\ninclude = [\\n    \\\"src/lfx_confluent\\\",\\n    \\\"extension.json\\\",\\n    \\\"README.md\\\",\\n    \\\"pyproject.toml\\\",\\n]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/confluent/src/lfx_confluent/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"3f04e2582d56a055bda6df7890e876da130beb9dc48e709e793412c5c19462ef\",\"content\":\"\\\"\\\"\\\"lfx-confluent: IBM Confluent bundle (data-in-motion side of the IBM streamhouse).\\n\\nThis package is the distribution unit ``lfx-confluent``.  At runtime\\nLangflow's loader discovers ``extension.json`` shipped alongside this\\n``__init__.py`` and registers the components under the namespaced IDs:\\n\\n* ``ext:confluent:ConfluentContextEngineComponent@official``\\n* ``ext:confluent:ConfluentKafkaConsumerComponent@official``\\n* ``ext:confluent:ConfluentKafkaProducerComponent@official``\\n* ``ext:confluent:ConfluentTableflowReaderComponent@official``\\n\\nEverything talks to Confluent over open protocols only -- the Kafka wire\\nprotocol (``confluent-kafka``), the Tableflow Iceberg REST catalog\\n(``pyiceberg``), and MCP over Streamable HTTP (Langflow's own MCP client\\nengine) -- so the same components work against Confluent Cloud, Confluent\\nPlatform, and WarpStream wherever the corresponding surface is exposed.\\n\\\"\\\"\\\"\\n\\nfrom lfx_confluent.components.confluent.context_engine import ConfluentContextEngineComponent\\nfrom lfx_confluent.components.confluent.kafka_consumer import ConfluentKafkaConsumerComponent\\nfrom lfx_confluent.components.confluent.kafka_producer import ConfluentKafkaProducerComponent\\nfrom lfx_confluent.components.confluent.tableflow_reader import ConfluentTableflowReaderComponent\\n\\n__all__ = [\\n    \\\"ConfluentContextEngineComponent\\\",\\n    \\\"ConfluentKafkaConsumerComponent\\\",\\n    \\\"ConfluentKafkaProducerComponent\\\",\\n    \\\"ConfluentTableflowReaderComponent\\\",\\n]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/confluent/src/lfx_confluent/components/confluent/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"9d8cb18574fcb9cde7fcf329aaec11eb31cffc2d4b26d00658ea128e463c1bc4\",\"content\":\"from .context_engine import ConfluentContextEngineComponent\\nfrom .kafka_consumer import ConfluentKafkaConsumerComponent\\nfrom .kafka_producer import ConfluentKafkaProducerComponent\\nfrom .tableflow_reader import ConfluentTableflowReaderComponent\\n\\n__all__ = [\\n    \\\"ConfluentContextEngineComponent\\\",\\n    \\\"ConfluentKafkaConsumerComponent\\\",\\n    \\\"ConfluentKafkaProducerComponent\\\",\\n    \\\"ConfluentTableflowReaderComponent\\\",\\n]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/confluent/src/lfx_confluent/components/confluent/_common.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"fd89b40c1df6a3945f3be331ac5a07837d8417bec74e361ea4cf46d3b66b57c9\",\"content\":\"\\\"\\\"\\\"Shared helpers for the IBM Confluent bundle.\\n\\nSmall, dependency-free utilities used by every component in the bundle:\\nendpoint templating for the Confluent Cloud regional services, Basic-auth\\nheader construction, Kafka client configuration for Confluent Cloud\\n(SASL_SSL / PLAIN with an API key + secret), and SSRF gating of every\\ntenant-supplied host through Langflow's connector policy.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport base64\\nimport re\\n\\nfrom lfx.utils.ssrf_protection import validate_connector_url_for_ssrf\\n\\nDEFAULT_CLOUD = \\\"aws\\\"\\nDEFAULT_REGION = \\\"us-east-1\\\"\\nKAFKA_DEFAULT_PORT = 9092\\nMAX_PORT = 65535\\n\\n# Confluent resource IDs (org / env / cluster / compute pool) and cloud\\n# region names are simple tokens.  Restricting them keeps user input from\\n# escaping the URL path segment it is interpolated into.\\n_TOKEN_RE = re.compile(r\\\"^[A-Za-z0-9][A-Za-z0-9._-]*$\\\")\\n\\n\\ndef require_token(value: str | None, label: str) -> str:\\n    \\\"\\\"\\\"Return ``value`` stripped, or raise ``ValueError`` if it is empty or not a plain token.\\\"\\\"\\\"\\n    text = (value or \\\"\\\").strip()\\n    if not text:\\n        msg = f\\\"{label} is required.\\\"\\n        raise ValueError(msg)\\n    if not _TOKEN_RE.match(text):\\n        msg = f\\\"{label} contains unsupported characters: {text!r}\\\"\\n        raise ValueError(msg)\\n    return text\\n\\n\\ndef basic_auth_header(api_key: str, api_secret: str) -> str:\\n    \\\"\\\"\\\"Build the ``Authorization: Basic ...`` value Confluent Cloud expects for API-key auth.\\\"\\\"\\\"\\n    key = (api_key or \\\"\\\").strip()\\n    secret = (api_secret or \\\"\\\").strip()\\n    if not key or not secret:\\n        msg = \\\"Both the API key and the API secret are required.\\\"\\n        raise ValueError(msg)\\n    token = base64.b64encode(f\\\"{key}:{secret}\\\".encode()).decode(\\\"ascii\\\")\\n    return f\\\"Basic {token}\\\"\\n\\n\\ndef ensure_url_allowed(url: str) -> str:\\n    \\\"\\\"\\\"SSRF-validate a tenant-supplied http(s) URL and return it stripped.\\\"\\\"\\\"\\n    text = (url or \\\"\\\").strip()\\n    if not text:\\n        msg = \\\"An endpoint URL is required.\\\"\\n        raise ValueError(msg)\\n    validate_connector_url_for_ssrf(text)\\n    return text\\n\\n\\ndef context_engine_url(\\n    region: str,\\n    organization_id: str,\\n    environment_id: str,\\n    kafka_cluster_id: str,\\n    cloud: str = DEFAULT_CLOUD,\\n) -> str:\\n    \\\"\\\"\\\"Return the Real-Time Context Engine MCP endpoint for a Kafka cluster.\\n\\n    Pattern documented by Confluent::\\n\\n        https://mcp.<REGION>.<CLOUD>.confluent.cloud/mcp/v1/context-engine/\\n            organizations/<ORG>/environments/<ENV>/kafka-clusters/<LKC>\\n    \\\"\\\"\\\"\\n    region_ = require_token(region, \\\"Region\\\")\\n    cloud_ = require_token(cloud, \\\"Cloud\\\")\\n    org = require_token(organization_id, \\\"Organization ID\\\")\\n    env = require_token(environment_id, \\\"Environment ID\\\")\\n    lkc = require_token(kafka_cluster_id, \\\"Kafka cluster ID\\\")\\n    return (\\n        f\\\"https://mcp.{region_}.{cloud_}.confluent.cloud/mcp/v1/context-engine/\\\"\\n        f\\\"organizations/{org}/environments/{env}/kafka-clusters/{lkc}\\\"\\n    )\\n\\n\\ndef tableflow_catalog_url(\\n    region: str,\\n    organization_id: str,\\n    environment_id: str,\\n    cloud: str = DEFAULT_CLOUD,\\n) -> str:\\n    \\\"\\\"\\\"Return the Tableflow Iceberg REST catalog endpoint for an environment.\\n\\n    Pattern documented by Confluent::\\n\\n        https://tableflow.<REGION>.<CLOUD>.confluent.cloud/iceberg/catalog/\\n            organizations/<ORG>/environments/<ENV>\\n    \\\"\\\"\\\"\\n    region_ = require_token(region, \\\"Region\\\")\\n    cloud_ = require_token(cloud, \\\"Cloud\\\")\\n    org = require_token(organization_id, \\\"Organization ID\\\")\\n    env = require_token(environment_id, \\\"Environment ID\\\")\\n    return (\\n        f\\\"https://tableflow.{region_}.{cloud_}.confluent.cloud/iceberg/catalog/organizations/{org}/environments/{env}\\\"\\n    )\\n\\n\\n# ``extra`` client settings are tenant-supplied (and reachable from Tool Mode), so they\\n# must not be able to re-point the client at another broker after the bootstrap list has\\n# been SSRF-gated, nor downgrade the transport or swap the SASL credentials.\\nPROTECTED_KAFKA_CONFIG_KEYS = frozenset(\\n    {\\n        \\\"bootstrap.servers\\\",\\n        \\\"metadata.broker.list\\\",\\n        \\\"security.protocol\\\",\\n    }\\n)\\n_PROTECTED_KAFKA_CONFIG_PREFIXES = (\\\"sasl.\\\", \\\"ssl.\\\")\\n\\n\\ndef _is_protected_kafka_key(key: str) -> bool:\\n    \\\"\\\"\\\"Return True for connection / transport / credential settings ``extra`` may not set.\\\"\\\"\\\"\\n    name = (key or \\\"\\\").strip().lower()\\n    return name in PROTECTED_KAFKA_CONFIG_KEYS or name.startswith(_PROTECTED_KAFKA_CONFIG_PREFIXES)\\n\\n\\ndef parse_bootstrap_servers(bootstrap_servers: str) -> list[tuple[str, int]]:\\n    \\\"\\\"\\\"Split ``host:port,host:port`` into validated ``(host, port)`` pairs.\\\"\\\"\\\"\\n    text = (bootstrap_servers or \\\"\\\").strip()\\n    if not text:\\n        msg = \\\"Bootstrap servers are required (for example 'pkc-xxxxx.us-east-1.aws.confluent.cloud:9092').\\\"\\n        raise ValueError(msg)\\n    pairs: list[tuple[str, int]] = []\\n    for raw in text.split(\\\",\\\"):\\n        item = raw.strip()\\n        if not item:\\n            continue\\n        host, sep, port_text = item.rpartition(\\\":\\\")\\n        if not sep or not host:\\n            host, port = item, KAFKA_DEFAULT_PORT\\n        else:\\n            try:\\n                port = int(port_text)\\n            except ValueError as exc:\\n                msg = f\\\"Invalid bootstrap server port in {item!r}.\\\"\\n                raise ValueError(msg) from exc\\n        if not (0 < port <= MAX_PORT):\\n            msg = f\\\"Invalid bootstrap server port in {item!r}.\\\"\\n            raise ValueError(msg)\\n        pairs.append((host, port))\\n    if not pairs:\\n        msg = \\\"Bootstrap servers are required.\\\"\\n        raise ValueError(msg)\\n    return pairs\\n\\n\\ndef validate_bootstrap_servers(bootstrap_servers: str) -> str:\\n    \\\"\\\"\\\"SSRF-gate every bootstrap host and return the normalized ``host:port`` list.\\n\\n    Kafka bootstrap strings have no URL scheme, so each host is validated as\\n    an ``https://host:port`` URL -- the connector policy only looks at the host,\\n    which is what matters (cloud-metadata endpoints, RFC1918 literals, ...).\\n    \\\"\\\"\\\"\\n    pairs = parse_bootstrap_servers(bootstrap_servers)\\n    for host, port in pairs:\\n        validate_connector_url_for_ssrf(f\\\"https://{host}:{port}\\\")\\n    return \\\",\\\".join(f\\\"{host}:{port}\\\" for host, port in pairs)\\n\\n\\ndef kafka_client_config(\\n    bootstrap_servers: str,\\n    api_key: str,\\n    api_secret: str,\\n    extra: dict | None = None,\\n) -> dict:\\n    \\\"\\\"\\\"Return a ``confluent_kafka`` client config for Confluent Cloud (SASL_SSL / PLAIN).\\n\\n    ``bootstrap_servers`` must already have passed :func:`validate_bootstrap_servers`.\\n    ``extra`` may tune the client (batching, timeouts, ...) but never the connection,\\n    transport or credentials -- see :data:`PROTECTED_KAFKA_CONFIG_KEYS`.\\n    \\\"\\\"\\\"\\n    key = (api_key or \\\"\\\").strip()\\n    secret = (api_secret or \\\"\\\").strip()\\n    config: dict = {\\\"bootstrap.servers\\\": bootstrap_servers}\\n    if key or secret:\\n        if not key or not secret:\\n            msg = \\\"Both the Kafka API key and the API secret are required for SASL authentication.\\\"\\n            raise ValueError(msg)\\n        config.update(\\n            {\\n                \\\"security.protocol\\\": \\\"SASL_SSL\\\",\\n                \\\"sasl.mechanisms\\\": \\\"PLAIN\\\",\\n                \\\"sasl.username\\\": key,\\n                \\\"sasl.password\\\": secret,\\n            }\\n        )\\n    if extra:\\n        protected = sorted(k for k in extra if _is_protected_kafka_key(k))\\n        if protected:\\n            msg = (\\n                \\\"Extra Client Config cannot override the connection, transport or credential settings: \\\"\\n                f\\\"{', '.join(protected)}.\\\"\\n            )\\n            raise ValueError(msg)\\n        config.update({k: v for k, v in extra.items() if k and v is not None})\\n    return config\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/confluent/src/lfx_confluent/components/confluent/context_engine.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"588237a8d4e7daf24f703da30165cb4afdda688cbe4833bc68ac97f6b41f425b\",\"content\":\"\\\"\\\"\\\"Confluent Real-Time Context Engine as an Agent toolset.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom typing import Any\\n\\nfrom lfx.base.mcp.preset import MCPPresetComponent, preset_control_inputs\\nfrom lfx.io import SecretStrInput, StrInput\\nfrom lfx_confluent.components.confluent._common import (\\n    DEFAULT_CLOUD,\\n    DEFAULT_REGION,\\n    basic_auth_header,\\n    context_engine_url,\\n    ensure_url_allowed,\\n)\\n\\n# Tool names documented by Confluent for the Real-Time Context Engine MCP server.\\nCONTEXT_ENGINE_TOOLS = [\\\"list_topics\\\", \\\"get_metadata\\\", \\\"query_data\\\"]\\n\\n\\nclass ConfluentContextEngineComponent(MCPPresetComponent):\\n    \\\"\\\"\\\"Serve fresh, governed Kafka topic data to an Agent through the Real-Time Context Engine.\\n\\n    Confluent's Real-Time Context Engine materializes schema'd Kafka topics into\\n    a low-latency serving layer and exposes it as an MCP server with three\\n    tools -- ``list_topics``, ``get_metadata`` and ``query_data`` (key lookups,\\n    filters, ranges and compound predicates).  This component templates the\\n    regional endpoint from your Confluent Cloud IDs, authenticates with a\\n    Confluent Cloud API key, and hands the tools to an Agent.\\n    \\\"\\\"\\\"\\n\\n    display_name = \\\"Confluent Real-Time Context Engine\\\"\\n    description = (\\n        \\\"Give an Agent live, governed context from Kafka topics through Confluent's \\\"\\n        \\\"Real-Time Context Engine (MCP): list topics, inspect schemas, and query the latest data.\\\"\\n    )\\n    documentation: str = \\\"https://docs.langflow.org/bundles-confluent\\\"\\n    icon = \\\"Confluent\\\"\\n    name = \\\"ConfluentContextEngine\\\"\\n    metadata = {\\\"keywords\\\": [\\\"confluent\\\", \\\"kafka\\\", \\\"context engine\\\", \\\"mcp\\\", \\\"real-time\\\", \\\"streaming\\\", \\\"ibm\\\"]}\\n\\n    inputs = [\\n        StrInput(\\n            name=\\\"region\\\",\\n            display_name=\\\"Cloud Region\\\",\\n            info=\\\"Confluent Cloud region of the Kafka cluster (for example us-east-1). AWS regions only today.\\\",\\n            value=DEFAULT_REGION,\\n            required=True,\\n        ),\\n        StrInput(\\n            name=\\\"organization_id\\\",\\n            display_name=\\\"Organization ID\\\",\\n            info=\\\"Confluent Cloud organization ID (from Organization settings).\\\",\\n            required=True,\\n        ),\\n        StrInput(\\n            name=\\\"environment_id\\\",\\n            display_name=\\\"Environment ID\\\",\\n            info=\\\"Confluent Cloud environment ID (for example env-abc123).\\\",\\n            required=True,\\n        ),\\n        StrInput(\\n            name=\\\"kafka_cluster_id\\\",\\n            display_name=\\\"Kafka Cluster ID\\\",\\n            info=\\\"Kafka cluster ID (for example lkc-abc123) whose topics have the Context Engine enabled.\\\",\\n            required=True,\\n        ),\\n        SecretStrInput(\\n            name=\\\"api_key\\\",\\n            display_name=\\\"API Key\\\",\\n            info=\\\"Confluent Cloud Global API key with read access to the cluster and Schema Registry.\\\",\\n            required=True,\\n        ),\\n        SecretStrInput(\\n            name=\\\"api_secret\\\",\\n            display_name=\\\"API Secret\\\",\\n            info=\\\"Secret paired with the API key.\\\",\\n            required=True,\\n        ),\\n        StrInput(\\n            name=\\\"endpoint_override\\\",\\n            display_name=\\\"Endpoint Override\\\",\\n            info=(\\n                \\\"Full MCP endpoint URL. Leave empty to build it from the region and IDs; set it when \\\"\\n                \\\"Confluent publishes a different host for your cloud provider or region.\\\"\\n            ),\\n            advanced=True,\\n        ),\\n        StrInput(\\n            name=\\\"cloud\\\",\\n            display_name=\\\"Cloud Provider\\\",\\n            info=\\\"Cloud provider segment of the endpoint host. The Context Engine is available on AWS today.\\\",\\n            value=DEFAULT_CLOUD,\\n            advanced=True,\\n        ),\\n        *preset_control_inputs(\\n            CONTEXT_ENGINE_TOOLS,\\n            tool_info=(\\n                \\\"Tool to run for the Response output. In Tool Mode all three tools are exposed to the \\\"\\n                \\\"Agent. Use the refresh button to re-read the tool list from the server.\\\"\\n            ),\\n        ),\\n    ]\\n\\n    def endpoint_url(self) -> str:\\n        override = (getattr(self, \\\"endpoint_override\\\", \\\"\\\") or \\\"\\\").strip()\\n        if override:\\n            return ensure_url_allowed(override)\\n        url = context_engine_url(\\n            self.region,\\n            self.organization_id,\\n            self.environment_id,\\n            self.kafka_cluster_id,\\n            cloud=getattr(self, \\\"cloud\\\", DEFAULT_CLOUD) or DEFAULT_CLOUD,\\n        )\\n        return ensure_url_allowed(url)\\n\\n    def _mcp_server_config(self) -> tuple[str, dict[str, Any]]:\\n        url = self.endpoint_url()\\n        headers = {\\\"Authorization\\\": basic_auth_header(self.api_key, self.api_secret)}\\n        server_name = f\\\"confluent-context-engine-{(self.kafka_cluster_id or '').strip() or 'cluster'}\\\"\\n        return server_name, {\\n            \\\"url\\\": url,\\n            \\\"headers\\\": headers,\\n            \\\"mode\\\": \\\"Streamable_HTTP\\\",\\n            \\\"verify_ssl\\\": bool(getattr(self, \\\"verify_ssl\\\", True)),\\n        }\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/confluent/src/lfx_confluent/components/confluent/kafka_consumer.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"4f48a347c2d7e9f3febed618526ac9f9b83713512386c96967acf5577c599e5d\",\"content\":\"\\\"\\\"\\\"Read a bounded batch of Kafka records from Confluent Cloud / Platform into a DataFrame.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport asyncio\\nimport json\\nimport time\\nfrom typing import Any\\n\\nfrom lfx.custom.custom_component.component import Component\\nfrom lfx.io import (\\n    BoolInput,\\n    DictInput,\\n    DropdownInput,\\n    FloatInput,\\n    IntInput,\\n    MessageTextInput,\\n    Output,\\n    SecretStrInput,\\n    StrInput,\\n)\\nfrom lfx.log.logger import logger\\nfrom lfx.schema.dataframe import DataFrame\\nfrom lfx_confluent.components.confluent._common import (\\n    ensure_url_allowed,\\n    kafka_client_config,\\n    validate_bootstrap_servers,\\n)\\n\\nVALUE_FORMAT_JSON = \\\"json\\\"\\nVALUE_FORMAT_STRING = \\\"string\\\"\\nVALUE_FORMAT_AVRO = \\\"avro\\\"\\nVALUE_FORMAT_JSON_SCHEMA = \\\"json_schema\\\"\\nVALUE_FORMATS = [VALUE_FORMAT_JSON, VALUE_FORMAT_STRING, VALUE_FORMAT_AVRO, VALUE_FORMAT_JSON_SCHEMA]\\nSCHEMA_REGISTRY_FORMATS = {VALUE_FORMAT_AVRO, VALUE_FORMAT_JSON_SCHEMA}\\n\\nOFFSET_RESET_OPTIONS = [\\\"latest\\\", \\\"earliest\\\"]\\nMAX_MESSAGES_CAP = 10_000\\nMAX_TIMEOUT_SECONDS = 300.0\\nPOLL_SLICE_SECONDS = 1.0\\n\\n\\nclass ConfluentKafkaConsumerComponent(Component):\\n    \\\"\\\"\\\"Consume up to N records (or until a timeout) from one or more topics.\\\"\\\"\\\"\\n\\n    display_name = \\\"Confluent Kafka Consumer\\\"\\n    description = (\\n        \\\"Read a bounded batch of records from Kafka topics on Confluent Cloud or Confluent Platform \\\"\\n        \\\"into a DataFrame (one row per record). Stops at the message limit or the timeout.\\\"\\n    )\\n    documentation: str = \\\"https://docs.langflow.org/bundles-confluent\\\"\\n    icon = \\\"Confluent\\\"\\n    name = \\\"ConfluentKafkaConsumer\\\"\\n    metadata = {\\\"keywords\\\": [\\\"confluent\\\", \\\"kafka\\\", \\\"consumer\\\", \\\"subscribe\\\", \\\"topic\\\", \\\"streaming\\\", \\\"ibm\\\"]}\\n\\n    inputs = [\\n        StrInput(\\n            name=\\\"bootstrap_servers\\\",\\n            display_name=\\\"Bootstrap Servers\\\",\\n            info=\\\"Comma-separated host:port list, for example pkc-xxxxx.us-east-1.aws.confluent.cloud:9092.\\\",\\n            required=True,\\n        ),\\n        SecretStrInput(\\n            name=\\\"api_key\\\",\\n            display_name=\\\"API Key\\\",\\n            info=\\\"Kafka cluster API key (SASL/PLAIN username). Leave empty for an unauthenticated broker.\\\",\\n        ),\\n        SecretStrInput(\\n            name=\\\"api_secret\\\",\\n            display_name=\\\"API Secret\\\",\\n            info=\\\"Kafka cluster API secret (SASL/PLAIN password).\\\",\\n        ),\\n        MessageTextInput(\\n            name=\\\"topics\\\",\\n            display_name=\\\"Topics\\\",\\n            info=\\\"Comma-separated topic names to subscribe to.\\\",\\n            required=True,\\n            tool_mode=True,\\n        ),\\n        StrInput(\\n            name=\\\"group_id\\\",\\n            display_name=\\\"Consumer Group ID\\\",\\n            info=\\\"Consumer group used to track offsets. Leave empty to derive one from the flow ID.\\\",\\n        ),\\n        IntInput(\\n            name=\\\"max_messages\\\",\\n            display_name=\\\"Max Messages\\\",\\n            info=f\\\"Stop after this many records (capped at {MAX_MESSAGES_CAP}).\\\",\\n            value=100,\\n            range_spec={\\\"min\\\": 1, \\\"max\\\": MAX_MESSAGES_CAP, \\\"step\\\": 1},\\n            tool_mode=True,\\n        ),\\n        FloatInput(\\n            name=\\\"timeout_seconds\\\",\\n            display_name=\\\"Timeout (seconds)\\\",\\n            info=f\\\"Stop waiting for more records after this long (capped at {MAX_TIMEOUT_SECONDS:g}s).\\\",\\n            value=5.0,\\n            range_spec={\\\"min\\\": 0.5, \\\"max\\\": MAX_TIMEOUT_SECONDS, \\\"step\\\": 0.5},\\n        ),\\n        DropdownInput(\\n            name=\\\"auto_offset_reset\\\",\\n            display_name=\\\"Start From\\\",\\n            options=OFFSET_RESET_OPTIONS,\\n            value=\\\"latest\\\",\\n            info=\\\"Where a new consumer group starts: latest (only new records) or earliest (from the beginning).\\\",\\n            advanced=True,\\n        ),\\n        BoolInput(\\n            name=\\\"commit_offsets\\\",\\n            display_name=\\\"Commit Offsets\\\",\\n            info=\\\"Commit the consumed offsets so the next run continues where this one stopped.\\\",\\n            value=True,\\n            advanced=True,\\n        ),\\n        DropdownInput(\\n            name=\\\"value_format\\\",\\n            display_name=\\\"Value Format\\\",\\n            options=VALUE_FORMATS,\\n            value=VALUE_FORMAT_JSON,\\n            info=(\\n                \\\"json: parse UTF-8 JSON (falls back to text). string: raw text. avro / json_schema: decode \\\"\\n                \\\"with Confluent Schema Registry (requires the Schema Registry fields).\\\"\\n            ),\\n            real_time_refresh=True,\\n            advanced=True,\\n        ),\\n        StrInput(\\n            name=\\\"schema_registry_url\\\",\\n            display_name=\\\"Schema Registry URL\\\",\\n            info=\\\"Schema Registry endpoint, for example https://psrc-xxxxx.us-east-2.aws.confluent.cloud.\\\",\\n            advanced=True,\\n            show=False,\\n        ),\\n        SecretStrInput(\\n            name=\\\"schema_registry_key\\\",\\n            display_name=\\\"Schema Registry API Key\\\",\\n            advanced=True,\\n            show=False,\\n        ),\\n        SecretStrInput(\\n            name=\\\"schema_registry_secret\\\",\\n            display_name=\\\"Schema Registry API Secret\\\",\\n            advanced=True,\\n            show=False,\\n        ),\\n        DictInput(\\n            name=\\\"client_config\\\",\\n            display_name=\\\"Extra Client Config\\\",\\n            info=\\\"Additional librdkafka consumer settings.\\\",\\n            advanced=True,\\n            is_list=True,\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(display_name=\\\"Records\\\", name=\\\"records\\\", method=\\\"consume\\\"),\\n    ]\\n\\n    # ------------------------------------------------------------ build cfg\\n    def update_build_config(self, build_config: dict, field_value: Any, field_name: str | None = None) -> dict:\\n        if field_name == \\\"value_format\\\":\\n            needs_registry = field_value in SCHEMA_REGISTRY_FORMATS\\n            for key in (\\\"schema_registry_url\\\", \\\"schema_registry_key\\\", \\\"schema_registry_secret\\\"):\\n                if key in build_config:\\n                    build_config[key][\\\"show\\\"] = needs_registry\\n                    build_config[key][\\\"advanced\\\"] = not needs_registry\\n        return build_config\\n\\n    # ------------------------------------------------------------- helpers\\n    def _resolved_group_id(self) -> str:\\n        explicit = (getattr(self, \\\"group_id\\\", \\\"\\\") or \\\"\\\").strip()\\n        if explicit:\\n            return explicit\\n        try:\\n            flow_id = self.flow_id\\n        except Exception:  # noqa: BLE001 - no graph bound (e.g. unit tests); fall back to a stable name\\n            flow_id = None\\n        return f\\\"langflow-{flow_id}\\\" if flow_id else \\\"langflow-consumer\\\"\\n\\n    def _topic_list(self) -> list[str]:\\n        topics = [t.strip() for t in (self.topics or \\\"\\\").split(\\\",\\\") if t.strip()]\\n        if not topics:\\n            msg = \\\"At least one topic is required.\\\"\\n            raise ValueError(msg)\\n        return topics\\n\\n    def _bounds(self) -> tuple[int, float]:\\n        max_messages = int(getattr(self, \\\"max_messages\\\", 100) or 100)\\n        max_messages = max(1, min(max_messages, MAX_MESSAGES_CAP))\\n        timeout = float(getattr(self, \\\"timeout_seconds\\\", 5.0) or 5.0)\\n        timeout = max(0.5, min(timeout, MAX_TIMEOUT_SECONDS))\\n        return max_messages, timeout\\n\\n    def _value_deserializer(self):\\n        \\\"\\\"\\\"Return ``callable(topic, raw_bytes) -> Any`` for the configured value format.\\\"\\\"\\\"\\n        value_format = getattr(self, \\\"value_format\\\", VALUE_FORMAT_JSON) or VALUE_FORMAT_JSON\\n\\n        if value_format == VALUE_FORMAT_STRING:\\n            return lambda _topic, raw: raw.decode(\\\"utf-8\\\", errors=\\\"replace\\\") if raw is not None else None\\n\\n        if value_format == VALUE_FORMAT_JSON:\\n\\n            def decode_json(_topic: str, raw: bytes | None) -> Any:\\n                if raw is None:\\n                    return None\\n                text = raw.decode(\\\"utf-8\\\", errors=\\\"replace\\\")\\n                try:\\n                    return json.loads(text)\\n                except json.JSONDecodeError:\\n                    return text\\n\\n            return decode_json\\n\\n        # Schema Registry-backed formats.\\n        registry_url = ensure_url_allowed(getattr(self, \\\"schema_registry_url\\\", \\\"\\\") or \\\"\\\")\\n        try:\\n            from confluent_kafka.schema_registry import SchemaRegistryClient\\n            from confluent_kafka.serialization import MessageField, SerializationContext\\n        except ImportError as exc:  # pragma: no cover\\n            msg = (\\n                \\\"confluent-kafka Schema Registry support is not installed \\\"\\n                \\\"(pip install 'confluent-kafka[avro,json,schemaregistry]').\\\"\\n            )\\n            raise ImportError(msg) from exc\\n\\n        registry_config: dict[str, Any] = {\\\"url\\\": registry_url}\\n        sr_key = (getattr(self, \\\"schema_registry_key\\\", \\\"\\\") or \\\"\\\").strip()\\n        sr_secret = (getattr(self, \\\"schema_registry_secret\\\", \\\"\\\") or \\\"\\\").strip()\\n        if sr_key or sr_secret:\\n            if not sr_key or not sr_secret:\\n                msg = \\\"Both the Schema Registry API key and secret are required.\\\"\\n                raise ValueError(msg)\\n            registry_config[\\\"basic.auth.user.info\\\"] = f\\\"{sr_key}:{sr_secret}\\\"\\n        client = SchemaRegistryClient(registry_config)\\n\\n        if value_format == VALUE_FORMAT_AVRO:\\n            from confluent_kafka.schema_registry.avro import AvroDeserializer\\n\\n            deserializer = AvroDeserializer(client)\\n        elif value_format == VALUE_FORMAT_JSON_SCHEMA:\\n            from confluent_kafka.schema_registry.json_schema import JSONDeserializer\\n\\n            deserializer = JSONDeserializer(None, schema_registry_client=client)\\n        else:\\n            msg = f\\\"Unsupported value format: {value_format!r}\\\"\\n            raise ValueError(msg)\\n\\n        def decode_registry(topic: str, raw: bytes | None) -> Any:\\n            if raw is None:\\n                return None\\n            return deserializer(raw, SerializationContext(topic, MessageField.VALUE))\\n\\n        return decode_registry\\n\\n    @staticmethod\\n    def _row_from_message(msg, value: Any) -> dict[str, Any]:\\n        ts_type, ts_value = msg.timestamp()\\n        key = msg.key()\\n        headers = msg.headers() or []\\n        row: dict[str, Any] = {\\n            \\\"topic\\\": msg.topic(),\\n            \\\"partition\\\": msg.partition(),\\n            \\\"offset\\\": msg.offset(),\\n            \\\"timestamp\\\": ts_value if ts_type else None,\\n            \\\"key\\\": key.decode(\\\"utf-8\\\", errors=\\\"replace\\\") if isinstance(key, bytes) else key,\\n            \\\"headers\\\": {k: (v.decode(\\\"utf-8\\\", errors=\\\"replace\\\") if isinstance(v, bytes) else v) for k, v in headers}\\n            if headers\\n            else None,\\n        }\\n        if isinstance(value, dict):\\n            # Promote record fields to columns; keep the raw object under \\\"value\\\" too.\\n            for k, v in value.items():\\n                row.setdefault(str(k), v)\\n            row[\\\"value\\\"] = value\\n        else:\\n            row[\\\"value\\\"] = value\\n        return row\\n\\n    # -------------------------------------------------------------- consume\\n    def _consume_sync(\\n        self, config: dict, topics: list[str], max_messages: int, timeout: float, *, commit: bool\\n    ) -> list[dict]:\\n        try:\\n            from confluent_kafka import Consumer, KafkaError, KafkaException\\n        except ImportError as exc:  # pragma: no cover - exercised on platforms without the wheel\\n            msg = \\\"confluent-kafka is not installed. Install the lfx-confluent bundle with its dependencies.\\\"\\n            raise ImportError(msg) from exc\\n\\n        decode = self._value_deserializer()\\n        consumer = Consumer(config)\\n        rows: list[dict] = []\\n        try:\\n            consumer.subscribe(topics)\\n            deadline = time.monotonic() + timeout\\n            while len(rows) < max_messages:\\n                remaining_time = deadline - time.monotonic()\\n                if remaining_time <= 0:\\n                    break\\n                batch = consumer.consume(\\n                    num_messages=max_messages - len(rows),\\n                    timeout=min(POLL_SLICE_SECONDS, remaining_time),\\n                )\\n                for msg in batch:\\n                    err = msg.error()\\n                    if err is not None:\\n                        if err.code() == KafkaError._PARTITION_EOF:  # noqa: SLF001 - documented librdkafka sentinel\\n                            continue\\n                        raise KafkaException(err)\\n                    try:\\n                        value = decode(msg.topic(), msg.value())\\n                    except Exception as exc:  # noqa: BLE001 - keep the batch, surface the decode error per row\\n                        value = None\\n                        row = self._row_from_message(msg, value)\\n                        row[\\\"decode_error\\\"] = str(exc)\\n                        rows.append(row)\\n                        continue\\n                    rows.append(self._row_from_message(msg, value))\\n            if commit and rows:\\n                consumer.commit(asynchronous=False)\\n        except KafkaException as exc:\\n            msg = f\\\"Kafka consume failed: {exc}\\\"\\n            raise ValueError(msg) from exc\\n        finally:\\n            consumer.close()\\n        return rows\\n\\n    async def consume(self) -> DataFrame:\\n        bootstrap = validate_bootstrap_servers(self.bootstrap_servers)\\n        topics = self._topic_list()\\n        max_messages, timeout = self._bounds()\\n        extra = getattr(self, \\\"client_config\\\", None) or {}\\n        if isinstance(extra, list):\\n            merged: dict[str, Any] = {}\\n            for item in extra:\\n                if isinstance(item, dict):\\n                    merged.update(item)\\n            extra = merged\\n        base = {\\n            \\\"group.id\\\": self._resolved_group_id(),\\n            \\\"auto.offset.reset\\\": getattr(self, \\\"auto_offset_reset\\\", \\\"latest\\\") or \\\"latest\\\",\\n            \\\"enable.auto.commit\\\": False,\\n        }\\n        base.update(extra)\\n        config = kafka_client_config(bootstrap, self.api_key, self.api_secret, extra=base)\\n        commit = bool(getattr(self, \\\"commit_offsets\\\", True))\\n        rows = await asyncio.to_thread(self._consume_sync, config, topics, max_messages, timeout, commit=commit)\\n        frame = DataFrame(rows)\\n        self.status = f\\\"Consumed {len(rows)} record(s) from {', '.join(topics)}\\\"\\n        if not rows:\\n            await logger.adebug(f\\\"Kafka consumer read no records from {topics} within {timeout}s\\\")\\n        return frame\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/confluent/src/lfx_confluent/components/confluent/kafka_producer.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"11f5a365af777b6e6a34cfad6f12521a7ad068abbbaeed3d54690ab4e7785348\",\"content\":\"\\\"\\\"\\\"Publish flow results to a Kafka topic on Confluent Cloud / Platform.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport asyncio\\nimport json\\nfrom typing import Any\\n\\nfrom lfx.custom.custom_component.component import Component\\nfrom lfx.io import DictInput, DropdownInput, HandleInput, IntInput, MessageTextInput, Output, SecretStrInput, StrInput\\nfrom lfx.schema.data import Data\\nfrom lfx.schema.dataframe import DataFrame\\nfrom lfx.schema.message import Message\\nfrom lfx_confluent.components.confluent._common import kafka_client_config, validate_bootstrap_servers\\n\\nSERIALIZATION_JSON = \\\"json\\\"\\nSERIALIZATION_STRING = \\\"string\\\"\\nMIN_FLUSH_TIMEOUT_SECONDS = 1\\nMAX_FLUSH_TIMEOUT_SECONDS = 300\\n\\n\\nclass ConfluentKafkaProducerComponent(Component):\\n    \\\"\\\"\\\"Produce one or more messages to a Kafka topic and return the delivery report.\\\"\\\"\\\"\\n\\n    display_name = \\\"Confluent Kafka Producer\\\"\\n    description = (\\n        \\\"Publish a Message, Data, or every row of a DataFrame to a Kafka topic on Confluent \\\"\\n        \\\"Cloud or Confluent Platform, and return the delivery report.\\\"\\n    )\\n    documentation: str = \\\"https://docs.langflow.org/bundles-confluent\\\"\\n    icon = \\\"Confluent\\\"\\n    name = \\\"ConfluentKafkaProducer\\\"\\n    metadata = {\\\"keywords\\\": [\\\"confluent\\\", \\\"kafka\\\", \\\"producer\\\", \\\"publish\\\", \\\"topic\\\", \\\"streaming\\\", \\\"ibm\\\"]}\\n\\n    inputs = [\\n        StrInput(\\n            name=\\\"bootstrap_servers\\\",\\n            display_name=\\\"Bootstrap Servers\\\",\\n            info=\\\"Comma-separated host:port list, for example pkc-xxxxx.us-east-1.aws.confluent.cloud:9092.\\\",\\n            required=True,\\n        ),\\n        SecretStrInput(\\n            name=\\\"api_key\\\",\\n            display_name=\\\"API Key\\\",\\n            info=\\\"Kafka cluster API key (SASL/PLAIN username). Leave empty for an unauthenticated broker.\\\",\\n        ),\\n        SecretStrInput(\\n            name=\\\"api_secret\\\",\\n            display_name=\\\"API Secret\\\",\\n            info=\\\"Kafka cluster API secret (SASL/PLAIN password).\\\",\\n        ),\\n        MessageTextInput(\\n            name=\\\"topic\\\",\\n            display_name=\\\"Topic\\\",\\n            info=\\\"Topic to publish to.\\\",\\n            required=True,\\n            tool_mode=True,\\n        ),\\n        HandleInput(\\n            name=\\\"message\\\",\\n            display_name=\\\"Message\\\",\\n            info=(\\n                \\\"What to publish. A Message publishes its text; a Data object publishes its JSON; \\\"\\n                \\\"a DataFrame publishes one record per row.\\\"\\n            ),\\n            input_types=[\\\"Message\\\", \\\"Data\\\", \\\"DataFrame\\\"],\\n            required=True,\\n        ),\\n        MessageTextInput(\\n            name=\\\"key\\\",\\n            display_name=\\\"Message Key\\\",\\n            info=\\\"Optional record key. Records with the same key land on the same partition.\\\",\\n            tool_mode=True,\\n        ),\\n        DropdownInput(\\n            name=\\\"serialization\\\",\\n            display_name=\\\"Value Serialization\\\",\\n            options=[SERIALIZATION_JSON, SERIALIZATION_STRING],\\n            value=SERIALIZATION_JSON,\\n            info=\\\"json: publish objects as UTF-8 JSON. string: publish the text as-is.\\\",\\n            advanced=True,\\n        ),\\n        DictInput(\\n            name=\\\"headers\\\",\\n            display_name=\\\"Record Headers\\\",\\n            info=\\\"Optional Kafka record headers added to every published record.\\\",\\n            advanced=True,\\n            is_list=True,\\n        ),\\n        IntInput(\\n            name=\\\"flush_timeout\\\",\\n            display_name=\\\"Flush Timeout (seconds)\\\",\\n            info=(\\n                \\\"How long to wait for the broker to acknowledge the records \\\"\\n                f\\\"(clamped to {MIN_FLUSH_TIMEOUT_SECONDS}-{MAX_FLUSH_TIMEOUT_SECONDS}s).\\\"\\n            ),\\n            value=10,\\n            range_spec={\\\"min\\\": MIN_FLUSH_TIMEOUT_SECONDS, \\\"max\\\": MAX_FLUSH_TIMEOUT_SECONDS, \\\"step\\\": 1},\\n            advanced=True,\\n        ),\\n        DictInput(\\n            name=\\\"client_config\\\",\\n            display_name=\\\"Extra Client Config\\\",\\n            info=\\\"Additional librdkafka producer settings, for example {'acks': 'all'}.\\\",\\n            advanced=True,\\n            is_list=True,\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(display_name=\\\"Delivery Report\\\", name=\\\"delivery_report\\\", method=\\\"produce\\\"),\\n    ]\\n\\n    # ----------------------------------------------------------- payloads\\n    def _records(self) -> list[dict[str, Any]]:\\n        \\\"\\\"\\\"Turn the connected input into a list of ``{\\\"key\\\", \\\"value\\\"}`` records.\\\"\\\"\\\"\\n        payload = self.message\\n        base_key = (getattr(self, \\\"key\\\", \\\"\\\") or \\\"\\\").strip() or None\\n        serialization = getattr(self, \\\"serialization\\\", SERIALIZATION_JSON) or SERIALIZATION_JSON\\n\\n        def encode(value: Any) -> bytes:\\n            if serialization == SERIALIZATION_STRING or isinstance(value, str):\\n                return str(value).encode(\\\"utf-8\\\")\\n            return json.dumps(value, ensure_ascii=False, default=str).encode(\\\"utf-8\\\")\\n\\n        if isinstance(payload, DataFrame):\\n            rows = payload.to_dict(orient=\\\"records\\\")\\n            return [{\\\"key\\\": base_key, \\\"value\\\": encode(row)} for row in rows]\\n        if isinstance(payload, Message):\\n            text = payload.text if payload.text is not None else \\\"\\\"\\n            return [{\\\"key\\\": base_key, \\\"value\\\": encode(text)}]\\n        if isinstance(payload, Data):\\n            data = payload.data if isinstance(payload.data, dict) else {\\\"data\\\": payload.data}\\n            return [{\\\"key\\\": base_key, \\\"value\\\": encode(data)}]\\n        if isinstance(payload, list):\\n            return [\\n                {\\\"key\\\": base_key, \\\"value\\\": encode(item.data if isinstance(item, Data) else item)} for item in payload\\n            ]\\n        if payload is None or payload == \\\"\\\":\\n            msg = \\\"Connect a Message, Data, or DataFrame to publish.\\\"\\n            raise ValueError(msg)\\n        return [{\\\"key\\\": base_key, \\\"value\\\": encode(payload)}]\\n\\n    def _record_headers(self) -> list[tuple[str, bytes]] | None:\\n        raw = getattr(self, \\\"headers\\\", None) or {}\\n        if isinstance(raw, list):\\n            merged: dict[str, Any] = {}\\n            for item in raw:\\n                if isinstance(item, dict):\\n                    merged.update(item)\\n            raw = merged\\n        if not isinstance(raw, dict) or not raw:\\n            return None\\n        return [(str(k), str(v).encode(\\\"utf-8\\\")) for k, v in raw.items() if k]\\n\\n    # -------------------------------------------------------------- produce\\n    def _produce_sync(\\n        self, config: dict, topic: str, records: list[dict[str, Any]], flush_timeout: float\\n    ) -> list[dict]:\\n        try:\\n            from confluent_kafka import KafkaError, KafkaException, Producer\\n        except ImportError as exc:  # pragma: no cover - exercised on platforms without the wheel\\n            msg = \\\"confluent-kafka is not installed. Install the lfx-confluent bundle with its dependencies.\\\"\\n            raise ImportError(msg) from exc\\n\\n        producer = Producer(config)\\n        reports: list[dict] = []\\n        headers = self._record_headers()\\n\\n        def on_delivery(err: KafkaError | None, msg) -> None:\\n            if err is not None:\\n                reports.append({\\\"topic\\\": topic, \\\"error\\\": str(err), \\\"delivered\\\": False})\\n                return\\n            ts_type, ts_value = msg.timestamp()\\n            reports.append(\\n                {\\n                    \\\"topic\\\": msg.topic(),\\n                    \\\"partition\\\": msg.partition(),\\n                    \\\"offset\\\": msg.offset(),\\n                    \\\"timestamp\\\": ts_value if ts_type else None,\\n                    \\\"key\\\": (msg.key() or b\\\"\\\").decode(\\\"utf-8\\\", errors=\\\"replace\\\") if msg.key() else None,\\n                    \\\"delivered\\\": True,\\n                }\\n            )\\n\\n        try:\\n            for record in records:\\n                key = record[\\\"key\\\"].encode(\\\"utf-8\\\") if record[\\\"key\\\"] else None\\n                producer.produce(topic, value=record[\\\"value\\\"], key=key, headers=headers, on_delivery=on_delivery)\\n                # Serve delivery callbacks eagerly so a slow broker doesn't fill the local queue.\\n                producer.poll(0)\\n            remaining = producer.flush(flush_timeout)\\n        except (KafkaException, BufferError) as exc:\\n            msg = f\\\"Kafka produce failed: {exc}\\\"\\n            raise ValueError(msg) from exc\\n        if remaining:\\n            reports.append(\\n                {\\n                    \\\"topic\\\": topic,\\n                    \\\"error\\\": f\\\"{remaining} record(s) not acknowledged within {flush_timeout}s\\\",\\n                    \\\"delivered\\\": False,\\n                }\\n            )\\n        return reports\\n\\n    def _flush_timeout(self) -> float:\\n        \\\"\\\"\\\"Return the flush timeout, clamped so it can never ask ``flush`` to wait forever.\\n\\n        ``Producer.flush`` treats a negative timeout as \\\"block until every record is\\n        acknowledged\\\", which would pin the ``asyncio.to_thread`` worker indefinitely when\\n        a broker is unreachable. ``range_spec`` only bounds the UI slider, not a value\\n        arriving from Tool Mode or the API.\\n        \\\"\\\"\\\"\\n        timeout = float(getattr(self, \\\"flush_timeout\\\", 10) or 10)\\n        return max(float(MIN_FLUSH_TIMEOUT_SECONDS), min(timeout, float(MAX_FLUSH_TIMEOUT_SECONDS)))\\n\\n    async def produce(self) -> Data:\\n        bootstrap = validate_bootstrap_servers(self.bootstrap_servers)\\n        topic = (self.topic or \\\"\\\").strip()\\n        if not topic:\\n            msg = \\\"Topic is required.\\\"\\n            raise ValueError(msg)\\n        records = self._records()\\n        extra = getattr(self, \\\"client_config\\\", None) or {}\\n        if isinstance(extra, list):\\n            merged: dict[str, Any] = {}\\n            for item in extra:\\n                if isinstance(item, dict):\\n                    merged.update(item)\\n            extra = merged\\n        config = kafka_client_config(bootstrap, self.api_key, self.api_secret, extra=extra)\\n        flush_timeout = self._flush_timeout()\\n        reports = await asyncio.to_thread(self._produce_sync, config, topic, records, flush_timeout)\\n        delivered = sum(1 for r in reports if r.get(\\\"delivered\\\"))\\n        failed = len(reports) - delivered\\n        result = Data(\\n            data={\\n                \\\"topic\\\": topic,\\n                \\\"records_sent\\\": len(records),\\n                \\\"delivered\\\": delivered,\\n                \\\"failed\\\": failed,\\n                \\\"reports\\\": reports,\\n            }\\n        )\\n        summary = f\\\"Delivered {delivered}/{len(records)} record(s) to {topic}\\\"\\n        self.status = f\\\"{summary} ({failed} failed)\\\" if failed else summary\\n        if failed and not delivered:\\n            msg = f\\\"No records were delivered to {topic}: {reports[0].get('error', 'unknown error')}\\\"\\n            raise ValueError(msg)\\n        return result\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/confluent/src/lfx_confluent/extension.json\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"abf57150cf4996889f662330dd7d20c7acdb873805ed858d05726f43c91d8fec\",\"content\":\"{\\n  \\\"$schema\\\": \\\"https://schemas.langflow.org/extension/v1.json\\\",\\n  \\\"id\\\": \\\"lfx-confluent\\\",\\n  \\\"version\\\": \\\"0.1.0\\\",\\n  \\\"name\\\": \\\"IBM Confluent\\\",\\n  \\\"description\\\": \\\"IBM Confluent components (Kafka producer/consumer, Tableflow Iceberg reader, Real-Time Context Engine MCP tools) as a standalone Langflow Extension Bundle.\\\",\\n  \\\"lfx\\\": {\\n    \\\"compat\\\": [\\\"1\\\"]\\n  },\\n  \\\"bundles\\\": [\\n    {\\n      \\\"name\\\": \\\"confluent\\\",\\n      \\\"path\\\": \\\"components/confluent\\\"\\n    }\\n  ]\\n}\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/confluent/tests/conftest.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"5cab77798797ac26a6def56296a94a2bacaf5d8b8fffad84f119ca9676c87c85\",\"content\":\"\\\"\\\"\\\"Shared fixtures for the ``lfx-confluent`` bundle tests.\\n\\nThe connector SSRF policy resolves host names through DNS, so the synthetic\\nConfluent host names used by these tests are allow-listed for the duration of\\neach test.  Literal private / metadata IPs are *not* allow-listed, so the\\nSSRF-rejection tests still exercise the real policy.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport pytest\\n\\n_TEST_HOSTS = (\\n    \\\"pkc-1.us-east-1.aws.confluent.cloud\\\",\\n    \\\"mcp.us-east-1.aws.confluent.cloud\\\",\\n    \\\"mcp.example.com\\\",\\n    \\\"tableflow.us-east-1.aws.confluent.cloud\\\",\\n    \\\"tableflow.us-west-2.aws.confluent.cloud\\\",\\n    \\\"tableflow.example.com\\\",\\n    \\\"psrc-1.us-east-2.aws.confluent.cloud\\\",\\n)\\n\\n\\n@pytest.fixture(autouse=True)\\ndef _allowlist_test_hosts(monkeypatch):\\n    monkeypatch.setenv(\\\"LANGFLOW_SSRF_ALLOWED_HOSTS\\\", \\\",\\\".join(_TEST_HOSTS))\\n    monkeypatch.setenv(\\\"LANGFLOW_CONNECTOR_SSRF_VALIDATION_ENABLED\\\", \\\"true\\\")\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/confluent/tests/test_common.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"752ebbe3c54dbde34ceb209dadcd39ba55393618c919dfa8a4089639cb877acf\",\"content\":\"\\\"\\\"\\\"Unit tests for the shared helpers of the IBM Confluent bundle (``lfx-confluent``).\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport base64\\n\\nimport pytest\\nfrom lfx.utils.ssrf_protection import SSRFProtectionError\\nfrom lfx_confluent.components.confluent import _common\\n\\n\\ndef test_basic_auth_header_encodes_key_and_secret():\\n    header = _common.basic_auth_header(\\\"key\\\", \\\"secret\\\")  # pragma: allowlist secret\\n    assert header.startswith(\\\"Basic \\\")\\n    assert base64.b64decode(header.split(\\\" \\\", 1)[1]).decode() == \\\"key:secret\\\"\\n\\n\\n@pytest.mark.parametrize((\\\"key\\\", \\\"secret\\\"), [(\\\"\\\", \\\"s\\\"), (\\\"k\\\", \\\"\\\"), (\\\"\\\", \\\"\\\")])\\ndef test_basic_auth_header_requires_both_parts(key, secret):\\n    with pytest.raises(ValueError, match=\\\"API key and the API secret\\\"):\\n        _common.basic_auth_header(key, secret)\\n\\n\\ndef test_context_engine_url_matches_confluent_pattern():\\n    url = _common.context_engine_url(\\\"us-east-1\\\", \\\"org-1\\\", \\\"env-abc\\\", \\\"lkc-xyz\\\")\\n    assert url == (\\n        \\\"https://mcp.us-east-1.aws.confluent.cloud/mcp/v1/context-engine/\\\"\\n        \\\"organizations/org-1/environments/env-abc/kafka-clusters/lkc-xyz\\\"\\n    )\\n\\n\\ndef test_tableflow_catalog_url_matches_confluent_pattern():\\n    url = _common.tableflow_catalog_url(\\\"us-west-2\\\", \\\"org-1\\\", \\\"env-abc\\\")\\n    assert (\\n        url\\n        == \\\"https://tableflow.us-west-2.aws.confluent.cloud/iceberg/catalog/organizations/org-1/environments/env-abc\\\"\\n    )\\n\\n\\n@pytest.mark.parametrize(\\\"bad\\\", [\\\"\\\", \\\"   \\\", \\\"env/../x\\\", \\\"env abc\\\", \\\"env?x=1\\\", \\\"-env\\\"])\\ndef test_require_token_rejects_non_tokens(bad):\\n    with pytest.raises(ValueError, match=\\\"Environment ID\\\"):\\n        _common.require_token(bad, \\\"Environment ID\\\")\\n\\n\\ndef test_parse_bootstrap_servers_defaults_port_and_splits():\\n    pairs = _common.parse_bootstrap_servers(\\\"a.example.com, b.example.com:9093 ,\\\")\\n    assert pairs == [(\\\"a.example.com\\\", 9092), (\\\"b.example.com\\\", 9093)]\\n\\n\\n@pytest.mark.parametrize(\\\"bad\\\", [\\\"\\\", \\\"host:notaport\\\", \\\"host:70000\\\"])\\ndef test_parse_bootstrap_servers_rejects_invalid(bad):\\n    with pytest.raises(ValueError, match=r\\\"Bootstrap|port\\\"):\\n        _common.parse_bootstrap_servers(bad)\\n\\n\\ndef test_validate_bootstrap_servers_blocks_cloud_metadata_host():\\n    with pytest.raises(SSRFProtectionError):\\n        _common.validate_bootstrap_servers(\\\"169.254.169.254:9092\\\")\\n\\n\\ndef test_validate_bootstrap_servers_normalizes_allowed_hosts():\\n    normalized = _common.validate_bootstrap_servers(\\\"pkc-1.us-east-1.aws.confluent.cloud\\\")\\n    assert normalized == \\\"pkc-1.us-east-1.aws.confluent.cloud:9092\\\"\\n\\n\\ndef test_kafka_client_config_sasl_plain():\\n    cfg = _common.kafka_client_config(\\\"h:9092\\\", \\\"k\\\", \\\"s\\\", extra={\\\"acks\\\": \\\"all\\\", \\\"ignored\\\": None})\\n    assert cfg == {\\n        \\\"bootstrap.servers\\\": \\\"h:9092\\\",\\n        \\\"security.protocol\\\": \\\"SASL_SSL\\\",\\n        \\\"sasl.mechanisms\\\": \\\"PLAIN\\\",\\n        \\\"sasl.username\\\": \\\"k\\\",\\n        \\\"sasl.password\\\": \\\"s\\\",  # pragma: allowlist secret\\n        \\\"acks\\\": \\\"all\\\",\\n    }\\n\\n\\ndef test_kafka_client_config_unauthenticated_when_no_key():\\n    assert _common.kafka_client_config(\\\"h:9092\\\", \\\"\\\", \\\"\\\") == {\\\"bootstrap.servers\\\": \\\"h:9092\\\"}\\n\\n\\ndef test_kafka_client_config_rejects_half_credentials():\\n    with pytest.raises(ValueError, match=\\\"Both the Kafka API key\\\"):\\n        _common.kafka_client_config(\\\"h:9092\\\", \\\"k\\\", \\\"\\\")\\n\\n\\n@pytest.mark.parametrize(\\n    \\\"protected\\\",\\n    [\\n        {\\\"bootstrap.servers\\\": \\\"169.254.169.254:9092\\\"},\\n        {\\\"metadata.broker.list\\\": \\\"10.0.0.5:9092\\\"},\\n        {\\\"security.protocol\\\": \\\"PLAINTEXT\\\"},\\n        {\\\"sasl.username\\\": \\\"someone-else\\\"},\\n        {\\\"SASL.Password\\\": \\\"swapped\\\"},  # pragma: allowlist secret -- case-insensitive key match\\n        {\\\"ssl.ca.location\\\": \\\"/tmp/attacker.pem\\\"},\\n    ],\\n)\\ndef test_kafka_client_config_rejects_protected_extra_keys(protected):\\n    \\\"\\\"\\\"``extra`` must not re-point the client, downgrade TLS, or swap the credentials.\\\"\\\"\\\"\\n    with pytest.raises(ValueError, match=\\\"cannot override\\\"):\\n        _common.kafka_client_config(\\\"h:9092\\\", \\\"k\\\", \\\"s\\\", extra=protected)\\n\\n\\ndef test_kafka_client_config_extra_cannot_bypass_bootstrap_ssrf_validation():\\n    \\\"\\\"\\\"The SSRF-gated bootstrap list survives an ``extra`` that points at a private host.\\\"\\\"\\\"\\n    validated = _common.validate_bootstrap_servers(\\\"pkc-1.us-east-1.aws.confluent.cloud:9092\\\")\\n    with pytest.raises(ValueError, match=r\\\"bootstrap\\\\.servers\\\"):\\n        _common.kafka_client_config(validated, \\\"k\\\", \\\"s\\\", extra={\\\"bootstrap.servers\\\": \\\"10.0.0.5:9092\\\"})\\n\\n\\ndef test_ensure_url_allowed_blocks_private_ip():\\n    with pytest.raises(SSRFProtectionError):\\n        _common.ensure_url_allowed(\\\"https://10.0.0.5/mcp\\\")\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/confluent/tests/test_context_engine.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"f3e15e5d194957542f2dd2f0337872bcace756f08621214cf6d4c8e0d50a3424\",\"content\":\"\\\"\\\"\\\"Unit tests for ``ConfluentContextEngineComponent`` (``lfx-confluent``).\\n\\nThe MCP engine (``lfx.base.mcp.util.update_tools``) is patched at the preset\\nbase module so no network access is needed; the tests assert endpoint\\ntemplating, header construction, Tool-Mode wiring, and the direct-run path.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport base64\\nimport json\\nfrom types import SimpleNamespace\\nfrom unittest.mock import AsyncMock, patch\\n\\nimport pytest\\nfrom lfx.utils.ssrf_protection import SSRFProtectionError\\nfrom lfx_confluent import ConfluentContextEngineComponent\\nfrom lfx_confluent.components.confluent.context_engine import CONTEXT_ENGINE_TOOLS\\n\\nUPDATE_TOOLS_TARGET = \\\"lfx.base.mcp.preset.update_tools\\\"\\n\\n\\ndef _tool(name: str, result=None):\\n    async def coroutine(**kwargs):\\n        if result is not None:\\n            return result\\n        return SimpleNamespace(content=[SimpleNamespace(type=\\\"text\\\", text=json.dumps({\\\"echo\\\": kwargs}))])\\n\\n    return SimpleNamespace(name=name, description=f\\\"{name} tool\\\", coroutine=coroutine)\\n\\n\\ndef _engine(tools):\\n    return AsyncMock(return_value=(\\\"Streamable_HTTP\\\", tools, {t.name: t for t in tools}))\\n\\n\\n@pytest.fixture\\ndef component() -> ConfluentContextEngineComponent:\\n    c = ConfluentContextEngineComponent()\\n    c.region = \\\"us-east-1\\\"\\n    c.organization_id = \\\"org-1\\\"\\n    c.environment_id = \\\"env-abc\\\"\\n    c.kafka_cluster_id = \\\"lkc-xyz\\\"\\n    c.api_key = \\\"key\\\"  # pragma: allowlist secret\\n    c.api_secret = \\\"secret\\\"  # noqa: S105  # pragma: allowlist secret\\n    c.endpoint_override = \\\"\\\"\\n    c.cloud = \\\"aws\\\"\\n    c.tool = \\\"\\\"\\n    c.tool_arguments = \\\"{}\\\"\\n    c.tool_execution_timeout = 0.0\\n    c.verify_ssl = True\\n    return c\\n\\n\\ndef test_component_metadata():\\n    \\\"\\\"\\\"Class name / component name are permanent identifiers for saved flows.\\\"\\\"\\\"\\n    assert ConfluentContextEngineComponent.__name__ == \\\"ConfluentContextEngineComponent\\\"\\n    assert ConfluentContextEngineComponent.name == \\\"ConfluentContextEngine\\\"\\n    assert ConfluentContextEngineComponent.add_tool_output is True\\n\\n\\ndef test_tool_dropdown_seeded_with_documented_tools():\\n    tool_input = next(i for i in ConfluentContextEngineComponent.inputs if i.name == \\\"tool\\\")\\n    assert tool_input.options == CONTEXT_ENGINE_TOOLS\\n\\n\\ndef test_hidden_tool_mode_trigger_present():\\n    trigger = next(i for i in ConfluentContextEngineComponent.inputs if i.name == \\\"tool_mode_trigger\\\")\\n    assert trigger.tool_mode is True\\n    assert trigger.show is False\\n\\n\\ndef test_endpoint_url_templated_from_ids(component):\\n    assert component.endpoint_url() == (\\n        \\\"https://mcp.us-east-1.aws.confluent.cloud/mcp/v1/context-engine/\\\"\\n        \\\"organizations/org-1/environments/env-abc/kafka-clusters/lkc-xyz\\\"\\n    )\\n\\n\\ndef test_endpoint_override_wins_and_is_ssrf_checked(component):\\n    component.endpoint_override = \\\"https://mcp.example.com/mcp/v1/context-engine/x\\\"\\n    assert component.endpoint_url() == \\\"https://mcp.example.com/mcp/v1/context-engine/x\\\"\\n    component.endpoint_override = \\\"http://169.254.169.254/latest/meta-data\\\"\\n    with pytest.raises(SSRFProtectionError):\\n        component.endpoint_url()\\n\\n\\ndef test_mcp_server_config_has_basic_auth_header(component):\\n    name, config = component._mcp_server_config()\\n    assert name == \\\"confluent-context-engine-lkc-xyz\\\"\\n    assert config[\\\"mode\\\"] == \\\"Streamable_HTTP\\\"\\n    assert config[\\\"verify_ssl\\\"] is True\\n    token = config[\\\"headers\\\"][\\\"Authorization\\\"].removeprefix(\\\"Basic \\\")\\n    assert base64.b64decode(token).decode() == \\\"key:secret\\\"\\n\\n\\nasync def test_get_tools_returns_engine_tools(component):\\n    tools = [_tool(\\\"list_topics\\\"), _tool(\\\"query_data\\\")]\\n    with patch(UPDATE_TOOLS_TARGET, new=_engine(tools)) as upd:\\n        got = await component._get_tools()\\n    assert [t.name for t in got] == [\\\"list_topics\\\", \\\"query_data\\\"]\\n    server_name, server_config = upd.await_args.args[:2]\\n    assert server_name.startswith(\\\"confluent-context-engine\\\")\\n    assert server_config[\\\"url\\\"].endswith(\\\"/kafka-clusters/lkc-xyz\\\")\\n\\n\\nasync def test_get_tools_raises_when_server_returns_nothing(component):\\n    with (\\n        patch(UPDATE_TOOLS_TARGET, new=AsyncMock(return_value=(\\\"\\\", [], {}))),\\n        pytest.raises(ValueError, match=\\\"No tools\\\"),\\n    ):\\n        await component._get_tools()\\n\\n\\nasync def test_run_tool_executes_selected_tool_with_json_arguments(component):\\n    tools = [_tool(\\\"query_data\\\")]\\n    component.tool = \\\"query_data\\\"\\n    component.tool_arguments = json.dumps({\\\"topic\\\": \\\"orders\\\", \\\"filter\\\": \\\"amount > 10\\\"})\\n    with patch(UPDATE_TOOLS_TARGET, new=_engine(tools)):\\n        frame = await component.run_tool()\\n    assert frame.to_dict(orient=\\\"records\\\") == [{\\\"echo\\\": {\\\"topic\\\": \\\"orders\\\", \\\"filter\\\": \\\"amount > 10\\\"}}]\\n\\n\\nasync def test_run_tool_requires_a_selection(component):\\n    with pytest.raises(ValueError, match=\\\"Select a tool\\\"):\\n        await component.run_tool()\\n\\n\\nasync def test_run_tool_unknown_tool_lists_available(component):\\n    tools = [_tool(\\\"list_topics\\\")]\\n    component.tool = \\\"nope\\\"\\n    with (\\n        patch(UPDATE_TOOLS_TARGET, new=_engine(tools)),\\n        pytest.raises(ValueError, match=\\\"Available tools: list_topics\\\"),\\n    ):\\n        await component.run_tool()\\n\\n\\ndef test_tool_arguments_must_be_json_object(component):\\n    component.tool_arguments = \\\"[1, 2]\\\"\\n    with pytest.raises(TypeError, match=\\\"JSON object\\\"):\\n        component._parse_tool_arguments()\\n    component.tool_arguments = \\\"{not json\\\"\\n    with pytest.raises(ValueError, match=\\\"JSON object\\\"):\\n        component._parse_tool_arguments()\\n\\n\\nasync def test_update_build_config_refreshes_tool_options(component):\\n    tools = [_tool(\\\"list_topics\\\"), _tool(\\\"get_metadata\\\"), _tool(\\\"query_data\\\"), _tool(\\\"new_tool\\\")]\\n    build_config = {\\\"tool\\\": {\\\"options\\\": list(CONTEXT_ENGINE_TOOLS), \\\"value\\\": \\\"query_data\\\"}}\\n    with patch(UPDATE_TOOLS_TARGET, new=_engine(tools)):\\n        out = await component.update_build_config(build_config, \\\"\\\", field_name=\\\"tool\\\")\\n    assert out[\\\"tool\\\"][\\\"options\\\"] == [\\\"list_topics\\\", \\\"get_metadata\\\", \\\"query_data\\\", \\\"new_tool\\\"]\\n    assert out[\\\"tool\\\"][\\\"value\\\"] == \\\"query_data\\\"\\n\\n\\nasync def test_update_build_config_keeps_defaults_on_failure(component):\\n    build_config = {\\\"tool\\\": {\\\"options\\\": list(CONTEXT_ENGINE_TOOLS), \\\"value\\\": \\\"\\\"}}\\n    with patch(UPDATE_TOOLS_TARGET, new=AsyncMock(side_effect=ConnectionError(\\\"down\\\"))):\\n        out = await component.update_build_config(build_config, \\\"\\\", field_name=\\\"tool\\\")\\n    assert out[\\\"tool\\\"][\\\"options\\\"] == CONTEXT_ENGINE_TOOLS\\n\\n\\ndef test_result_rows_flattens_json_array_and_keeps_text():\\n    result = SimpleNamespace(\\n        content=[\\n            SimpleNamespace(type=\\\"text\\\", text=json.dumps([{\\\"topic\\\": \\\"a\\\"}, {\\\"topic\\\": \\\"b\\\"}])),\\n            SimpleNamespace(type=\\\"text\\\", text=\\\"plain text\\\"),\\n            SimpleNamespace(type=\\\"text\\\", text=json.dumps(42)),\\n        ]\\n    )\\n    rows = ConfluentContextEngineComponent._result_rows(result)\\n    assert rows[0] == {\\\"topic\\\": \\\"a\\\"}\\n    assert rows[1] == {\\\"topic\\\": \\\"b\\\"}\\n    assert rows[2][\\\"text\\\"] == \\\"plain text\\\"\\n    assert rows[3] == {\\\"type\\\": \\\"text\\\", \\\"text\\\": \\\"42\\\", \\\"parsed_value\\\": 42}\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/confluent/tests/test_kafka_consumer.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"b9594fe0d42eef8c672503a04bbf4cc2245255ff41d04a98031a0fd8d770c30a\",\"content\":\"\\\"\\\"\\\"Unit tests for ``ConfluentKafkaConsumerComponent`` (``lfx-confluent``).\\n\\n``confluent_kafka.Consumer`` is patched with a fake that hands out scripted\\nmessages, so the tests cover the bounded consume loop, value decoding, row\\nshape, offset commit, and close-on-error without a broker.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport json\\nfrom unittest.mock import patch\\n\\nimport pytest\\nfrom lfx.utils.ssrf_protection import SSRFProtectionError\\nfrom lfx_confluent import ConfluentKafkaConsumerComponent\\nfrom lfx_confluent.components.confluent.kafka_consumer import SCHEMA_REGISTRY_FORMATS\\n\\nCONSUMER_TARGET = \\\"confluent_kafka.Consumer\\\"\\n\\n\\nclass _FakeMessage:\\n    def __init__(self, value, key=b\\\"k\\\", topic=\\\"orders\\\", partition=0, offset=0, headers=None, error=None):\\n        self._value, self._key, self._topic = value, key, topic\\n        self._partition, self._offset, self._headers, self._error = partition, offset, headers, error\\n\\n    def error(self):\\n        return self._error\\n\\n    def value(self):\\n        return self._value\\n\\n    def key(self):\\n        return self._key\\n\\n    def topic(self):\\n        return self._topic\\n\\n    def partition(self):\\n        return self._partition\\n\\n    def offset(self):\\n        return self._offset\\n\\n    def timestamp(self):\\n        return (1, 1_700_000_000_000 + self._offset)\\n\\n    def headers(self):\\n        return self._headers\\n\\n\\nclass _FakeConsumer:\\n    instances: list[_FakeConsumer] = []\\n    script: list[list[_FakeMessage]] = []\\n\\n    def __init__(self, config):\\n        self.config = config\\n        self.subscribed = None\\n        self.closed = False\\n        self.committed = False\\n        self.consume_calls = 0\\n        _FakeConsumer.instances.append(self)\\n\\n    def subscribe(self, topics):\\n        self.subscribed = topics\\n\\n    def consume(self, num_messages, timeout):  # noqa: ARG002 - mirrors the confluent_kafka signature\\n        self.consume_calls += 1\\n        if _FakeConsumer.script:\\n            batch = _FakeConsumer.script.pop(0)\\n            return batch[:num_messages]\\n        return []\\n\\n    def commit(self, *, asynchronous=True):  # noqa: ARG002 - mirrors the confluent_kafka signature\\n        self.committed = True\\n\\n    def close(self):\\n        self.closed = True\\n\\n\\n@pytest.fixture(autouse=True)\\ndef _reset_fake():\\n    _FakeConsumer.instances.clear()\\n    _FakeConsumer.script = []\\n    yield\\n    _FakeConsumer.instances.clear()\\n    _FakeConsumer.script = []\\n\\n\\n@pytest.fixture\\ndef component() -> ConfluentKafkaConsumerComponent:\\n    c = ConfluentKafkaConsumerComponent()\\n    c.bootstrap_servers = \\\"pkc-1.us-east-1.aws.confluent.cloud:9092\\\"\\n    c.api_key = \\\"key\\\"  # pragma: allowlist secret\\n    c.api_secret = \\\"secret\\\"  # noqa: S105  # pragma: allowlist secret\\n    c.topics = \\\"orders, payments\\\"\\n    c.group_id = \\\"test-group\\\"\\n    c.max_messages = 3\\n    c.timeout_seconds = 2.0\\n    c.auto_offset_reset = \\\"earliest\\\"\\n    c.commit_offsets = True\\n    c.value_format = \\\"json\\\"\\n    c.schema_registry_url = \\\"\\\"\\n    c.schema_registry_key = \\\"\\\"\\n    c.schema_registry_secret = \\\"\\\"\\n    c.client_config = {}\\n    return c\\n\\n\\ndef test_component_metadata():\\n    assert ConfluentKafkaConsumerComponent.__name__ == \\\"ConfluentKafkaConsumerComponent\\\"\\n    assert ConfluentKafkaConsumerComponent.name == \\\"ConfluentKafkaConsumer\\\"\\n\\n\\ndef test_update_build_config_shows_registry_fields_for_schema_formats(component):\\n    fields = (\\\"schema_registry_url\\\", \\\"schema_registry_key\\\", \\\"schema_registry_secret\\\")\\n    build_config = {k: {\\\"show\\\": False, \\\"advanced\\\": True} for k in fields}\\n    for fmt in SCHEMA_REGISTRY_FORMATS:\\n        out = component.update_build_config(dict(build_config), fmt, field_name=\\\"value_format\\\")\\n        assert all(out[k][\\\"show\\\"] for k in build_config)\\n    out = component.update_build_config(dict(build_config), \\\"json\\\", field_name=\\\"value_format\\\")\\n    assert not any(out[k][\\\"show\\\"] for k in build_config)\\n\\n\\ndef test_bounds_are_clamped(component):\\n    component.max_messages = 999_999\\n    component.timeout_seconds = 9_999\\n    assert component._bounds() == (10_000, 300.0)\\n\\n\\ndef test_group_id_defaults_when_empty(component):\\n    component.group_id = \\\"\\\"\\n    assert component._resolved_group_id().startswith(\\\"langflow\\\")\\n\\n\\nasync def test_consume_reads_bounded_batch_and_promotes_json_fields(component):\\n    _FakeConsumer.script = [\\n        [\\n            _FakeMessage(json.dumps({\\\"id\\\": 1, \\\"amount\\\": 10}).encode(), offset=0, headers=[(\\\"h\\\", b\\\"v\\\")]),\\n            _FakeMessage(json.dumps({\\\"id\\\": 2, \\\"amount\\\": 20}).encode(), offset=1),\\n        ],\\n        [\\n            _FakeMessage(b\\\"not-json\\\", offset=2),\\n            _FakeMessage(b\\\"never-read\\\", offset=3),\\n        ],\\n    ]\\n    with patch(CONSUMER_TARGET, _FakeConsumer):\\n        frame = await component.consume()\\n    consumer = _FakeConsumer.instances[0]\\n    assert consumer.subscribed == [\\\"orders\\\", \\\"payments\\\"]\\n    assert consumer.config[\\\"group.id\\\"] == \\\"test-group\\\"\\n    assert consumer.config[\\\"auto.offset.reset\\\"] == \\\"earliest\\\"\\n    assert consumer.config[\\\"enable.auto.commit\\\"] is False\\n    assert consumer.config[\\\"security.protocol\\\"] == \\\"SASL_SSL\\\"\\n    assert consumer.committed is True\\n    assert consumer.closed is True\\n    rows = frame.to_dict(orient=\\\"records\\\")\\n    assert len(rows) == 3\\n    assert rows[0][\\\"id\\\"] == 1\\n    assert rows[0][\\\"amount\\\"] == 10\\n    assert rows[0][\\\"value\\\"] == {\\\"id\\\": 1, \\\"amount\\\": 10}\\n    assert rows[0][\\\"headers\\\"] == {\\\"h\\\": \\\"v\\\"}\\n    assert rows[0][\\\"key\\\"] == \\\"k\\\"\\n    assert rows[2][\\\"value\\\"] == \\\"not-json\\\"\\n\\n\\nasync def test_consume_string_format_returns_text(component):\\n    component.value_format = \\\"string\\\"\\n    _FakeConsumer.script = [[_FakeMessage(b'{\\\"id\\\": 1}')]]\\n    with patch(CONSUMER_TARGET, _FakeConsumer):\\n        frame = await component.consume()\\n    assert frame.to_dict(orient=\\\"records\\\")[0][\\\"value\\\"] == '{\\\"id\\\": 1}'\\n\\n\\nasync def test_consume_returns_empty_frame_on_timeout(component):\\n    component.timeout_seconds = 0.5\\n    with patch(CONSUMER_TARGET, _FakeConsumer):\\n        frame = await component.consume()\\n    assert len(frame) == 0\\n    assert _FakeConsumer.instances[0].closed is True\\n    assert _FakeConsumer.instances[0].committed is False\\n\\n\\nasync def test_consume_closes_consumer_on_kafka_error(component):\\n    from confluent_kafka import KafkaError\\n\\n    class _Err:\\n        def code(self):\\n            return KafkaError._UNKNOWN_TOPIC\\n\\n        def __str__(self):\\n            return \\\"unknown topic\\\"\\n\\n    _FakeConsumer.script = [[_FakeMessage(b\\\"{}\\\", error=_Err())]]\\n    with patch(CONSUMER_TARGET, _FakeConsumer), pytest.raises(ValueError, match=\\\"Kafka consume failed\\\"):\\n        await component.consume()\\n    assert _FakeConsumer.instances[0].closed is True\\n\\n\\nasync def test_consume_skips_partition_eof(component):\\n    from confluent_kafka import KafkaError\\n\\n    class _Eof:\\n        def code(self):\\n            return KafkaError._PARTITION_EOF\\n\\n    _FakeConsumer.script = [[_FakeMessage(b\\\"{}\\\", error=_Eof()), _FakeMessage(json.dumps({\\\"id\\\": 9}).encode())]]\\n    component.max_messages = 2\\n    component.timeout_seconds = 0.5\\n    with patch(CONSUMER_TARGET, _FakeConsumer):\\n        frame = await component.consume()\\n    rows = frame.to_dict(orient=\\\"records\\\")\\n    assert len(rows) == 1  # the EOF sentinel is skipped, not surfaced as a row\\n    assert rows[0][\\\"id\\\"] == 9\\n\\n\\nasync def test_consume_blocks_ssrf_bootstrap_host(component):\\n    component.bootstrap_servers = \\\"10.0.0.5:9092\\\"\\n    with pytest.raises(SSRFProtectionError):\\n        await component.consume()\\n\\n\\nasync def test_consume_requires_topics(component):\\n    component.topics = \\\" , \\\"\\n    with pytest.raises(ValueError, match=\\\"At least one topic\\\"):\\n        await component.consume()\\n\\n\\ndef test_registry_deserializer_requires_registry_url(component):\\n    component.value_format = \\\"avro\\\"\\n    with pytest.raises(ValueError, match=\\\"endpoint URL is required\\\"):\\n        component._value_deserializer()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/confluent/tests/test_kafka_producer.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"90eb38db8526a3dc7cf191146a185268ddf47895e6cafb8909eb2f8c29dd42da\",\"content\":\"\\\"\\\"\\\"Unit tests for ``ConfluentKafkaProducerComponent`` (``lfx-confluent``).\\n\\n``confluent_kafka.Producer`` is patched with a fake that invokes delivery\\ncallbacks synchronously, so the tests exercise payload encoding, header\\nhandling, and delivery-report aggregation without a broker.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport json\\nfrom unittest.mock import patch\\n\\nimport pytest\\nfrom lfx.schema.data import Data\\nfrom lfx.schema.dataframe import DataFrame\\nfrom lfx.schema.message import Message\\nfrom lfx.utils.ssrf_protection import SSRFProtectionError\\nfrom lfx_confluent import ConfluentKafkaProducerComponent\\n\\nPRODUCER_TARGET = \\\"confluent_kafka.Producer\\\"\\n\\n\\nclass _FakeMessage:\\n    def __init__(self, topic, key, partition=0, offset=7):\\n        self._topic, self._key, self._partition, self._offset = topic, key, partition, offset\\n\\n    def topic(self):\\n        return self._topic\\n\\n    def partition(self):\\n        return self._partition\\n\\n    def offset(self):\\n        return self._offset\\n\\n    def timestamp(self):\\n        return (1, 1_700_000_000_000)\\n\\n    def key(self):\\n        return self._key\\n\\n\\nclass _FakeProducer:\\n    instances: list[_FakeProducer] = []\\n\\n    def __init__(self, config):\\n        self.config = config\\n        self.produced: list[dict] = []\\n        self.flushed_with = None\\n        self.remaining_after_flush = 0\\n        self.fail_every = None\\n        _FakeProducer.instances.append(self)\\n\\n    def produce(self, topic, value=None, key=None, headers=None, on_delivery=None):\\n        self.produced.append({\\\"topic\\\": topic, \\\"value\\\": value, \\\"key\\\": key, \\\"headers\\\": headers})\\n        if self.fail_every and len(self.produced) % self.fail_every == 0:\\n            on_delivery(RuntimeError(\\\"broker said no\\\"), None)\\n        else:\\n            on_delivery(None, _FakeMessage(topic, key, offset=len(self.produced)))\\n\\n    def poll(self, _timeout):\\n        return 0\\n\\n    def flush(self, timeout):\\n        self.flushed_with = timeout\\n        return self.remaining_after_flush\\n\\n\\n@pytest.fixture(autouse=True)\\ndef _reset_fake():\\n    _FakeProducer.instances.clear()\\n    yield\\n    _FakeProducer.instances.clear()\\n\\n\\n@pytest.fixture\\ndef component() -> ConfluentKafkaProducerComponent:\\n    c = ConfluentKafkaProducerComponent()\\n    c.bootstrap_servers = \\\"pkc-1.us-east-1.aws.confluent.cloud:9092\\\"\\n    c.api_key = \\\"key\\\"  # pragma: allowlist secret\\n    c.api_secret = \\\"secret\\\"  # noqa: S105  # pragma: allowlist secret\\n    c.topic = \\\"orders\\\"\\n    c.key = \\\"\\\"\\n    c.serialization = \\\"json\\\"\\n    c.headers = {}\\n    c.flush_timeout = 10\\n    c.client_config = {}\\n    return c\\n\\n\\ndef test_component_metadata():\\n    assert ConfluentKafkaProducerComponent.__name__ == \\\"ConfluentKafkaProducerComponent\\\"\\n    assert ConfluentKafkaProducerComponent.name == \\\"ConfluentKafkaProducer\\\"\\n\\n\\ndef test_records_from_message_data_and_dataframe(component):\\n    component.message = Message(text=\\\"hello\\\")\\n    assert component._records() == [{\\\"key\\\": None, \\\"value\\\": b\\\"hello\\\"}]\\n\\n    component.message = Data(data={\\\"a\\\": 1})\\n    assert json.loads(component._records()[0][\\\"value\\\"]) == {\\\"a\\\": 1}\\n\\n    component.key = \\\"k1\\\"\\n    component.message = DataFrame([{\\\"a\\\": 1}, {\\\"a\\\": 2}])\\n    records = component._records()\\n    assert [json.loads(r[\\\"value\\\"]) for r in records] == [{\\\"a\\\": 1}, {\\\"a\\\": 2}]\\n    assert all(r[\\\"key\\\"] == \\\"k1\\\" for r in records)\\n\\n\\ndef test_records_require_a_payload(component):\\n    component.message = None\\n    with pytest.raises(ValueError, match=\\\"Connect a Message\\\"):\\n        component._records()\\n\\n\\ndef test_record_headers_from_dict_and_list(component):\\n    component.headers = {\\\"source\\\": \\\"langflow\\\"}\\n    assert component._record_headers() == [(\\\"source\\\", b\\\"langflow\\\")]\\n    component.headers = [{\\\"a\\\": \\\"1\\\"}, {\\\"b\\\": \\\"2\\\"}]\\n    assert component._record_headers() == [(\\\"a\\\", b\\\"1\\\"), (\\\"b\\\", b\\\"2\\\")]\\n    component.headers = {}\\n    assert component._record_headers() is None\\n\\n\\nasync def test_produce_publishes_each_row_and_reports_delivery(component):\\n    component.message = DataFrame([{\\\"id\\\": 1}, {\\\"id\\\": 2}, {\\\"id\\\": 3}])\\n    component.headers = {\\\"source\\\": \\\"langflow\\\"}\\n    component.client_config = {\\\"acks\\\": \\\"all\\\"}\\n    with patch(PRODUCER_TARGET, _FakeProducer):\\n        result = await component.produce()\\n    producer = _FakeProducer.instances[0]\\n    assert producer.config[\\\"bootstrap.servers\\\"] == \\\"pkc-1.us-east-1.aws.confluent.cloud:9092\\\"\\n    assert producer.config[\\\"security.protocol\\\"] == \\\"SASL_SSL\\\"\\n    assert producer.config[\\\"sasl.username\\\"] == \\\"key\\\"\\n    assert producer.config[\\\"acks\\\"] == \\\"all\\\"\\n    assert len(producer.produced) == 3\\n    assert producer.produced[0][\\\"headers\\\"] == [(\\\"source\\\", b\\\"langflow\\\")]\\n    assert producer.flushed_with == 10.0\\n    assert result.data[\\\"records_sent\\\"] == 3\\n    assert result.data[\\\"delivered\\\"] == 3\\n    assert result.data[\\\"failed\\\"] == 0\\n    assert result.data[\\\"reports\\\"][0][\\\"offset\\\"] == 1\\n\\n\\n@pytest.mark.parametrize(\\n    (\\\"configured\\\", \\\"expected\\\"),\\n    [(-1, 1.0), (0, 10.0), (0.2, 1.0), (10, 10.0), (10_000, 300.0)],\\n)\\nasync def test_flush_timeout_is_clamped(component, configured, expected):\\n    \\\"\\\"\\\"A negative timeout would make ``Producer.flush`` block forever and pin the worker.\\\"\\\"\\\"\\n    component.message = DataFrame([{\\\"id\\\": 1}])\\n    component.flush_timeout = configured\\n    with patch(PRODUCER_TARGET, _FakeProducer):\\n        await component.produce()\\n    assert _FakeProducer.instances[-1].flushed_with == expected\\n\\n\\nasync def test_produce_reports_partial_failures(component):\\n    component.message = DataFrame([{\\\"id\\\": 1}, {\\\"id\\\": 2}])\\n\\n    class _Flaky(_FakeProducer):\\n        def __init__(self, config):\\n            super().__init__(config)\\n            self.fail_every = 2\\n\\n    with patch(PRODUCER_TARGET, _Flaky):\\n        result = await component.produce()\\n    assert result.data[\\\"delivered\\\"] == 1\\n    assert result.data[\\\"failed\\\"] == 1\\n    assert any(not r[\\\"delivered\\\"] for r in result.data[\\\"reports\\\"])\\n\\n\\nasync def test_produce_raises_when_nothing_delivered(component):\\n    component.message = Message(text=\\\"x\\\")\\n\\n    class _Broken(_FakeProducer):\\n        def __init__(self, config):\\n            super().__init__(config)\\n            self.fail_every = 1\\n\\n    with patch(PRODUCER_TARGET, _Broken), pytest.raises(ValueError, match=\\\"No records were delivered\\\"):\\n        await component.produce()\\n\\n\\nasync def test_produce_flags_unacknowledged_records(component):\\n    component.message = Message(text=\\\"x\\\")\\n\\n    class _Slow(_FakeProducer):\\n        def __init__(self, config):\\n            super().__init__(config)\\n            self.remaining_after_flush = 1\\n\\n    with patch(PRODUCER_TARGET, _Slow):\\n        result = await component.produce()\\n    assert result.data[\\\"failed\\\"] == 1\\n    assert \\\"not acknowledged\\\" in result.data[\\\"reports\\\"][-1][\\\"error\\\"]\\n\\n\\nasync def test_produce_blocks_ssrf_bootstrap_host(component):\\n    component.message = Message(text=\\\"x\\\")\\n    component.bootstrap_servers = \\\"169.254.169.254:9092\\\"\\n    with pytest.raises(SSRFProtectionError):\\n        await component.produce()\\n\\n\\nasync def test_produce_requires_topic(component):\\n    component.message = Message(text=\\\"x\\\")\\n    component.topic = \\\"  \\\"\\n    with pytest.raises(ValueError, match=\\\"Topic is required\\\"):\\n        await component.produce()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/confluent/tests/test_optional_sdks.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3d10786e3931f0fc0364d7a50d21f5f1862d88eba159e856495854d58fe2206\",\"content\":\"\\\"\\\"\\\"Regression: the Confluent bundle must import without ``confluent_kafka`` / ``pyiceberg``.\\n\\nBoth SDKs are imported lazily (inside the build methods) so the bundle still\\nloads -- and the MCP preset component still works -- on a platform where a\\nwheel is unavailable.  These tests *simulate* the packages' absence (a\\n``None`` entry in ``sys.modules`` makes the import raise ``ImportError``) so\\nthey run on every platform, and guard against re-introducing a module-level\\nimport of either SDK.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport importlib\\nimport sys\\n\\nimport pytest\\n\\n_SIMULATED_MISSING = (\\\"confluent_kafka\\\", \\\"pyiceberg\\\", \\\"pyiceberg.catalog\\\")\\n\\n\\ndef _bundle_module_names() -> list[str]:\\n    return [name for name in sys.modules if name == \\\"lfx_confluent\\\" or name.startswith(\\\"lfx_confluent.\\\")]\\n\\n\\n@pytest.fixture\\ndef without_sdks():\\n    saved = {name: sys.modules[name] for name in _bundle_module_names()}\\n    for name in saved:\\n        del sys.modules[name]\\n    sdk_roots = {\\\"confluent_kafka\\\", \\\"pyiceberg\\\"}\\n    saved_sdks = {name: sys.modules.pop(name, None) for name in list(sys.modules) if name.split(\\\".\\\")[0] in sdk_roots}\\n    for name in _SIMULATED_MISSING:\\n        sys.modules[name] = None\\n    try:\\n        yield\\n    finally:\\n        for name in _SIMULATED_MISSING:\\n            sys.modules.pop(name, None)\\n        for name in _bundle_module_names():\\n            del sys.modules[name]\\n        sys.modules.update({k: v for k, v in saved_sdks.items() if v is not None})\\n        sys.modules.update(saved)\\n\\n\\n@pytest.mark.usefixtures(\\\"without_sdks\\\")\\ndef test_bundle_imports_without_sdks():\\n    module = importlib.import_module(\\\"lfx_confluent\\\")\\n    assert {\\n        \\\"ConfluentContextEngineComponent\\\",\\n        \\\"ConfluentKafkaConsumerComponent\\\",\\n        \\\"ConfluentKafkaProducerComponent\\\",\\n        \\\"ConfluentTableflowReaderComponent\\\",\\n    } <= set(module.__all__)\\n\\n\\n@pytest.mark.usefixtures(\\\"without_sdks\\\")\\nasync def test_producer_raises_clear_error_without_confluent_kafka():\\n    from lfx.schema.message import Message\\n\\n    module = importlib.import_module(\\\"lfx_confluent.components.confluent.kafka_producer\\\")\\n    c = module.ConfluentKafkaProducerComponent()\\n    c.bootstrap_servers = \\\"pkc-1.us-east-1.aws.confluent.cloud:9092\\\"\\n    c.api_key = c.api_secret = \\\"\\\"\\n    c.topic = \\\"t\\\"\\n    c.message = Message(text=\\\"x\\\")\\n    c.headers = {}\\n    c.client_config = {}\\n    c.flush_timeout = 1\\n    with pytest.raises(ImportError, match=\\\"confluent-kafka is not installed\\\"):\\n        await c.produce()\\n\\n\\n@pytest.mark.usefixtures(\\\"without_sdks\\\")\\nasync def test_tableflow_raises_clear_error_without_pyiceberg():\\n    module = importlib.import_module(\\\"lfx_confluent.components.confluent.tableflow_reader\\\")\\n    c = module.ConfluentTableflowReaderComponent()\\n    c.region, c.organization_id, c.environment_id, c.kafka_cluster_id = \\\"us-east-1\\\", \\\"org\\\", \\\"env-1\\\", \\\"lkc-1\\\"\\n    c.api_key, c.api_secret = \\\"k\\\", \\\"s\\\"  # pragma: allowlist secret\\n    c.table_name = \\\"orders\\\"\\n    c.storage_mode = \\\"confluent_managed\\\"\\n    c.access_delegation = \\\"vended-credentials\\\"\\n    c.catalog_uri_override = c.namespace = c.snapshot_id = c.row_filter = c.selected_fields = \\\"\\\"\\n    c.limit = 10\\n    with pytest.raises(ImportError, match=\\\"pyiceberg is not installed\\\"):\\n        await c.read_table()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/datastax/README.md\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"95fe3696eb07fd2647f712a613e2e8a93fed0c1af997bda6fc0998c41843c392\",\"content\":\"# lfx-datastax\\n\\nDataStax component(s) as a standalone Langflow Extension Bundle.\\n\\n## Install\\n\\n```bash\\npip install lfx-datastax\\n```\\n\\nThe bundle is registered automatically via the `langflow.extensions`\\nentry-point.  After install, restart your Langflow server; the bundle's\\ncomponents will appear in the palette under the `datastax` group with\\nthe namespaced IDs `ext:datastax:<Class>@official`.\\n\\n## Develop\\n\\n```bash\\ncd src/bundles/datastax\\npip install -e .\\nlfx extension validate src/lfx_datastax\\n```\\n\\n## Migration\\n\\nSaved flows referencing the legacy class name(s) or the old import paths\\nunder `lfx.components.datastax.*` are rewritten to the new namespaced\\nIDs by the migration table in\\n`src/lfx/src/lfx/extension/migration/migration_table.json`.\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/datastax/pyproject.toml\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"accb5b6982360c408e01d95f9af716e114256254bb561b4daa72978fa81ec471\",\"content\":\"[project]\\nname = \\\"lfx-datastax\\\"\\nversion = \\\"0.1.8\\\"\\ndescription = \\\"DataStax and Cassandra components as a standalone Langflow Extension Bundle.\\\"\\nreadme = \\\"README.md\\\"\\nrequires-python = \\\">=3.10,<3.15\\\"\\nlicense = { text = \\\"MIT\\\" }\\nauthors = [\\n    { name = \\\"Langflow\\\", email = \\\"contact@langflow.org\\\" },\\n]\\nkeywords = [\\\"langflow\\\", \\\"lfx\\\", \\\"extension\\\", \\\"bundle\\\", \\\"datastax\\\"]\\n\\n# Runtime deps: lfx (the BUNDLE_API surface) plus any third-party imports\\n# the bundle's components rely on.  REVIEW THIS LIST -- the script ports\\n# only ``lfx``; add any other deps the moved component(s) import.\\n# lfx is floored at the current major.minor line and capped below the next\\n# lfx major (e.g. \\\"lfx>=1.11.0,<2.0.0\\\"); the floor is read from\\n# src/lfx/pyproject.toml at port time and re-synced on ``make patch`` via\\n# scripts/ci/sync_bundle_lfx_pin.py.  Fine-grained BUNDLE_API compatibility\\n# is enforced via extension.json's lfx.compat list against BUNDLE_API_VERSION.\\ndependencies = [\\n    \\\"lfx>=1.12.0.dev0,<2.0.0\\\",\\n    \\\"langchain-astradb~=1.0.0\\\",\\n    \\\"langchain-community>=0.4.1,<1.0.0\\\",\\n    # Imported directly (astrapy.DataAPIClient/Database) by the astra components,\\n    # not just transitively via langchain-astradb; pin matches langflow-base's\\n    # astrapy extra.\\n    \\\"astrapy>=2.1.0,<3.0.0\\\",\\n    \\\"langchain-graph-retriever==0.8.0\\\",\\n    \\\"graph-retriever==0.8.0\\\",\\n    \\\"requests>=2.32.0\\\",\\n    \\\"cassio>=0.1.7\\\",\\n]\\n\\n[project.urls]\\nHomepage = \\\"https://github.com/langflow-ai/langflow\\\"\\nDocumentation = \\\"https://docs.langflow.org/extensions\\\"\\nRepository = \\\"https://github.com/langflow-ai/langflow\\\"\\n\\n# Manifest-shipping distributions are discovered via the\\n# ``langflow.extensions`` entry-point.  Editable installs whose\\n# ``dist.files`` only surfaces dist-info entries fall back to this\\n# entry-point to find the manifest.\\n[project.entry-points.\\\"langflow.extensions\\\"]\\nlfx-datastax = \\\"lfx_datastax\\\"\\n\\n[build-system]\\nrequires = [\\\"hatchling==1.31.0\\\"]\\nbuild-backend = \\\"hatchling.build\\\"\\n\\n[tool.hatch.build.targets.wheel]\\n# extension.json + components live inside the lfx_datastax package so\\n# ``importlib.metadata.files(dist)`` finds them and the loader resolves\\n# bundles[].path relative to the manifest's directory.\\npackages = [\\\"src/lfx_datastax\\\"]\\ninclude = [\\n    \\\"src/lfx_datastax/extension.json\\\",\\n    \\\"src/lfx_datastax/base/**/*.py\\\",\\n    \\\"src/lfx_datastax/components/**/*.py\\\",\\n]\\n\\n[tool.hatch.build.targets.sdist]\\ninclude = [\\n    \\\"src/lfx_datastax\\\",\\n    \\\"extension.json\\\",\\n    \\\"README.md\\\",\\n    \\\"pyproject.toml\\\",\\n]\\n\\n[tool.ruff]\\n# This file defines a [tool.ruff.lint.*] table, which makes ruff treat this\\n# directory as a standalone config root. Without restating line-length, ruff\\n# falls back to its default of 88 here, which conflicts with the repo-wide 120\\n# enforced by the pre-commit ruff-format hook (run with --config pyproject.toml).\\nline-length = 120\\n\\n[tool.ruff.lint.per-file-ignores]\\n\\\"src/lfx_datastax/components/datastax/astradb_vectorstore.py\\\" = [\\\"S110\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/datastax/src/lfx_datastax/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"9c147d6f40c532db7d8303e8c4ddace4dfbf7e1ffb70f18b1752174c1a2e6ae4\",\"content\":\"\\\"\\\"\\\"lfx-datastax: DataStax bundle.\\n\\nDistribution unit ``lfx-datastax``.  At runtime Langflow's loader\\ndiscovers ``extension.json`` shipped alongside this ``__init__.py`` and\\nregisters the bundle's components under the namespaced IDs\\n``ext:datastax:<Class>@official``.\\n\\\"\\\"\\\"\\n\\nfrom lfx_datastax.components.datastax.astradb_cql import AstraDBCQLToolComponent\\nfrom lfx_datastax.components.datastax.astradb_chatmemory import AstraDBChatMemory\\nfrom lfx_datastax.components.datastax.astradb_data_api import AstraDBDataAPIComponent\\nfrom lfx_datastax.components.datastax.astradb_graph import (\\n    AstraDBGraphVectorStoreComponent,\\n)\\nfrom lfx_datastax.components.datastax.astradb_tool import AstraDBToolComponent\\nfrom lfx_datastax.components.datastax.astradb_vectorstore import (\\n    AstraDBVectorStoreComponent,\\n)\\nfrom lfx_datastax.components.datastax.astradb_vectorize import AstraVectorizeComponent\\nfrom lfx_datastax.components.datastax.dotenv import Dotenv\\nfrom lfx_datastax.components.datastax.graph_rag import GraphRAGComponent\\nfrom lfx_datastax.components.datastax.hcd import HCDVectorStoreComponent\\n\\n__all__ = [\\n    \\\"AstraDBCQLToolComponent\\\",\\n    \\\"AstraDBChatMemory\\\",\\n    \\\"AstraDBDataAPIComponent\\\",\\n    \\\"AstraDBGraphVectorStoreComponent\\\",\\n    \\\"AstraDBToolComponent\\\",\\n    \\\"AstraDBVectorStoreComponent\\\",\\n    \\\"AstraVectorizeComponent\\\",\\n    \\\"Dotenv\\\",\\n    \\\"GraphRAGComponent\\\",\\n    \\\"HCDVectorStoreComponent\\\",\\n]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/datastax/src/lfx_datastax/base/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"87050bd92a78af5f087d338cc9ff01c4baa2c01092c734e0a867d06ab25075a8\",\"content\":\"\\\"\\\"\\\"Shared base infrastructure for the datastax bundle.\\n\\nHouses the mixin(s) every component in this bundle inherits from --\\npre-extraction this lived at ``lfx.base.datastax``.  Moved into the\\nbundle (not kept in lfx) because it is datastax-specific and only ever\\nimported by the datastax components.\\n\\\"\\\"\\\"\\n\\nfrom lfx_datastax.base.astradb_base import AstraDBBaseComponent\\n\\n__all__ = [\\n    \\\"AstraDBBaseComponent\\\",\\n]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/datastax/src/lfx_datastax/base/astradb_base.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"a7c03c670ea0caf779b68a7e563c9b3d54d9951f0ff7472199a1f9b9f301b2d2\",\"content\":\"import re\\nfrom collections import defaultdict\\nfrom dataclasses import asdict, dataclass, field\\nfrom typing import Any\\n\\nfrom astrapy import DataAPIClient, Database\\nfrom langchain_astradb.utils.astradb import _AstraDBCollectionEnvironment\\n\\nfrom lfx.custom.custom_component.component import Component\\nfrom lfx.io import (\\n    BoolInput,\\n    DropdownInput,\\n    IntInput,\\n    SecretStrInput,\\n    StrInput,\\n)\\nfrom lfx.log.logger import logger\\nfrom lfx.utils.ssrf_protection import validate_connector_url_for_ssrf\\n\\n\\ndef validate_api_endpoint(api_endpoint: str | None) -> str | None:\\n    \\\"\\\"\\\"SSRF-validate a tenant-controlled Astra/HCD Data API endpoint before it is dialed.\\n\\n    ``api_endpoint`` (and a ``https://``-prefixed ``database_name``) are free-form fields any flow\\n    author can set, and the resolved URL is handed to the astrapy client together with the\\n    configured application token. Route it through the shared connector guard -- the same one the\\n    sibling ``astradb_cql`` REST path uses -- so a blocked destination (RFC1918, cloud metadata,\\n    ...) is rejected before a client is built and before the token can leave the process.\\n\\n    An unset endpoint is passed through untouched: callers treat ``None``/empty as \\\"not configured\\n    yet\\\" and must not blow up in build_config paths.\\n\\n    Raises:\\n        SSRFProtectionError: If the endpoint is set and its host is blocked by connector policy.\\n    \\\"\\\"\\\"\\n    if api_endpoint:\\n        validate_connector_url_for_ssrf(api_endpoint)\\n    return api_endpoint\\n\\n\\nclass AstraDBBaseComponent(Component):\\n    \\\"\\\"\\\"Base class for AstraDB components with common functionality.\\\"\\\"\\\"\\n\\n    @dataclass\\n    class NewDatabaseInput:\\n        functionality: str = \\\"create\\\"\\n        fields: dict[str, dict] = field(\\n            default_factory=lambda: {\\n                \\\"data\\\": {\\n                    \\\"node\\\": {\\n                        \\\"name\\\": \\\"create_database\\\",\\n                        \\\"description\\\": \\\"Please allow several minutes for creation to complete.\\\",\\n                        \\\"display_name\\\": \\\"Create new database\\\",\\n                        \\\"field_order\\\": [\\n                            \\\"01_new_database_name\\\",\\n                            \\\"02_cloud_provider\\\",\\n                            \\\"03_region\\\",\\n                        ],\\n                        \\\"template\\\": {\\n                            \\\"01_new_database_name\\\": StrInput(\\n                                name=\\\"new_database_name\\\",\\n                                display_name=\\\"Name\\\",\\n                                info=\\\"Name of the new database to create in Astra DB.\\\",\\n                                required=True,\\n                            ),\\n                            \\\"02_cloud_provider\\\": DropdownInput(\\n                                name=\\\"cloud_provider\\\",\\n                                display_name=\\\"Cloud provider\\\",\\n                                info=\\\"Cloud provider for the new database.\\\",\\n                                options=[],\\n                                required=True,\\n                                real_time_refresh=True,\\n                            ),\\n                            \\\"03_region\\\": DropdownInput(\\n                                name=\\\"region\\\",\\n                                display_name=\\\"Region\\\",\\n                                info=\\\"Region for the new database.\\\",\\n                                options=[],\\n                                required=True,\\n                            ),\\n                        },\\n                    },\\n                }\\n            }\\n        )\\n\\n    @dataclass\\n    class NewCollectionInput:\\n        functionality: str = \\\"create\\\"\\n        fields: dict[str, dict] = field(\\n            default_factory=lambda: {\\n                \\\"data\\\": {\\n                    \\\"node\\\": {\\n                        \\\"name\\\": \\\"create_collection\\\",\\n                        \\\"description\\\": \\\"Please allow several seconds for creation to complete.\\\",\\n                        \\\"display_name\\\": \\\"Create new collection\\\",\\n                        \\\"field_order\\\": [\\n                            \\\"01_new_collection_name\\\",\\n                            \\\"02_embedding_generation_provider\\\",\\n                            \\\"03_embedding_generation_model\\\",\\n                            \\\"04_dimension\\\",\\n                        ],\\n                        \\\"template\\\": {\\n                            \\\"01_new_collection_name\\\": StrInput(\\n                                name=\\\"new_collection_name\\\",\\n                                display_name=\\\"Name\\\",\\n                                info=\\\"Name of the new collection to create in Astra DB.\\\",\\n                                required=True,\\n                            ),\\n                            \\\"02_embedding_generation_provider\\\": DropdownInput(\\n                                name=\\\"embedding_generation_provider\\\",\\n                                display_name=\\\"Embedding generation method\\\",\\n                                info=\\\"Provider to use for generating embeddings.\\\",\\n                                helper_text=(\\n                                    \\\"To create collections with more embedding provider options, go to \\\"\\n                                    '<a class=\\\"underline\\\" href=\\\"https://astra.datastax.com/\\\" target=\\\" _blank\\\" '\\n                                    'rel=\\\"noopener noreferrer\\\">your database in Astra DB</a>'\\n                                ),\\n                                real_time_refresh=True,\\n                                required=True,\\n                                options=[],\\n                            ),\\n                            \\\"03_embedding_generation_model\\\": DropdownInput(\\n                                name=\\\"embedding_generation_model\\\",\\n                                display_name=\\\"Embedding model\\\",\\n                                info=\\\"Model to use for generating embeddings.\\\",\\n                                real_time_refresh=True,\\n                                options=[],\\n                            ),\\n                            \\\"04_dimension\\\": IntInput(\\n                                name=\\\"dimension\\\",\\n                                display_name=\\\"Dimensions\\\",\\n                                info=\\\"Dimensions of the embeddings to generate.\\\",\\n                                value=None,\\n                            ),\\n                        },\\n                    },\\n                }\\n            }\\n        )\\n\\n    inputs = [\\n        SecretStrInput(\\n            name=\\\"token\\\",\\n            display_name=\\\"Astra DB Application Token\\\",\\n            info=\\\"Authentication token for accessing Astra DB.\\\",\\n            value=\\\"ASTRA_DB_APPLICATION_TOKEN\\\",\\n            required=True,\\n            real_time_refresh=True,\\n            input_types=[],\\n        ),\\n        DropdownInput(\\n            name=\\\"environment\\\",\\n            display_name=\\\"Environment\\\",\\n            info=\\\"The environment for the Astra DB API Endpoint.\\\",\\n            options=[\\\"prod\\\", \\\"test\\\", \\\"dev\\\"],\\n            value=\\\"prod\\\",\\n            advanced=True,\\n            real_time_refresh=True,\\n            combobox=True,\\n        ),\\n        DropdownInput(\\n            name=\\\"database_name\\\",\\n            display_name=\\\"Database\\\",\\n            info=\\\"The Database name for the Astra DB instance.\\\",\\n            required=True,\\n            refresh_button=True,\\n            real_time_refresh=True,\\n            dialog_inputs=asdict(NewDatabaseInput()),\\n            combobox=True,\\n        ),\\n        DropdownInput(\\n            name=\\\"api_endpoint\\\",\\n            display_name=\\\"Astra DB API Endpoint\\\",\\n            info=\\\"The API Endpoint for the Astra DB instance. Supersedes database selection.\\\",\\n            advanced=True,\\n        ),\\n        DropdownInput(\\n            name=\\\"keyspace\\\",\\n            display_name=\\\"Keyspace\\\",\\n            info=\\\"Optional keyspace within Astra DB to use for the collection.\\\",\\n            advanced=True,\\n            options=[],\\n            real_time_refresh=True,\\n        ),\\n        DropdownInput(\\n            name=\\\"collection_name\\\",\\n            display_name=\\\"Collection\\\",\\n            info=\\\"The name of the collection within Astra DB where the vectors will be stored.\\\",\\n            required=True,\\n            refresh_button=True,\\n            real_time_refresh=True,\\n            dialog_inputs=asdict(NewCollectionInput()),\\n            combobox=True,\\n            show=False,\\n        ),\\n        BoolInput(\\n            name=\\\"autodetect_collection\\\",\\n            display_name=\\\"Autodetect Collection\\\",\\n            info=\\\"Boolean flag to determine whether to autodetect the collection.\\\",\\n            advanced=True,\\n            value=True,\\n        ),\\n    ]\\n\\n    @classmethod\\n    def get_environment(cls, environment: str | None = None) -> str:\\n        if not environment:\\n            return \\\"prod\\\"\\n        return environment\\n\\n    @classmethod\\n    def map_cloud_providers(cls, token: str, environment: str | None = None) -> dict[str, dict[str, Any]]:\\n        \\\"\\\"\\\"Fetch all available cloud providers and regions.\\\"\\\"\\\"\\n        try:\\n            # Get the admin object\\n            client = DataAPIClient(environment=cls.get_environment(environment))\\n            admin_client = client.get_admin(token=token)\\n\\n            # Get the list of available regions\\n            available_regions = admin_client.find_available_regions(only_org_enabled_regions=True)\\n\\n            provider_mapping: dict[str, dict[str, str]] = {\\n                \\\"AWS\\\": {\\\"name\\\": \\\"Amazon Web Services\\\", \\\"id\\\": \\\"aws\\\"},\\n                \\\"GCP\\\": {\\\"name\\\": \\\"Google Cloud Platform\\\", \\\"id\\\": \\\"gcp\\\"},\\n                \\\"Azure\\\": {\\\"name\\\": \\\"Microsoft Azure\\\", \\\"id\\\": \\\"azure\\\"},\\n            }\\n\\n            result: dict[str, dict[str, Any]] = {}\\n            for region_info in available_regions:\\n                cloud_provider = region_info.cloud_provider\\n                region = region_info.name\\n\\n                if cloud_provider in provider_mapping:\\n                    provider_name = provider_mapping[cloud_provider][\\\"name\\\"]\\n                    provider_id = provider_mapping[cloud_provider][\\\"id\\\"]\\n\\n                    if provider_name not in result:\\n                        result[provider_name] = {\\\"id\\\": provider_id, \\\"regions\\\": []}\\n\\n                    result[provider_name][\\\"regions\\\"].append(region)\\n        except Exception as e:  # noqa: BLE001\\n            logger.debug(\\\"Error fetching cloud providers: %s\\\", e)\\n            return {}\\n        else:\\n            return result\\n\\n    @classmethod\\n    def get_vectorize_providers(cls, token: str, environment: str | None = None, api_endpoint: str | None = None):\\n        # Fed a build_config value; validate before the blanket except below can swallow the error.\\n        validate_api_endpoint(api_endpoint)\\n        try:\\n            # Get the admin object\\n            client = DataAPIClient(environment=cls.get_environment(environment))\\n            admin_client = client.get_admin()\\n            db_admin = admin_client.get_database_admin(api_endpoint, token=token)\\n\\n            # Get the list of embedding providers\\n            embedding_providers = db_admin.find_embedding_providers()\\n\\n            vectorize_providers_mapping = {}\\n            # Map the provider display name to the provider key and models\\n            for (\\n                provider_key,\\n                provider_data,\\n            ) in embedding_providers.embedding_providers.items():\\n                # Get the provider display name and models\\n                display_name = provider_data.display_name\\n                models = [model.name for model in provider_data.models]\\n\\n                # Build our mapping\\n                vectorize_providers_mapping[display_name] = [provider_key, models]\\n\\n            # Sort the resulting dictionary\\n            return defaultdict(list, dict(sorted(vectorize_providers_mapping.items())))\\n        except Exception as _:  # noqa: BLE001\\n            return {}\\n\\n    @classmethod\\n    async def create_database_api(\\n        cls,\\n        new_database_name: str,\\n        cloud_provider: str,\\n        region: str,\\n        token: str,\\n        environment: str | None = None,\\n        keyspace: str | None = None,\\n    ):\\n        # Get the environment, set to prod if null like\\n        my_env = cls.get_environment(environment)\\n\\n        # Initialize the Data API client\\n        client = DataAPIClient(environment=my_env)\\n\\n        # Get the admin object\\n        admin_client = client.get_admin(token=token)\\n\\n        # Raise a value error if name isn't provided\\n        if not new_database_name:\\n            msg = \\\"Database name is required to create a new database.\\\"\\n            raise ValueError(msg)\\n\\n        # Call the create database function\\n        return await admin_client.async_create_database(\\n            name=new_database_name,\\n            cloud_provider=cls.map_cloud_providers(token=token, environment=my_env)[cloud_provider][\\\"id\\\"],\\n            region=region,\\n            keyspace=keyspace,\\n            wait_until_active=False,\\n        )\\n\\n    @classmethod\\n    async def create_collection_api(\\n        cls,\\n        new_collection_name: str,\\n        token: str,\\n        api_endpoint: str,\\n        environment: str | None = None,\\n        keyspace: str | None = None,\\n        dimension: int | None = None,\\n        embedding_generation_provider: str | None = None,\\n        embedding_generation_model: str | None = None,\\n    ):\\n        # Fed a build_config value; validate before the endpoint is dialed with the token.\\n        validate_api_endpoint(api_endpoint)\\n\\n        # Build vectorize options, if needed\\n        vectorize_options = None\\n        if not dimension:\\n            try:\\n                from langchain_astradb import VectorServiceOptions\\n            except ImportError as e:\\n                msg = (\\n                    \\\"langchain-astradb is required to create AstraDB collections with \\\"\\n                    \\\"Astra Vectorize embeddings. Please install it with \\\"\\n                    \\\"`pip install langchain-astradb`.\\\"\\n                )\\n                raise ImportError(msg) from e\\n\\n            environment = cls.get_environment(environment)\\n            providers = cls.get_vectorize_providers(token=token, environment=environment, api_endpoint=api_endpoint)\\n            vectorize_options = VectorServiceOptions(\\n                provider=providers.get(embedding_generation_provider, [None, []])[0],\\n                model_name=embedding_generation_model,\\n            )\\n\\n        # Raise a value error if name isn't provided\\n        if not new_collection_name:\\n            msg = \\\"Collection name is required to create a new collection.\\\"\\n            raise ValueError(msg)\\n\\n        # Define the base arguments being passed to the create collection function\\n        base_args = {\\n            \\\"collection_name\\\": new_collection_name,\\n            \\\"token\\\": token,\\n            \\\"api_endpoint\\\": api_endpoint,\\n            \\\"keyspace\\\": keyspace,\\n            \\\"environment\\\": environment,\\n            \\\"embedding_dimension\\\": dimension,\\n            \\\"collection_vector_service_options\\\": vectorize_options,\\n        }\\n\\n        _AstraDBCollectionEnvironment(**base_args)\\n\\n    @classmethod\\n    def get_database_list_static(cls, token: str, environment: str | None = None):\\n        try:\\n            environment = cls.get_environment(environment)\\n            client = DataAPIClient(environment=environment)\\n\\n            # Get the admin object\\n            admin_client = client.get_admin(token=token)\\n\\n            # Get the list of databases\\n            db_list = admin_client.list_databases()\\n\\n            # Generate the api endpoint for each database\\n            db_info_dict = {}\\n            for db in db_list:\\n                try:\\n                    # Get the API endpoint for the database\\n                    api_endpoints = [db_reg.api_endpoint for db_reg in db.regions]\\n\\n                    # Get the number of collections\\n                    try:\\n                        # Get the number of collections in the database\\n                        num_collections = len(\\n                            client.get_database(\\n                                api_endpoints[0],\\n                                token=token,\\n                            ).list_collection_names()\\n                        )\\n                    except Exception:  # noqa: BLE001\\n                        if db.status != \\\"PENDING\\\":\\n                            continue\\n                        num_collections = 0\\n\\n                    # Add the database to the dictionary\\n                    db_info_dict[db.name] = {\\n                        \\\"api_endpoints\\\": api_endpoints,\\n                        \\\"keyspaces\\\": db.keyspaces,\\n                        \\\"collections\\\": num_collections,\\n                        \\\"status\\\": db.status if db.status != \\\"ACTIVE\\\" else None,\\n                        \\\"org_id\\\": db.org_id if db.org_id else None,\\n                    }\\n                except Exception as e:  # noqa: BLE001\\n                    logger.debug(\\\"Failed to get metadata for database %s: %s\\\", db.name, e)\\n        except Exception as e:  # noqa: BLE001\\n            logger.debug(\\\"Error fetching database list: %s\\\", e)\\n            return {}\\n        else:\\n            return db_info_dict\\n\\n    def get_database_list(self):\\n        return self.get_database_list_static(\\n            token=self.token,\\n            environment=self.environment,\\n        )\\n\\n    @classmethod\\n    def get_api_endpoint_static(\\n        cls,\\n        token: str,\\n        environment: str | None = None,\\n        api_endpoint: str | None = None,\\n        database_name: str | None = None,\\n    ):\\n        # If the api_endpoint is set, return it. Both this and the url-shaped database_name below\\n        # are tenant-controlled, so SSRF-validate them before any caller dials them with the token.\\n        if api_endpoint:\\n            return validate_api_endpoint(api_endpoint)\\n\\n        # Check if the database_name is like a url\\n        if database_name and database_name.startswith(\\\"https://\\\"):\\n            return validate_api_endpoint(database_name)\\n\\n        # If the database is not set, nothing we can do.\\n        if not database_name:\\n            return None\\n\\n        # Grab the database object\\n        environment = cls.get_environment(environment)\\n        db = cls.get_database_list_static(token=token, environment=environment).get(database_name)\\n        if not db:\\n            return None\\n\\n        # Otherwise, get the URL from the database list\\n        endpoints = db.get(\\\"api_endpoints\\\") or []\\n        return endpoints[0] if endpoints else None\\n\\n    def get_api_endpoint(self):\\n        return self.get_api_endpoint_static(\\n            token=self.token,\\n            environment=self.environment,\\n            api_endpoint=self.api_endpoint,\\n            database_name=self.database_name,\\n        )\\n\\n    @classmethod\\n    def get_database_id_static(cls, api_endpoint: str) -> str | None:\\n        # Pattern matches standard UUID format: 8-4-4-4-12 hexadecimal characters\\n        uuid_pattern = r\\\"[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}\\\"\\n        match = re.search(uuid_pattern, api_endpoint)\\n\\n        return match.group(0) if match else None\\n\\n    def get_database_id(self):\\n        return self.get_database_id_static(api_endpoint=self.get_api_endpoint())\\n\\n    def get_keyspace(self):\\n        keyspace = self.keyspace\\n\\n        if keyspace:\\n            return keyspace.strip()\\n\\n        return \\\"default_keyspace\\\"\\n\\n    def get_database_object(self, api_endpoint: str | None = None):\\n        # Resolve (and SSRF-validate) the endpoint OUTSIDE the try below: callers pass build_config\\n        # values straight through, and the blanket handler would otherwise remap the SSRF error\\n        # into a generic ValueError after the client had already been constructed.\\n        resolved_endpoint = validate_api_endpoint(api_endpoint) or self.get_api_endpoint()\\n        try:\\n            client = DataAPIClient(environment=self.environment)\\n\\n            return client.get_database(\\n                resolved_endpoint,\\n                token=self.token,\\n                keyspace=self.get_keyspace(),\\n            )\\n        except Exception as e:\\n            msg = f\\\"Error fetching database object: {e}\\\"\\n            raise ValueError(msg) from e\\n\\n    def collection_data(self, collection_name: str, database: Database = None):\\n        # Resolve the endpoint (SSRF-validated) before the try so a blocked host never reaches the\\n        # client; the handler below deliberately swallows errors for this best-effort UI count.\\n        resolved_endpoint = None if database else self.get_api_endpoint()\\n        try:\\n            if not database:\\n                client = DataAPIClient(environment=self.environment)\\n\\n                database = client.get_database(\\n                    resolved_endpoint,\\n                    token=self.token,\\n                    keyspace=self.get_keyspace(),\\n                )\\n\\n            collection = database.get_collection(collection_name)\\n\\n            return collection.estimated_document_count()\\n        except Exception as e:  # noqa: BLE001\\n            self.log(f\\\"Error checking collection data: {e}\\\")\\n\\n            return None\\n\\n    def _initialize_database_options(self):\\n        try:\\n            db_list = self.get_database_list()\\n            if not db_list:\\n                return []\\n            return [\\n                {\\n                    \\\"name\\\": name,\\n                    \\\"status\\\": info[\\\"status\\\"],\\n                    \\\"collections\\\": info[\\\"collections\\\"],\\n                    \\\"api_endpoints\\\": info[\\\"api_endpoints\\\"],\\n                    \\\"keyspaces\\\": info[\\\"keyspaces\\\"],\\n                    \\\"org_id\\\": info[\\\"org_id\\\"],\\n                }\\n                for name, info in db_list.items()\\n            ]\\n        except Exception as e:  # noqa: BLE001\\n            logger.debug(\\\"Error fetching database options: %s\\\", e)\\n            return []\\n\\n    @classmethod\\n    def get_provider_icon(cls, collection=None, provider_name: str | None = None) -> str:\\n        # Get the provider name from the collection\\n        provider_name = provider_name or (\\n            collection.definition.vector.service.provider\\n            if (\\n                collection\\n                and collection.definition\\n                and collection.definition.vector\\n                and collection.definition.vector.service\\n            )\\n            else None\\n        )\\n\\n        # If there is no provider, use the vector store icon\\n        if not provider_name or provider_name.lower() == \\\"bring your own\\\":\\n            return \\\"vectorstores\\\"\\n\\n        # Map provider casings\\n        case_map = {\\n            \\\"nvidia\\\": \\\"NVIDIA\\\",\\n            \\\"openai\\\": \\\"OpenAI\\\",\\n            \\\"amazon bedrock\\\": \\\"AmazonBedrockEmbeddings\\\",\\n            \\\"azure openai\\\": \\\"AzureOpenAiEmbeddings\\\",\\n            \\\"cohere\\\": \\\"Cohere\\\",\\n            \\\"jina ai\\\": \\\"JinaAI\\\",\\n            \\\"mistral ai\\\": \\\"MistralAI\\\",\\n            \\\"upstage\\\": \\\"Upstage\\\",\\n            \\\"voyage ai\\\": \\\"VoyageAI\\\",\\n        }\\n\\n        # Adjust the casing on some like nvidia\\n        return case_map[provider_name.lower()] if provider_name.lower() in case_map else provider_name.title()\\n\\n    def _initialize_collection_options(self, api_endpoint: str | None = None):\\n        # Nothing to generate if we don't have an API endpoint yet\\n        api_endpoint = api_endpoint or self.get_api_endpoint()\\n        if not api_endpoint:\\n            return []\\n\\n        # Retrieve the database object\\n        database = self.get_database_object(api_endpoint=api_endpoint)\\n\\n        # Get the list of collections\\n        collection_list = database.list_collections(keyspace=self.get_keyspace())\\n\\n        # Return the list of collections and metadata associated\\n        return [\\n            {\\n                \\\"name\\\": col.name,\\n                \\\"records\\\": self.collection_data(collection_name=col.name, database=database),\\n                \\\"provider\\\": (\\n                    col.definition.vector.service.provider\\n                    if col.definition.vector and col.definition.vector.service\\n                    else None\\n                ),\\n                \\\"icon\\\": self.get_provider_icon(collection=col),\\n                \\\"model\\\": (\\n                    col.definition.vector.service.model_name\\n                    if col.definition.vector and col.definition.vector.service\\n                    else None\\n                ),\\n            }\\n            for col in collection_list\\n        ]\\n\\n    def reset_provider_options(self, build_config: dict) -> dict:\\n        \\\"\\\"\\\"Reset provider options and related configurations in the build_config dictionary.\\\"\\\"\\\"\\n        # Extract template path for cleaner access\\n        template = build_config[\\\"collection_name\\\"][\\\"dialog_inputs\\\"][\\\"fields\\\"][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"]\\n\\n        # Get vectorize providers\\n        vectorize_providers_api = self.get_vectorize_providers(\\n            token=self.token,\\n            environment=self.environment,\\n            api_endpoint=build_config[\\\"api_endpoint\\\"][\\\"value\\\"],\\n        )\\n\\n        # Create a new dictionary with \\\"Bring your own\\\" first\\n        vectorize_providers: dict[str, list[list[str]]] = {\\\"Bring your own\\\": [[], []]}\\n\\n        # Add the remaining items (only Nvidia) from the original dictionary\\n        vectorize_providers.update(\\n            {\\n                k: v\\n                for k, v in vectorize_providers_api.items()\\n                if k.lower() in [\\\"nvidia\\\"]  # TODO: Eventually support more\\n            }\\n        )\\n\\n        # Set provider options\\n        provider_field = \\\"02_embedding_generation_provider\\\"\\n        template[provider_field][\\\"options\\\"] = list(vectorize_providers.keys())\\n\\n        # Add metadata for each provider option\\n        template[provider_field][\\\"options_metadata\\\"] = [\\n            {\\\"icon\\\": self.get_provider_icon(provider_name=provider)} for provider in template[provider_field][\\\"options\\\"]\\n        ]\\n\\n        # Get selected embedding provider\\n        embedding_provider = template[provider_field][\\\"value\\\"]\\n        is_bring_your_own = embedding_provider and embedding_provider == \\\"Bring your own\\\"\\n\\n        # Configure embedding model field\\n        model_field = \\\"03_embedding_generation_model\\\"\\n        template[model_field].update(\\n            {\\n                \\\"options\\\": vectorize_providers.get(embedding_provider, [[], []])[1],\\n                \\\"placeholder\\\": \\\"Bring your own\\\" if is_bring_your_own else None,\\n                \\\"readonly\\\": is_bring_your_own,\\n                \\\"required\\\": not is_bring_your_own,\\n                \\\"value\\\": None,\\n            }\\n        )\\n\\n        # If this is a bring your own, set dimensions to 0\\n        return self.reset_dimension_field(build_config)\\n\\n    def reset_dimension_field(self, build_config: dict) -> dict:\\n        \\\"\\\"\\\"Reset dimension field options based on provided configuration.\\\"\\\"\\\"\\n        # Extract template path for cleaner access\\n        template = build_config[\\\"collection_name\\\"][\\\"dialog_inputs\\\"][\\\"fields\\\"][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"]\\n\\n        # Get selected embedding model\\n        provider_field = \\\"02_embedding_generation_provider\\\"\\n        embedding_provider = template[provider_field][\\\"value\\\"]\\n        is_bring_your_own = embedding_provider and embedding_provider == \\\"Bring your own\\\"\\n\\n        # Configure dimension field\\n        dimension_field = \\\"04_dimension\\\"\\n        dimension_value = 1024 if not is_bring_your_own else None  # TODO: Dynamically figure this out\\n        template[dimension_field].update(\\n            {\\n                \\\"placeholder\\\": dimension_value,\\n                \\\"value\\\": dimension_value,\\n                \\\"readonly\\\": not is_bring_your_own,\\n                \\\"required\\\": is_bring_your_own,\\n            }\\n        )\\n\\n        return build_config\\n\\n    def reset_collection_list(self, build_config: dict) -> dict:\\n        \\\"\\\"\\\"Reset collection list options based on provided configuration.\\\"\\\"\\\"\\n        # Get collection options\\n        collection_options = self._initialize_collection_options(api_endpoint=build_config[\\\"api_endpoint\\\"][\\\"value\\\"])\\n        # Update collection configuration\\n        collection_config = build_config[\\\"collection_name\\\"]\\n        collection_config.update(\\n            {\\n                \\\"options\\\": [col[\\\"name\\\"] for col in collection_options],\\n                \\\"options_metadata\\\": [{k: v for k, v in col.items() if k != \\\"name\\\"} for col in collection_options],\\n            }\\n        )\\n\\n        # Reset selected collection if not in options\\n        if collection_config[\\\"value\\\"] not in collection_config[\\\"options\\\"]:\\n            collection_config[\\\"value\\\"] = \\\"\\\"\\n\\n        # Set advanced status based on database selection\\n        collection_config[\\\"show\\\"] = bool(build_config[\\\"database_name\\\"][\\\"value\\\"])\\n\\n        return build_config\\n\\n    def reset_database_list(self, build_config: dict) -> dict:\\n        \\\"\\\"\\\"Reset database list options and related configurations.\\\"\\\"\\\"\\n        # Get database options\\n        database_options = self._initialize_database_options()\\n\\n        # Update cloud provider options\\n        template = build_config[\\\"database_name\\\"][\\\"dialog_inputs\\\"][\\\"fields\\\"][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"]\\n        template[\\\"02_cloud_provider\\\"][\\\"options\\\"] = list(\\n            self.map_cloud_providers(\\n                token=self.token,\\n                environment=self.environment,\\n            ).keys()\\n        )\\n\\n        # Update database configuration\\n        database_config = build_config[\\\"database_name\\\"]\\n        database_config.update(\\n            {\\n                \\\"options\\\": [db[\\\"name\\\"] for db in database_options],\\n                \\\"options_metadata\\\": [{k: v for k, v in db.items() if k != \\\"name\\\"} for db in database_options],\\n            }\\n        )\\n\\n        # Reset selections if value not in options\\n        if database_config[\\\"value\\\"] not in database_config[\\\"options\\\"]:\\n            database_config[\\\"value\\\"] = \\\"\\\"\\n            build_config[\\\"api_endpoint\\\"][\\\"options\\\"] = []\\n            build_config[\\\"api_endpoint\\\"][\\\"value\\\"] = \\\"\\\"\\n            build_config[\\\"collection_name\\\"][\\\"show\\\"] = False\\n\\n        # Set advanced status based on token presence\\n        database_config[\\\"show\\\"] = bool(build_config[\\\"token\\\"][\\\"value\\\"])\\n\\n        return build_config\\n\\n    def reset_build_config(self, build_config: dict) -> dict:\\n        \\\"\\\"\\\"Reset all build configuration options to default empty state.\\\"\\\"\\\"\\n        # Reset database configuration\\n        database_config = build_config[\\\"database_name\\\"]\\n        database_config.update({\\\"options\\\": [], \\\"options_metadata\\\": [], \\\"value\\\": \\\"\\\", \\\"show\\\": False})\\n        build_config[\\\"api_endpoint\\\"][\\\"options\\\"] = []\\n        build_config[\\\"api_endpoint\\\"][\\\"value\\\"] = \\\"\\\"\\n\\n        # Reset collection configuration\\n        collection_config = build_config[\\\"collection_name\\\"]\\n        collection_config.update({\\\"options\\\": [], \\\"options_metadata\\\": [], \\\"value\\\": \\\"\\\", \\\"show\\\": False})\\n\\n        return build_config\\n\\n    async def update_build_config(\\n        self,\\n        build_config: dict,\\n        field_value: str | dict,\\n        field_name: str | None = None,\\n    ) -> dict:\\n        \\\"\\\"\\\"Update build configuration based on field name and value.\\\"\\\"\\\"\\n        # Early return if no token provided\\n        if not self.token:\\n            return self.reset_build_config(build_config)\\n\\n        # Database creation callback\\n        if field_name == \\\"database_name\\\" and isinstance(field_value, dict):\\n            if \\\"01_new_database_name\\\" in field_value:\\n                await self._create_new_database(build_config, field_value)\\n                return self.reset_collection_list(build_config)\\n            return self._update_cloud_regions(build_config, field_value)\\n\\n        # Collection creation callback\\n        if field_name == \\\"collection_name\\\" and isinstance(field_value, dict):\\n            # Case 1: New collection creation\\n            if \\\"01_new_collection_name\\\" in field_value:\\n                await self._create_new_collection(build_config, field_value)\\n                return build_config\\n\\n            # Case 2: Update embedding provider options\\n            if \\\"02_embedding_generation_provider\\\" in field_value:\\n                return self.reset_provider_options(build_config)\\n\\n            # Case 3: Update dimension field\\n            if \\\"03_embedding_generation_model\\\" in field_value:\\n                return self.reset_dimension_field(build_config)\\n\\n        # Initial execution or token/environment change\\n        first_run = field_name == \\\"embedding_model\\\" and not field_value and not build_config[\\\"database_name\\\"][\\\"options\\\"]\\n        if first_run or field_name in {\\\"token\\\", \\\"environment\\\"}:\\n            return self.reset_database_list(build_config)\\n\\n        # Database selection change\\n        if field_name == \\\"database_name\\\" and not isinstance(field_value, dict):\\n            return self._handle_database_selection(build_config, field_value)\\n\\n        # Keyspace selection change\\n        if field_name == \\\"keyspace\\\":\\n            return self.reset_collection_list(build_config)\\n\\n        # Collection selection change\\n        if field_name == \\\"collection_name\\\" and not isinstance(field_value, dict):\\n            return self._handle_collection_selection(build_config, field_value)\\n\\n        return build_config\\n\\n    async def _create_new_database(self, build_config: dict, field_value: dict) -> None:\\n        \\\"\\\"\\\"Create a new database and update build config options.\\\"\\\"\\\"\\n        try:\\n            await self.create_database_api(\\n                new_database_name=field_value[\\\"01_new_database_name\\\"],\\n                token=self.token,\\n                keyspace=self.get_keyspace(),\\n                environment=self.environment,\\n                cloud_provider=field_value[\\\"02_cloud_provider\\\"],\\n                region=field_value[\\\"03_region\\\"],\\n            )\\n        except Exception as e:\\n            msg = f\\\"Error creating database: {e}\\\"\\n            raise ValueError(msg) from e\\n\\n        build_config[\\\"database_name\\\"][\\\"options\\\"].append(field_value[\\\"01_new_database_name\\\"])\\n        build_config[\\\"database_name\\\"][\\\"options_metadata\\\"].append(\\n            {\\n                \\\"status\\\": \\\"PENDING\\\",\\n                \\\"collections\\\": 0,\\n                \\\"api_endpoints\\\": [],\\n                \\\"keyspaces\\\": [self.get_keyspace()],\\n                \\\"org_id\\\": None,\\n            }\\n        )\\n\\n    def _update_cloud_regions(self, build_config: dict, field_value: dict) -> dict:\\n        \\\"\\\"\\\"Update cloud provider regions in build config.\\\"\\\"\\\"\\n        cloud_provider = field_value[\\\"02_cloud_provider\\\"]\\n\\n        # Update the region options based on the selected cloud provider\\n        template = build_config[\\\"database_name\\\"][\\\"dialog_inputs\\\"][\\\"fields\\\"][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"]\\n        template[\\\"03_region\\\"][\\\"options\\\"] = self.map_cloud_providers(\\n            token=self.token,\\n            environment=self.environment,\\n        )[cloud_provider][\\\"regions\\\"]\\n\\n        # Reset the the 03_region value if it's not in the new options\\n        if template[\\\"03_region\\\"][\\\"value\\\"] not in template[\\\"03_region\\\"][\\\"options\\\"]:\\n            template[\\\"03_region\\\"][\\\"value\\\"] = None\\n\\n        return build_config\\n\\n    async def _create_new_collection(self, build_config: dict, field_value: dict) -> None:\\n        \\\"\\\"\\\"Create a new collection and update build config options.\\\"\\\"\\\"\\n        embedding_provider = field_value.get(\\\"02_embedding_generation_provider\\\")\\n        try:\\n            await self.create_collection_api(\\n                new_collection_name=field_value[\\\"01_new_collection_name\\\"],\\n                token=self.token,\\n                api_endpoint=build_config[\\\"api_endpoint\\\"][\\\"value\\\"],\\n                environment=self.environment,\\n                keyspace=self.get_keyspace(),\\n                dimension=field_value.get(\\\"04_dimension\\\") if embedding_provider == \\\"Bring your own\\\" else None,\\n                embedding_generation_provider=embedding_provider,\\n                embedding_generation_model=field_value.get(\\\"03_embedding_generation_model\\\"),\\n            )\\n        except Exception as e:\\n            msg = f\\\"Error creating collection: {e}\\\"\\n            raise ValueError(msg) from e\\n\\n        provider = embedding_provider.lower() if embedding_provider and embedding_provider != \\\"Bring your own\\\" else None\\n        build_config[\\\"collection_name\\\"].update(\\n            {\\n                \\\"value\\\": field_value[\\\"01_new_collection_name\\\"],\\n                \\\"options\\\": build_config[\\\"collection_name\\\"][\\\"options\\\"] + [field_value[\\\"01_new_collection_name\\\"]],\\n            }\\n        )\\n\\n        # Update collection metadata\\n        build_config[\\\"collection_name\\\"][\\\"options_metadata\\\"].append(\\n            {\\n                \\\"records\\\": 0,\\n                \\\"provider\\\": provider,\\n                \\\"icon\\\": self.get_provider_icon(provider_name=provider),\\n                \\\"model\\\": field_value.get(\\\"03_embedding_generation_model\\\"),\\n            }\\n        )\\n\\n    def _handle_database_selection(self, build_config: dict, field_value: str) -> dict:\\n        \\\"\\\"\\\"Handle database selection and update related configurations.\\\"\\\"\\\"\\n        build_config = self.reset_database_list(build_config)\\n\\n        # Reset collection list if database selection changes\\n        if field_value not in build_config[\\\"database_name\\\"][\\\"options\\\"]:\\n            build_config[\\\"database_name\\\"][\\\"value\\\"] = \\\"\\\"\\n            return build_config\\n\\n        # Get the api endpoint for the selected database\\n        index = build_config[\\\"database_name\\\"][\\\"options\\\"].index(field_value)\\n        build_config[\\\"api_endpoint\\\"][\\\"options\\\"] = build_config[\\\"database_name\\\"][\\\"options_metadata\\\"][index][\\n            \\\"api_endpoints\\\"\\n        ]\\n        build_config[\\\"api_endpoint\\\"][\\\"value\\\"] = build_config[\\\"database_name\\\"][\\\"options_metadata\\\"][index][\\n            \\\"api_endpoints\\\"\\n        ][0]\\n\\n        # Get the org_id for the selected database\\n        org_id = build_config[\\\"database_name\\\"][\\\"options_metadata\\\"][index][\\\"org_id\\\"]\\n        if not org_id:\\n            return build_config\\n\\n        # Update the list of keyspaces based on the db info\\n        build_config[\\\"keyspace\\\"][\\\"options\\\"] = build_config[\\\"database_name\\\"][\\\"options_metadata\\\"][index][\\\"keyspaces\\\"]\\n        build_config[\\\"keyspace\\\"][\\\"value\\\"] = (\\n            build_config[\\\"keyspace\\\"][\\\"options\\\"] and build_config[\\\"keyspace\\\"][\\\"options\\\"][0]\\n            if build_config[\\\"keyspace\\\"][\\\"value\\\"] not in build_config[\\\"keyspace\\\"][\\\"options\\\"]\\n            else build_config[\\\"keyspace\\\"][\\\"value\\\"]\\n        )\\n\\n        # Get the database id for the selected database\\n        db_id = self.get_database_id_static(api_endpoint=build_config[\\\"api_endpoint\\\"][\\\"value\\\"])\\n        keyspace = self.get_keyspace()\\n\\n        # Update the helper text for the embedding provider field\\n        template = build_config[\\\"collection_name\\\"][\\\"dialog_inputs\\\"][\\\"fields\\\"][\\\"data\\\"][\\\"node\\\"][\\\"template\\\"]\\n        template[\\\"02_embedding_generation_provider\\\"][\\\"helper_text\\\"] = (\\n            \\\"To create collections with more embedding provider options, go to \\\"\\n            f'<a class=\\\"underline\\\" target=\\\"_blank\\\" rel=\\\"noopener noreferrer\\\" '\\n            f'href=\\\"https://astra.datastax.com/org/{org_id}/database/{db_id}/data-explorer?createCollection=1&namespace={keyspace}\\\">'\\n            \\\"your database in Astra DB</a>.\\\"\\n        )\\n\\n        # Reset provider options\\n        build_config = self.reset_provider_options(build_config)\\n\\n        return self.reset_collection_list(build_config)\\n\\n    def _handle_collection_selection(self, build_config: dict, field_value: str) -> dict:\\n        \\\"\\\"\\\"Handle collection selection and update embedding options.\\\"\\\"\\\"\\n        build_config[\\\"autodetect_collection\\\"][\\\"value\\\"] = True\\n        build_config = self.reset_collection_list(build_config)\\n\\n        # Reset embedding model if collection selection changes\\n        if field_value and field_value not in build_config[\\\"collection_name\\\"][\\\"options\\\"]:\\n            build_config[\\\"collection_name\\\"][\\\"options\\\"].append(field_value)\\n            build_config[\\\"collection_name\\\"][\\\"options_metadata\\\"].append(\\n                {\\n                    \\\"records\\\": 0,\\n                    \\\"provider\\\": None,\\n                    \\\"icon\\\": \\\"vectorstores\\\",\\n                    \\\"model\\\": None,\\n                }\\n            )\\n            build_config[\\\"autodetect_collection\\\"][\\\"value\\\"] = False\\n\\n        return build_config\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/datastax/src/lfx_datastax/components/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/datastax/src/lfx_datastax/components/cassandra/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"ffe9a6cd9151d1604724b68e1d7c034c154238546db6e27abb1c2192210f09f3\",\"content\":\"\\\"\\\"\\\"Cassandra components shipped by the DataStax extension.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom typing import TYPE_CHECKING, Any\\n\\nfrom lfx.components._importing import import_mod\\n\\nif TYPE_CHECKING:\\n    from .cassandra import CassandraVectorStoreComponent\\n    from .cassandra_chat import CassandraChatMemory\\n    from .cassandra_graph import CassandraGraphVectorStoreComponent\\n\\n_dynamic_imports = {\\n    \\\"CassandraVectorStoreComponent\\\": \\\"cassandra\\\",\\n    \\\"CassandraGraphVectorStoreComponent\\\": \\\"cassandra_graph\\\",\\n    \\\"CassandraChatMemory\\\": \\\"cassandra_chat\\\",\\n}\\n\\n__all__ = [\\n    \\\"CassandraChatMemory\\\",\\n    \\\"CassandraGraphVectorStoreComponent\\\",\\n    \\\"CassandraVectorStoreComponent\\\",\\n]\\n\\n\\ndef __getattr__(attr_name: str) -> Any:\\n    \\\"\\\"\\\"Lazily import Cassandra components on attribute access.\\\"\\\"\\\"\\n    if attr_name not in _dynamic_imports:\\n        msg = f\\\"module '{__name__}' has no attribute '{attr_name}'\\\"\\n        raise AttributeError(msg)\\n    try:\\n        result = import_mod(attr_name, _dynamic_imports[attr_name], __spec__.parent)\\n    except (ModuleNotFoundError, ImportError, AttributeError) as e:\\n        msg = f\\\"Could not import '{attr_name}' from '{__name__}': {e}\\\"\\n        raise AttributeError(msg) from e\\n    globals()[attr_name] = result\\n    return result\\n\\n\\ndef __dir__() -> list[str]:\\n    return list(__all__)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/datastax/src/lfx_datastax/components/cassandra/cassandra.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"4e187171bdb530c9328567a01e43e9e50aabe7a4514df8390bc199b9d77e2d70\",\"content\":\"\\\"\\\"\\\"Cassandra vector-store component.\\\"\\\"\\\"\\n\\nfrom langchain_community.vectorstores import Cassandra\\n\\nfrom lfx.base.vectorstores.model import LCVectorStoreComponent, check_cached_vector_store\\nfrom lfx.helpers.data import docs_to_data\\nfrom lfx.inputs.inputs import BoolInput, DictInput, FloatInput\\nfrom lfx.io import (\\n    DropdownInput,\\n    HandleInput,\\n    IntInput,\\n    MessageTextInput,\\n    SecretStrInput,\\n)\\nfrom lfx.schema.data import Data\\n\\nDEFAULT_BATCH_SIZE = 16\\n\\n\\nclass CassandraVectorStoreComponent(LCVectorStoreComponent):\\n    display_name = \\\"Cassandra\\\"\\n    description = \\\"Cassandra Vector Store with search capabilities\\\"\\n    documentation = \\\"https://python.langchain.com/docs/modules/data_connection/vectorstores/integrations/cassandra\\\"\\n    name = \\\"Cassandra\\\"\\n    icon = \\\"Cassandra\\\"\\n\\n    inputs = [\\n        MessageTextInput(\\n            name=\\\"database_ref\\\",\\n            display_name=\\\"Contact Points / Astra Database ID\\\",\\n            info=\\\"Contact points for the database (or Astra DB database ID)\\\",\\n            required=True,\\n        ),\\n        MessageTextInput(\\n            name=\\\"username\\\", display_name=\\\"Username\\\", info=\\\"Username for the database (leave empty for Astra DB).\\\"\\n        ),\\n        SecretStrInput(\\n            name=\\\"token\\\",\\n            display_name=\\\"Password / Astra DB Token\\\",\\n            info=\\\"User password for the database (or Astra DB token).\\\",\\n            required=True,\\n        ),\\n        MessageTextInput(\\n            name=\\\"keyspace\\\",\\n            display_name=\\\"Keyspace\\\",\\n            info=\\\"Table Keyspace (or Astra DB namespace).\\\",\\n            required=True,\\n        ),\\n        MessageTextInput(\\n            name=\\\"table_name\\\",\\n            display_name=\\\"Table Name\\\",\\n            info=\\\"The name of the table (or Astra DB collection) where vectors will be stored.\\\",\\n            required=True,\\n        ),\\n        IntInput(\\n            name=\\\"ttl_seconds\\\",\\n            display_name=\\\"TTL Seconds\\\",\\n            info=\\\"Optional time-to-live for the added texts.\\\",\\n            advanced=True,\\n        ),\\n        IntInput(\\n            name=\\\"batch_size\\\",\\n            display_name=\\\"Batch Size\\\",\\n            info=\\\"Optional number of data to process in a single batch.\\\",\\n            value=DEFAULT_BATCH_SIZE,\\n            advanced=True,\\n        ),\\n        DropdownInput(\\n            name=\\\"setup_mode\\\",\\n            display_name=\\\"Setup Mode\\\",\\n            info=\\\"Configuration mode for setting up the Cassandra table, with options like 'Sync', 'Async', or 'Off'.\\\",\\n            options=[\\\"Sync\\\", \\\"Async\\\", \\\"Off\\\"],\\n            value=\\\"Sync\\\",\\n            advanced=True,\\n        ),\\n        DictInput(\\n            name=\\\"cluster_kwargs\\\",\\n            display_name=\\\"Cluster arguments\\\",\\n            info=\\\"Optional dictionary of additional keyword arguments for the Cassandra cluster.\\\",\\n            advanced=True,\\n            list=True,\\n        ),\\n        *LCVectorStoreComponent.inputs,\\n        HandleInput(name=\\\"embedding\\\", display_name=\\\"Embedding\\\", input_types=[\\\"Embeddings\\\"]),\\n        IntInput(\\n            name=\\\"number_of_results\\\",\\n            display_name=\\\"Number of Results\\\",\\n            info=\\\"Number of results to return.\\\",\\n            value=4,\\n            advanced=True,\\n        ),\\n        DropdownInput(\\n            name=\\\"search_type\\\",\\n            display_name=\\\"Search Type\\\",\\n            info=\\\"Search type to use\\\",\\n            options=[\\\"Similarity\\\", \\\"Similarity with score threshold\\\", \\\"MMR (Max Marginal Relevance)\\\"],\\n            value=\\\"Similarity\\\",\\n            advanced=True,\\n        ),\\n        FloatInput(\\n            name=\\\"search_score_threshold\\\",\\n            display_name=\\\"Search Score Threshold\\\",\\n            info=\\\"Minimum similarity score threshold for search results. \\\"\\n            \\\"(when using 'Similarity with score threshold')\\\",\\n            value=0,\\n            advanced=True,\\n        ),\\n        DictInput(\\n            name=\\\"search_filter\\\",\\n            display_name=\\\"Search Metadata Filter\\\",\\n            info=\\\"Optional dictionary of filters to apply to the search query.\\\",\\n            advanced=True,\\n            list=True,\\n        ),\\n        MessageTextInput(\\n            name=\\\"body_search\\\",\\n            display_name=\\\"Search Body\\\",\\n            info=\\\"Document textual search terms to apply to the search query.\\\",\\n            advanced=True,\\n        ),\\n        BoolInput(\\n            name=\\\"enable_body_search\\\",\\n            display_name=\\\"Enable Body Search\\\",\\n            info=\\\"Flag to enable body search. This must be enabled BEFORE the table is created.\\\",\\n            value=False,\\n            advanced=True,\\n        ),\\n    ]\\n\\n    @check_cached_vector_store\\n    def build_vector_store(self) -> Cassandra:\\n        try:\\n            import cassio\\n            from langchain_community.utilities.cassandra import SetupMode\\n        except ImportError as e:\\n            msg = \\\"Could not import cassio integration package. Please install it with `pip install cassio`.\\\"\\n            raise ImportError(msg) from e\\n\\n        from uuid import UUID\\n\\n        database_ref = self.database_ref\\n\\n        try:\\n            UUID(self.database_ref)\\n            is_astra = True\\n        except ValueError:\\n            is_astra = False\\n            if \\\",\\\" in self.database_ref:\\n                # use a copy because we can't change the type of the parameter\\n                database_ref = self.database_ref.split(\\\",\\\")\\n\\n        if is_astra:\\n            cassio.init(\\n                database_id=database_ref,\\n                token=self.token,\\n                cluster_kwargs=self.cluster_kwargs,\\n            )\\n        else:\\n            cassio.init(\\n                contact_points=database_ref,\\n                username=self.username,\\n                password=self.token,\\n                cluster_kwargs=self.cluster_kwargs,\\n            )\\n\\n        # Convert DataFrame to Data if needed using parent's method\\n        self.ingest_data = self._prepare_ingest_data()\\n\\n        documents = []\\n        for _input in self.ingest_data or []:\\n            if isinstance(_input, Data):\\n                documents.append(_input.to_lc_document())\\n            else:\\n                documents.append(_input)\\n\\n        body_index_options = [(\\\"index_analyzer\\\", \\\"STANDARD\\\")] if self.enable_body_search else None\\n\\n        if self.setup_mode == \\\"Off\\\":\\n            setup_mode = SetupMode.OFF\\n        elif self.setup_mode == \\\"Sync\\\":\\n            setup_mode = SetupMode.SYNC\\n        else:\\n            setup_mode = SetupMode.ASYNC\\n\\n        # The ingest write is synchronous, so ASYNC (async_setup plus an un-awaited\\n        # coroutine dimension) degrades to SYNC. OFF is kept: it drives skip_provisioning,\\n        # so overriding it would re-run the DDL against a pre-provisioned table.\\n        if documents and setup_mode is SetupMode.ASYNC:\\n            setup_mode = SetupMode.SYNC\\n\\n        table = Cassandra(\\n            embedding=self.embedding,\\n            table_name=self.table_name,\\n            keyspace=self.keyspace,\\n            ttl_seconds=self.ttl_seconds or None,\\n            body_index_options=body_index_options,\\n            setup_mode=setup_mode,\\n        )\\n\\n        if documents:\\n            self.log(f\\\"Adding {len(documents)} documents to the Vector Store.\\\")\\n            # batch_size is an add_texts parameter: from_documents leaked it through\\n            # **kwargs into Cassandra.__init__ and raised TypeError (#6255). add_texts\\n            # slices with range(0, n, batch_size), where a cleared field (IntInput\\n            # coerces to 0) raises and a negative value writes nothing while reporting\\n            # success -- both only after the table DDL has already run.\\n            batch_size = max(int(self.batch_size or DEFAULT_BATCH_SIZE), 1)\\n            table.add_documents(documents=documents, batch_size=batch_size)\\n        else:\\n            self.log(\\\"No documents to add to the Vector Store.\\\")\\n        return table\\n\\n    def _map_search_type(self) -> str:\\n        if self.search_type == \\\"Similarity with score threshold\\\":\\n            return \\\"similarity_score_threshold\\\"\\n        if self.search_type == \\\"MMR (Max Marginal Relevance)\\\":\\n            return \\\"mmr\\\"\\n        return \\\"similarity\\\"\\n\\n    def search_documents(self) -> list[Data]:\\n        vector_store = self.build_vector_store()\\n\\n        self.log(f\\\"Search input: {self.search_query}\\\")\\n        self.log(f\\\"Search type: {self.search_type}\\\")\\n        self.log(f\\\"Number of results: {self.number_of_results}\\\")\\n\\n        if self.search_query and isinstance(self.search_query, str) and self.search_query.strip():\\n            try:\\n                search_type = self._map_search_type()\\n                search_args = self._build_search_args()\\n\\n                self.log(f\\\"Search args: {search_args}\\\")\\n\\n                docs = vector_store.search(query=self.search_query, search_type=search_type, **search_args)\\n            except KeyError as e:\\n                if \\\"content\\\" in str(e):\\n                    msg = (\\n                        \\\"You should ingest data through Langflow (or LangChain) to query it in Langflow. \\\"\\n                        \\\"Your collection does not contain a field name 'content'.\\\"\\n                    )\\n                    raise ValueError(msg) from e\\n                raise\\n\\n            self.log(f\\\"Retrieved documents: {len(docs)}\\\")\\n\\n            data = docs_to_data(docs)\\n            self.status = data\\n            return data\\n        return []\\n\\n    def _build_search_args(self):\\n        args = {\\n            \\\"k\\\": self.number_of_results,\\n            \\\"score_threshold\\\": self.search_score_threshold,\\n        }\\n\\n        if self.search_filter:\\n            clean_filter = {k: v for k, v in self.search_filter.items() if k and v}\\n            if len(clean_filter) > 0:\\n                args[\\\"filter\\\"] = clean_filter\\n        if self.body_search:\\n            if not self.enable_body_search:\\n                msg = \\\"You should enable body search when creating the table to search the body field.\\\"\\n                raise ValueError(msg)\\n            args[\\\"body_search\\\"] = self.body_search\\n        return args\\n\\n    def get_retriever_kwargs(self):\\n        search_args = self._build_search_args()\\n        return {\\n            \\\"search_type\\\": self._map_search_type(),\\n            \\\"search_kwargs\\\": search_args,\\n        }\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/datastax/src/lfx_datastax/components/cassandra/cassandra_chat.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"7e73363d0b22e34ad274246246b589b01a3d7ae7a127614f16129aaf03173acb\",\"content\":\"\\\"\\\"\\\"Cassandra chat-memory component.\\\"\\\"\\\"\\n\\nfrom lfx.base.memory.model import LCChatMemoryComponent\\nfrom lfx.field_typing.constants import Memory\\nfrom lfx.inputs.inputs import DictInput, MessageTextInput, SecretStrInput\\n\\n\\nclass CassandraChatMemory(LCChatMemoryComponent):\\n    display_name = \\\"Cassandra Chat Memory\\\"\\n    description = \\\"Retrieves and store chat messages from Apache Cassandra.\\\"\\n    name = \\\"CassandraChatMemory\\\"\\n    icon = \\\"Cassandra\\\"\\n\\n    inputs = [\\n        MessageTextInput(\\n            name=\\\"database_ref\\\",\\n            display_name=\\\"Contact Points / Astra Database ID\\\",\\n            info=\\\"Contact points for the database (or Astra DB database ID)\\\",\\n            required=True,\\n        ),\\n        MessageTextInput(\\n            name=\\\"username\\\", display_name=\\\"Username\\\", info=\\\"Username for the database (leave empty for Astra DB).\\\"\\n        ),\\n        SecretStrInput(\\n            name=\\\"token\\\",\\n            display_name=\\\"Password / Astra DB Token\\\",\\n            info=\\\"User password for the database (or Astra DB token).\\\",\\n            required=True,\\n        ),\\n        MessageTextInput(\\n            name=\\\"keyspace\\\",\\n            display_name=\\\"Keyspace\\\",\\n            info=\\\"Table Keyspace (or Astra DB namespace).\\\",\\n            required=True,\\n        ),\\n        MessageTextInput(\\n            name=\\\"table_name\\\",\\n            display_name=\\\"Table Name\\\",\\n            info=\\\"The name of the table (or Astra DB collection) where vectors will be stored.\\\",\\n            required=True,\\n        ),\\n        MessageTextInput(\\n            name=\\\"session_id\\\", display_name=\\\"Session ID\\\", info=\\\"Session ID for the message.\\\", advanced=True\\n        ),\\n        DictInput(\\n            name=\\\"cluster_kwargs\\\",\\n            display_name=\\\"Cluster arguments\\\",\\n            info=\\\"Optional dictionary of additional keyword arguments for the Cassandra cluster.\\\",\\n            advanced=True,\\n            is_list=True,\\n        ),\\n    ]\\n\\n    def build_message_history(self) -> Memory:\\n        from langchain_community.chat_message_histories import CassandraChatMessageHistory\\n\\n        try:\\n            import cassio\\n        except ImportError as e:\\n            msg = \\\"Could not import cassio integration package. Please install it with `pip install cassio`.\\\"\\n            raise ImportError(msg) from e\\n\\n        from uuid import UUID\\n\\n        database_ref = self.database_ref\\n\\n        try:\\n            UUID(self.database_ref)\\n            is_astra = True\\n        except ValueError:\\n            is_astra = False\\n            if \\\",\\\" in self.database_ref:\\n                # use a copy because we can't change the type of the parameter\\n                database_ref = self.database_ref.split(\\\",\\\")\\n\\n        if is_astra:\\n            cassio.init(\\n                database_id=database_ref,\\n                token=self.token,\\n                cluster_kwargs=self.cluster_kwargs,\\n            )\\n        else:\\n            cassio.init(\\n                contact_points=database_ref,\\n                username=self.username,\\n                password=self.token,\\n                cluster_kwargs=self.cluster_kwargs,\\n            )\\n\\n        return CassandraChatMessageHistory(\\n            session_id=self.session_id,\\n            table_name=self.table_name,\\n            keyspace=self.keyspace,\\n        )\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/datastax/src/lfx_datastax/components/datastax/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"a59b4eeaf8373374184b8a6f69f29749aa634d82b607136859593cac4e8757de\",\"content\":\"\\\"\\\"\\\"Lazy component re-exports for the ``datastax`` bundle.\\n\\nMirrors the pre-extraction layout of ``lfx.components.datastax`` so saved\\nflows that referenced the module-level class\\n(e.g. ``lfx.components.datastax.<Class>``) keep resolving via the\\nmigration table after rewrite to\\n``lfx_datastax.components.datastax.<Class>``.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom typing import TYPE_CHECKING, Any\\n\\nfrom lfx.utils.lazy_import import import_mod\\n\\nif TYPE_CHECKING:\\n    from .astradb_cql import AstraDBCQLToolComponent\\n    from .astradb_chatmemory import AstraDBChatMemory\\n    from .astradb_data_api import AstraDBDataAPIComponent\\n    from .astradb_graph import AstraDBGraphVectorStoreComponent\\n    from .astradb_tool import AstraDBToolComponent\\n    from .astradb_vectorstore import AstraDBVectorStoreComponent\\n    from .astradb_vectorize import AstraVectorizeComponent\\n    from .dotenv import Dotenv\\n    from .graph_rag import GraphRAGComponent\\n    from .hcd import HCDVectorStoreComponent\\n\\n_dynamic_imports = {\\n    \\\"AstraDBCQLToolComponent\\\": \\\"astradb_cql\\\",\\n    \\\"AstraDBChatMemory\\\": \\\"astradb_chatmemory\\\",\\n    \\\"AstraDBDataAPIComponent\\\": \\\"astradb_data_api\\\",\\n    \\\"AstraDBGraphVectorStoreComponent\\\": \\\"astradb_graph\\\",\\n    \\\"AstraDBToolComponent\\\": \\\"astradb_tool\\\",\\n    \\\"AstraDBVectorStoreComponent\\\": \\\"astradb_vectorstore\\\",\\n    \\\"AstraVectorizeComponent\\\": \\\"astradb_vectorize\\\",\\n    \\\"Dotenv\\\": \\\"dotenv\\\",\\n    \\\"GraphRAGComponent\\\": \\\"graph_rag\\\",\\n    \\\"HCDVectorStoreComponent\\\": \\\"hcd\\\",\\n}\\n\\n__all__ = [\\n    \\\"AstraDBCQLToolComponent\\\",\\n    \\\"AstraDBChatMemory\\\",\\n    \\\"AstraDBDataAPIComponent\\\",\\n    \\\"AstraDBGraphVectorStoreComponent\\\",\\n    \\\"AstraDBToolComponent\\\",\\n    \\\"AstraDBVectorStoreComponent\\\",\\n    \\\"AstraVectorizeComponent\\\",\\n    \\\"Dotenv\\\",\\n    \\\"GraphRAGComponent\\\",\\n    \\\"HCDVectorStoreComponent\\\",\\n]\\n\\n\\ndef __getattr__(attr_name: str) -> Any:\\n    if attr_name not in _dynamic_imports:\\n        msg = f\\\"module {__name__!r} has no attribute {attr_name!r}\\\"\\n        raise AttributeError(msg)\\n    try:\\n        result = import_mod(attr_name, _dynamic_imports[attr_name], __spec__.parent)\\n    except (ModuleNotFoundError, ImportError, AttributeError) as e:\\n        msg = f\\\"Could not import {attr_name!r} from {__name__!r}: {e}\\\"\\n        raise AttributeError(msg) from e\\n    globals()[attr_name] = result\\n    return result\\n\\n\\ndef __dir__() -> list[str]:\\n    return list(__all__)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/datastax/src/lfx_datastax/components/datastax/astradb_chatmemory.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"b05decbf5e05986648638df80843d75a9a081fb4fe202821b09580dee385e96f\",\"content\":\"from lfx_datastax.base.astradb_base import AstraDBBaseComponent\\nfrom lfx.base.memory.model import LCChatMemoryComponent\\nfrom lfx.field_typing.constants import Memory\\nfrom lfx.inputs.inputs import MessageTextInput\\n\\n\\nclass AstraDBChatMemory(AstraDBBaseComponent, LCChatMemoryComponent):\\n    display_name = \\\"Astra DB Chat Memory\\\"\\n    description = \\\"Retrieves and stores chat messages from Astra DB.\\\"\\n    name = \\\"AstraDBChatMemory\\\"\\n    icon: str = \\\"AstraDB\\\"\\n\\n    inputs = [\\n        *AstraDBBaseComponent.inputs,\\n        MessageTextInput(\\n            name=\\\"session_id\\\",\\n            display_name=\\\"Session ID\\\",\\n            info=\\\"The session ID of the chat. If empty, the current session ID parameter will be used.\\\",\\n            advanced=True,\\n        ),\\n    ]\\n\\n    def build_message_history(self) -> Memory:\\n        try:\\n            from langchain_astradb.chat_message_histories import (\\n                AstraDBChatMessageHistory,\\n            )\\n        except ImportError as e:\\n            msg = (\\n                \\\"Could not import langchain Astra DB integration package. \\\"\\n                \\\"Please install it with `uv pip install langchain-astradb`.\\\"\\n            )\\n            raise ImportError(msg) from e\\n\\n        return AstraDBChatMessageHistory(\\n            session_id=self.session_id,\\n            collection_name=self.collection_name,\\n            token=self.token,\\n            api_endpoint=self.get_api_endpoint(),\\n            namespace=self.get_keyspace(),\\n            environment=self.environment,\\n        )\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/datastax/src/lfx_datastax/components/datastax/astradb_cql.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"9f9c354cb4897511671cf413572ee0b8d8ba7c57b722a9b3c7d2c18f8457c586\",\"content\":\"import json\\nimport urllib\\nfrom datetime import datetime, timezone\\nfrom http import HTTPStatus\\nfrom typing import Any\\n\\nimport requests\\nfrom langchain_core.tools import StructuredTool, Tool\\nfrom pydantic import BaseModel, Field, create_model\\n\\nfrom lfx_datastax.base.astradb_base import AstraDBBaseComponent\\nfrom lfx.base.langchain_utilities.model import LCToolComponent\\nfrom lfx.io import DictInput, IntInput, StrInput, TableInput\\nfrom lfx.log.logger import logger\\nfrom lfx.schema.data import Data\\nfrom lfx.schema.table import EditMode\\nfrom lfx.utils.ssrf_protection import validate_connector_url_for_ssrf\\n\\n\\nclass AstraDBCQLToolComponent(AstraDBBaseComponent, LCToolComponent):\\n    display_name: str = \\\"Astra DB CQL\\\"\\n    description: str = \\\"Create a tool to get transactional data from DataStax Astra DB CQL Table\\\"\\n    documentation: str = \\\"https://docs.langflow.org/bundles-datastax\\\"\\n    icon: str = \\\"AstraDB\\\"\\n\\n    inputs = [\\n        *AstraDBBaseComponent.inputs,\\n        StrInput(\\n            name=\\\"tool_name\\\",\\n            display_name=\\\"Tool Name\\\",\\n            info=\\\"The name of the tool.\\\",\\n            required=True,\\n        ),\\n        StrInput(\\n            name=\\\"tool_description\\\",\\n            display_name=\\\"Tool Description\\\",\\n            info=\\\"The tool description to be passed to the model.\\\",\\n            required=True,\\n        ),\\n        StrInput(\\n            name=\\\"projection_fields\\\",\\n            display_name=\\\"Projection fields\\\",\\n            info=\\\"Attributes to return separated by comma.\\\",\\n            required=True,\\n            value=\\\"*\\\",\\n            advanced=True,\\n        ),\\n        TableInput(\\n            name=\\\"tools_params\\\",\\n            display_name=\\\"Tools Parameters\\\",\\n            info=\\\"Define the structure for the tool parameters. Describe the parameters \\\"\\n            \\\"in a way the LLM can understand how to use them. Add the parameters \\\"\\n            \\\"respecting the table schema (Partition Keys, Clustering Keys and Indexed Fields).\\\",\\n            required=False,\\n            table_schema=[\\n                {\\n                    \\\"name\\\": \\\"name\\\",\\n                    \\\"display_name\\\": \\\"Name\\\",\\n                    \\\"type\\\": \\\"str\\\",\\n                    \\\"description\\\": \\\"Name of the field/parameter to be used by the model.\\\",\\n                    \\\"default\\\": \\\"field\\\",\\n                    \\\"edit_mode\\\": EditMode.INLINE,\\n                },\\n                {\\n                    \\\"name\\\": \\\"field_name\\\",\\n                    \\\"display_name\\\": \\\"Field Name\\\",\\n                    \\\"type\\\": \\\"str\\\",\\n                    \\\"description\\\": \\\"Specify the column name to be filtered on the table. \\\"\\n                    \\\"Leave empty if the attribute name is the same as the name of the field.\\\",\\n                    \\\"default\\\": \\\"\\\",\\n                    \\\"edit_mode\\\": EditMode.INLINE,\\n                },\\n                {\\n                    \\\"name\\\": \\\"description\\\",\\n                    \\\"display_name\\\": \\\"Description\\\",\\n                    \\\"type\\\": \\\"str\\\",\\n                    \\\"description\\\": \\\"Describe the purpose of the parameter.\\\",\\n                    \\\"default\\\": \\\"description of tool parameter\\\",\\n                    \\\"edit_mode\\\": EditMode.POPOVER,\\n                },\\n                {\\n                    \\\"name\\\": \\\"mandatory\\\",\\n                    \\\"display_name\\\": \\\"Is Mandatory\\\",\\n                    \\\"type\\\": \\\"boolean\\\",\\n                    \\\"edit_mode\\\": EditMode.INLINE,\\n                    \\\"description\\\": (\\\"Indicate if the field is mandatory.\\\"),\\n                    \\\"options\\\": [\\\"True\\\", \\\"False\\\"],\\n                    \\\"default\\\": \\\"False\\\",\\n                },\\n                {\\n                    \\\"name\\\": \\\"is_timestamp\\\",\\n                    \\\"display_name\\\": \\\"Is Timestamp\\\",\\n                    \\\"type\\\": \\\"boolean\\\",\\n                    \\\"edit_mode\\\": EditMode.INLINE,\\n                    \\\"description\\\": (\\\"Indicate if the field is a timestamp.\\\"),\\n                    \\\"options\\\": [\\\"True\\\", \\\"False\\\"],\\n                    \\\"default\\\": \\\"False\\\",\\n                },\\n                {\\n                    \\\"name\\\": \\\"operator\\\",\\n                    \\\"display_name\\\": \\\"Operator\\\",\\n                    \\\"type\\\": \\\"str\\\",\\n                    \\\"description\\\": \\\"Set the operator for the field. \\\"\\n                    \\\"https://docs.datastax.com/en/astra-db-serverless/api-reference/documents.html#operators\\\",\\n                    \\\"default\\\": \\\"$eq\\\",\\n                    \\\"options\\\": [\\n                        \\\"$gt\\\",\\n                        \\\"$gte\\\",\\n                        \\\"$lt\\\",\\n                        \\\"$lte\\\",\\n                        \\\"$eq\\\",\\n                        \\\"$ne\\\",\\n                        \\\"$in\\\",\\n                        \\\"$nin\\\",\\n                        \\\"$exists\\\",\\n                        \\\"$all\\\",\\n                        \\\"$size\\\",\\n                    ],\\n                    \\\"edit_mode\\\": EditMode.INLINE,\\n                },\\n            ],\\n            value=[],\\n        ),\\n        DictInput(\\n            name=\\\"partition_keys\\\",\\n            display_name=\\\"DEPRECATED: Partition Keys\\\",\\n            is_list=True,\\n            info=\\\"Field name and description to the model\\\",\\n            required=False,\\n            advanced=True,\\n        ),\\n        DictInput(\\n            name=\\\"clustering_keys\\\",\\n            display_name=\\\"DEPRECATED: Clustering Keys\\\",\\n            is_list=True,\\n            info=\\\"Field name and description to the model\\\",\\n            required=False,\\n            advanced=True,\\n        ),\\n        DictInput(\\n            name=\\\"static_filters\\\",\\n            display_name=\\\"Static Filters\\\",\\n            is_list=True,\\n            advanced=True,\\n            info=\\\"Field name and value. When filled, it will not be generated by the LLM.\\\",\\n        ),\\n        IntInput(\\n            name=\\\"number_of_results\\\",\\n            display_name=\\\"Number of Results\\\",\\n            info=\\\"Number of results to return.\\\",\\n            advanced=True,\\n            value=5,\\n        ),\\n    ]\\n\\n    def parse_timestamp(self, timestamp_str: str) -> str:\\n        \\\"\\\"\\\"Parse a timestamp string into Astra DB REST API format.\\n\\n        Args:\\n            timestamp_str (str): Input timestamp string\\n\\n        Returns:\\n            str: Formatted timestamp string in YYYY-MM-DDTHH:MI:SS.000Z format\\n\\n        Raises:\\n            ValueError: If the timestamp cannot be parsed\\n        \\\"\\\"\\\"\\n        # Common datetime formats to try\\n        formats = [\\n            \\\"%Y-%m-%d\\\",  # 2024-03-21\\n            \\\"%Y-%m-%dT%H:%M:%S\\\",  # 2024-03-21T15:30:00\\n            \\\"%Y-%m-%dT%H:%M:%S%z\\\",  # 2024-03-21T15:30:00+0000\\n            \\\"%Y-%m-%d %H:%M:%S\\\",  # 2024-03-21 15:30:00\\n            \\\"%d/%m/%Y\\\",  # 21/03/2024\\n            \\\"%Y/%m/%d\\\",  # 2024/03/21\\n        ]\\n\\n        for fmt in formats:\\n            try:\\n                # Parse the date string\\n                date_obj = datetime.strptime(timestamp_str, fmt).astimezone()\\n\\n                # If the parsed date has no timezone info, assume UTC\\n                if date_obj.tzinfo is None:\\n                    date_obj = date_obj.replace(tzinfo=timezone.utc)\\n\\n                # Convert to UTC and format\\n                utc_date = date_obj.astimezone(timezone.utc)\\n                return utc_date.strftime(\\\"%Y-%m-%dT%H:%M:%S.000Z\\\")\\n            except ValueError:\\n                continue\\n\\n        msg = f\\\"Could not parse date: {timestamp_str}\\\"\\n        logger.error(msg)\\n        raise ValueError(msg)\\n\\n    def astra_rest(self, args):\\n        headers = {\\\"Accept\\\": \\\"application/json\\\", \\\"X-Cassandra-Token\\\": f\\\"{self.token}\\\"}\\n        astra_url = f\\\"{self.get_api_endpoint()}/api/rest/v2/keyspaces/{self.get_keyspace()}/{self.collection_name}/\\\"\\n        # api_endpoint is tenant-controlled: block SSRF to internal/cloud-metadata hosts before\\n        # the Cassandra token is sent to it.\\n        validate_connector_url_for_ssrf(astra_url)\\n        where = {}\\n\\n        for param in self.tools_params:\\n            field_name = param[\\\"field_name\\\"] if param[\\\"field_name\\\"] else param[\\\"name\\\"]\\n            field_value = None\\n\\n            if field_name in self.static_filters:\\n                field_value = self.static_filters[field_name]\\n            elif param[\\\"name\\\"] in args:\\n                field_value = args[param[\\\"name\\\"]]\\n\\n            if field_value is None:\\n                continue\\n\\n            if param[\\\"is_timestamp\\\"] == True:  # noqa: E712\\n                try:\\n                    field_value = self.parse_timestamp(field_value)\\n                except ValueError as e:\\n                    msg = f\\\"Error parsing timestamp: {e} - Use the prompt to specify the date in the correct format\\\"\\n                    logger.error(msg)\\n                    raise ValueError(msg) from e\\n\\n            if param[\\\"operator\\\"] == \\\"$exists\\\":\\n                where[field_name] = {\\n                    **where.get(field_name, {}),\\n                    param[\\\"operator\\\"]: True,\\n                }\\n            elif param[\\\"operator\\\"] in [\\\"$in\\\", \\\"$nin\\\", \\\"$all\\\"]:\\n                where[field_name] = {\\n                    **where.get(field_name, {}),\\n                    param[\\\"operator\\\"]: field_value.split(\\\",\\\") if isinstance(field_value, str) else field_value,\\n                }\\n            else:\\n                where[field_name] = {\\n                    **where.get(field_name, {}),\\n                    param[\\\"operator\\\"]: field_value,\\n                }\\n\\n        url = f\\\"{astra_url}?page-size={self.number_of_results}\\\"\\n        url += f\\\"&where={json.dumps(where)}\\\"\\n\\n        if self.projection_fields != \\\"*\\\":\\n            url += f\\\"&fields={urllib.parse.quote(self.projection_fields.replace(' ', ''))}\\\"\\n\\n        res = requests.request(\\\"GET\\\", url=url, headers=headers, timeout=10, allow_redirects=False)\\n\\n        if int(res.status_code) >= HTTPStatus.BAD_REQUEST:\\n            msg = f\\\"Error on Astra DB CQL Tool {self.tool_name} request: {res.text}\\\"\\n            logger.error(msg)\\n            raise ValueError(msg)\\n\\n        try:\\n            res_data = res.json()\\n            return res_data[\\\"data\\\"]\\n        except ValueError:\\n            return res.status_code\\n\\n    def create_args_schema(self) -> dict[str, BaseModel]:\\n        args: dict[str, tuple[Any, Field]] = {}\\n\\n        for param in self.tools_params:\\n            field_name = param[\\\"field_name\\\"] if param[\\\"field_name\\\"] else param[\\\"name\\\"]\\n            if field_name not in self.static_filters:\\n                if param[\\\"mandatory\\\"]:\\n                    args[param[\\\"name\\\"]] = (str, Field(description=param[\\\"description\\\"]))\\n                else:\\n                    args[param[\\\"name\\\"]] = (\\n                        str | None,\\n                        Field(description=param[\\\"description\\\"], default=None),\\n                    )\\n\\n        model = create_model(\\\"ToolInput\\\", **args, __base__=BaseModel)\\n        return {\\\"ToolInput\\\": model}\\n\\n    def build_tool(self) -> Tool:\\n        \\\"\\\"\\\"Builds a Astra DB CQL Table tool.\\n\\n        Args:\\n            name (str, optional): The name of the tool.\\n\\n        Returns:\\n            Tool: The built Astra DB tool.\\n        \\\"\\\"\\\"\\n        schema_dict = self.create_args_schema()\\n        return StructuredTool.from_function(\\n            name=self.tool_name,\\n            args_schema=schema_dict[\\\"ToolInput\\\"],\\n            description=self.tool_description,\\n            func=self.run_model,\\n            return_direct=False,\\n        )\\n\\n    def projection_args(self, input_str: str) -> dict:\\n        elements = input_str.split(\\\",\\\")\\n        result = {}\\n\\n        for element in elements:\\n            if element.startswith(\\\"!\\\"):\\n                result[element[1:]] = False\\n            else:\\n                result[element] = True\\n\\n        return result\\n\\n    def run_model(self, **args) -> Data | list[Data]:\\n        results = self.astra_rest(args)\\n        data: list[Data] = []\\n\\n        if isinstance(results, list):\\n            data = [Data(data=doc) for doc in results]\\n        else:\\n            self.status = results\\n            return []\\n\\n        self.status = data\\n        return data\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/datastax/src/lfx_datastax/components/datastax/astradb_data_api.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"73a74b295b10ff0f0e1a52e2752f72d3fb34b838fecb002a111e32afd1cbb75a\",\"content\":\"\\\"\\\"\\\"Astra DB Data API component.\\n\\nA thin, modern Langflow component that exposes the full document-based\\nData API surface of DataStax Astra DB using **only** the ``astrapy`` SDK.\\n\\nThe component inherits :class:`lfx_datastax.base.astradb_base.AstraDBBaseComponent`\\nto reuse the polished database / collection / keyspace selector UI (including\\nthe in-app \\\"Create new database\\\" and \\\"Create new collection\\\" dialogs).\\nUnlike :class:`AstraDBVectorStoreComponent`, no ``langchain-astradb`` code path\\nis used at runtime --- every operation goes through ``astrapy`` directly.\\n\\nSupported operations (selectable via the operation tab):\\n\\n* Find             --- ``collection.find``\\n* Find One         --- ``collection.find_one``\\n* Insert One       --- ``collection.insert_one``\\n* Insert Many      --- ``collection.insert_many``\\n* Update One       --- ``collection.update_one``\\n* Update Many      --- ``collection.update_many``\\n* Delete One       --- ``collection.delete_one``\\n* Delete Many      --- ``collection.delete_many``\\n* Count Documents  --- ``collection.count_documents``\\n* Estimated Count  --- ``collection.estimated_document_count``\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom typing import Any\\n\\nfrom astrapy import Collection, DataAPIClient, Database\\nfrom astrapy.info import (\\n    CollectionDefinition,\\n    CollectionVectorOptions,\\n    VectorServiceOptions,\\n)\\n\\nfrom lfx_datastax.base.astradb_base import AstraDBBaseComponent, validate_api_endpoint\\nfrom lfx.io import (\\n    BoolInput,\\n    DropdownInput,\\n    IntInput,\\n    NestedDictInput,\\n    Output,\\n)\\nfrom lfx.log.logger import logger\\nfrom lfx.schema.data import Data\\nfrom lfx.schema.dataframe import DataFrame\\n\\n# Operation option constants -- kept as module-level constants so the UI\\n# tab values and the dispatcher stay in sync with a single source of truth.\\nOP_FIND = \\\"Find\\\"\\nOP_FIND_ONE = \\\"Find One\\\"\\nOP_INSERT_ONE = \\\"Insert One\\\"\\nOP_INSERT_MANY = \\\"Insert Many\\\"\\nOP_UPDATE_ONE = \\\"Update One\\\"\\nOP_UPDATE_MANY = \\\"Update Many\\\"\\nOP_DELETE_ONE = \\\"Delete One\\\"\\nOP_DELETE_MANY = \\\"Delete Many\\\"\\nOP_COUNT = \\\"Count Documents\\\"\\nOP_ESTIMATED_COUNT = \\\"Estimated Count\\\"\\n\\nALL_OPERATIONS: tuple[str, ...] = (\\n    OP_FIND,\\n    OP_FIND_ONE,\\n    OP_INSERT_ONE,\\n    OP_INSERT_MANY,\\n    OP_UPDATE_ONE,\\n    OP_UPDATE_MANY,\\n    OP_DELETE_ONE,\\n    OP_DELETE_MANY,\\n    OP_COUNT,\\n    OP_ESTIMATED_COUNT,\\n)\\n\\n# Per-operation icons surfaced in the operation dropdown. Icon names mirror\\n# those used elsewhere in Langflow for a consistent look.\\nOPERATION_ICONS: dict[str, str] = {\\n    OP_FIND: \\\"Search\\\",\\n    OP_FIND_ONE: \\\"SearchCheck\\\",\\n    OP_INSERT_ONE: \\\"Plus\\\",\\n    OP_INSERT_MANY: \\\"CopyPlus\\\",\\n    OP_UPDATE_ONE: \\\"Pencil\\\",\\n    OP_UPDATE_MANY: \\\"PencilLine\\\",\\n    OP_DELETE_ONE: \\\"Trash\\\",\\n    OP_DELETE_MANY: \\\"Trash2\\\",\\n    OP_COUNT: \\\"Hash\\\",\\n    OP_ESTIMATED_COUNT: \\\"Sigma\\\",\\n}\\n\\n# Groups of inputs that each operation needs. Centralising this makes the\\n# dynamic show/hide logic trivial to audit and extend.\\nOPERATION_FIELDS: dict[str, set[str]] = {\\n    OP_FIND: {\\n        \\\"filter_query\\\",\\n        \\\"projection\\\",\\n        \\\"sort\\\",\\n        \\\"limit\\\",\\n        \\\"skip\\\",\\n        \\\"include_similarity\\\",\\n    },\\n    OP_FIND_ONE: {\\\"filter_query\\\", \\\"projection\\\", \\\"sort\\\", \\\"include_similarity\\\"},\\n    OP_INSERT_ONE: {\\\"document\\\"},\\n    OP_INSERT_MANY: {\\\"documents\\\", \\\"ordered\\\"},\\n    OP_UPDATE_ONE: {\\\"filter_query\\\", \\\"update\\\", \\\"upsert\\\"},\\n    OP_UPDATE_MANY: {\\\"filter_query\\\", \\\"update\\\", \\\"upsert\\\"},\\n    OP_DELETE_ONE: {\\\"filter_query\\\"},\\n    OP_DELETE_MANY: {\\\"filter_query\\\"},\\n    OP_COUNT: {\\\"filter_query\\\", \\\"upper_bound\\\"},\\n    OP_ESTIMATED_COUNT: set(),\\n}\\n\\n# Default count upper bound (``count_documents`` in astrapy requires one).\\nDEFAULT_COUNT_UPPER_BOUND = 1000\\n# Default find limit -- guard against unbounded scans in the UI path.\\nDEFAULT_FIND_LIMIT = 100\\n\\n# Fields specific to the operation that we toggle ``show`` on.\\n_OPERATION_TOGGLE_FIELDS: tuple[str, ...] = (\\n    \\\"filter_query\\\",\\n    \\\"projection\\\",\\n    \\\"sort\\\",\\n    \\\"limit\\\",\\n    \\\"skip\\\",\\n    \\\"include_similarity\\\",\\n    \\\"document\\\",\\n    \\\"documents\\\",\\n    \\\"update\\\",\\n    \\\"upsert\\\",\\n    \\\"ordered\\\",\\n    \\\"upper_bound\\\",\\n)\\n\\n\\nclass AstraDBDataAPIComponent(AstraDBBaseComponent):\\n    \\\"\\\"\\\"Direct ``astrapy`` Data API access for Astra DB collections.\\n\\n    Inherits the standard Astra DB selector UI (database / keyspace /\\n    collection, plus the create-new dialogs) from\\n    :class:`AstraDBBaseComponent` and adds a single operation tab that\\n    drives a minimal, operation-specific set of inputs.\\n    \\\"\\\"\\\"\\n\\n    display_name: str = \\\"Astra DB Data API\\\"\\n    description: str = (\\n        \\\"Run Data API operations (find, filter, insert, update, delete, \\\"\\n        \\\"count) against an Astra DB collection using astrapy directly.\\\"\\n    )\\n    documentation: str = \\\"https://docs.datastax.com/en/astra-db-serverless/api-reference/overview.html\\\"\\n    icon: str = \\\"AstraDB\\\"\\n    name: str = \\\"AstraDBDataAPI\\\"\\n    beta: bool = True\\n\\n    inputs = [\\n        *AstraDBBaseComponent.inputs,\\n        DropdownInput(\\n            name=\\\"operation\\\",\\n            display_name=\\\"Operation\\\",\\n            info=\\\"Data API operation to run against the selected collection.\\\",\\n            options=list(ALL_OPERATIONS),\\n            options_metadata=[{\\\"icon\\\": OPERATION_ICONS[op]} for op in ALL_OPERATIONS],\\n            value=OP_FIND,\\n            real_time_refresh=True,\\n            combobox=False,\\n            tool_mode=True,\\n        ),\\n        # -- Query / projection / sort ---------------------------------\\n        NestedDictInput(\\n            name=\\\"filter_query\\\",\\n            display_name=\\\"Filter\\\",\\n            info=(\\n                \\\"MongoDB-style filter, e.g. \\\"\\n                '{\\\"status\\\": \\\"active\\\", \\\"age\\\": {\\\"$gte\\\": 18}}. '\\n                \\\"Leave empty to match all documents (not recommended for \\\"\\n                \\\"delete/update operations).\\\"\\n            ),\\n            advanced=False,\\n            tool_mode=True,\\n        ),\\n        NestedDictInput(\\n            name=\\\"projection\\\",\\n            display_name=\\\"Projection\\\",\\n            info=('Fields to include (``1``/``true``) or exclude (``0``/``false``), e.g. {\\\"name\\\": 1, \\\"email\\\": 1}.'),\\n            advanced=True,\\n        ),\\n        NestedDictInput(\\n            name=\\\"sort\\\",\\n            display_name=\\\"Sort\\\",\\n            info=(\\n                \\\"Sort specification -- ``1`` ascending, ``-1`` descending. \\\"\\n                \\\"Use ``$vector`` or ``$vectorize`` for vector search, e.g. \\\"\\n                '{\\\"$vectorize\\\": \\\"search query\\\"}.'\\n            ),\\n            advanced=True,\\n        ),\\n        IntInput(\\n            name=\\\"limit\\\",\\n            display_name=\\\"Limit\\\",\\n            info=\\\"Maximum number of documents to return.\\\",\\n            value=DEFAULT_FIND_LIMIT,\\n            advanced=False,\\n            tool_mode=True,\\n        ),\\n        IntInput(\\n            name=\\\"skip\\\",\\n            display_name=\\\"Skip\\\",\\n            info=\\\"Number of documents to skip.\\\",\\n            value=0,\\n            advanced=True,\\n        ),\\n        BoolInput(\\n            name=\\\"include_similarity\\\",\\n            display_name=\\\"Include Similarity\\\",\\n            info=\\\"Include the ``$similarity`` score on each returned document (vector searches only).\\\",\\n            value=False,\\n            advanced=True,\\n        ),\\n        # -- Writes -----------------------------------------------------\\n        NestedDictInput(\\n            name=\\\"document\\\",\\n            display_name=\\\"Document\\\",\\n            info='Single document to insert, e.g. {\\\"name\\\": \\\"Ada\\\", \\\"age\\\": 36}.',\\n            show=False,\\n            tool_mode=True,\\n        ),\\n        NestedDictInput(\\n            name=\\\"documents\\\",\\n            display_name=\\\"Documents\\\",\\n            info=\\\"List of documents to insert. Provide a JSON list, e.g. [{...}, {...}].\\\",\\n            show=False,\\n            tool_mode=True,\\n        ),\\n        BoolInput(\\n            name=\\\"ordered\\\",\\n            display_name=\\\"Ordered Insert\\\",\\n            info=\\\"If enabled, inserts stop at the first error; otherwise errors are collected.\\\",\\n            value=False,\\n            show=False,\\n            advanced=True,\\n        ),\\n        NestedDictInput(\\n            name=\\\"update\\\",\\n            display_name=\\\"Update\\\",\\n            info=(\\n                'Update operator document, e.g. {\\\"$set\\\": {\\\"status\\\": \\\"archived\\\"}}. '\\n                \\\"Must use update operators (``$set``, ``$inc``, ``$push`` ...).\\\"\\n            ),\\n            show=False,\\n            tool_mode=True,\\n        ),\\n        BoolInput(\\n            name=\\\"upsert\\\",\\n            display_name=\\\"Upsert\\\",\\n            info=\\\"Insert a new document if no match is found.\\\",\\n            value=False,\\n            show=False,\\n            advanced=True,\\n        ),\\n        # -- Count ------------------------------------------------------\\n        IntInput(\\n            name=\\\"upper_bound\\\",\\n            display_name=\\\"Count Upper Bound\\\",\\n            info=\\\"Maximum count astrapy will scan to for ``Count Documents``.\\\",\\n            value=DEFAULT_COUNT_UPPER_BOUND,\\n            show=False,\\n            advanced=True,\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(display_name=\\\"Data\\\", name=\\\"data\\\", method=\\\"run_operation\\\"),\\n        Output(display_name=\\\"Table\\\", name=\\\"dataframe\\\", method=\\\"as_dataframe\\\"),\\n        Output(display_name=\\\"Raw Result\\\", name=\\\"raw\\\", method=\\\"raw_result\\\"),\\n    ]\\n\\n    # ----------------------------------------------------------------------\\n    # Override collection creation to use astrapy *directly*.\\n    # ----------------------------------------------------------------------\\n\\n    @classmethod\\n    async def create_collection_api(  # type: ignore[override]\\n        cls,\\n        new_collection_name: str,\\n        token: str,\\n        api_endpoint: str,\\n        environment: str | None = None,\\n        keyspace: str | None = None,\\n        dimension: int | None = None,\\n        embedding_generation_provider: str | None = None,\\n        embedding_generation_model: str | None = None,\\n    ) -> Collection:\\n        \\\"\\\"\\\"Create a new Astra DB collection using astrapy only.\\n\\n        The base class implementation in :class:`AstraDBBaseComponent` uses\\n        ``_AstraDBCollectionEnvironment`` from ``langchain-astradb``. This\\n        override instead calls ``astrapy``'s :meth:`Database.create_collection`\\n        directly, building a :class:`CollectionDefinition` when\\n        server-side vectorize options are requested.\\n\\n        Args:\\n            new_collection_name: Required collection name.\\n            token: Astra DB application token.\\n            api_endpoint: Full Astra DB API endpoint for the target database.\\n            environment: Astra environment (``prod`` / ``test`` / ``dev``).\\n            keyspace: Keyspace to create the collection in.\\n            dimension: Embedding dimension if using \\\"Bring your own\\\" embeddings.\\n            embedding_generation_provider: Display name of a configured\\n                vectorize provider, or ``\\\"Bring your own\\\"``.\\n            embedding_generation_model: Model name for the selected provider.\\n\\n        Returns:\\n            The newly created :class:`astrapy.Collection`.\\n\\n        Raises:\\n            ValueError: If ``new_collection_name`` is empty or if an\\n                unsupported provider configuration is supplied.\\n        \\\"\\\"\\\"\\n        if not new_collection_name:\\n            msg = \\\"Collection name is required to create a new collection.\\\"\\n            raise ValueError(msg)\\n\\n        # Fed a build_config value; validate before the endpoint is dialed with the token.\\n        validate_api_endpoint(api_endpoint)\\n\\n        env = cls.get_environment(environment)\\n        client = DataAPIClient(environment=env)\\n        database = client.get_database(api_endpoint, token=token, keyspace=keyspace)\\n\\n        # Build the vector options -- either bring-your-own (dimension only)\\n        # or a server-side vectorize provider.\\n        vector_options: CollectionVectorOptions | None = None\\n        if dimension:\\n            vector_options = CollectionVectorOptions(dimension=dimension)\\n        elif embedding_generation_provider and embedding_generation_provider != \\\"Bring your own\\\":\\n            providers = cls.get_vectorize_providers(token=token, environment=env, api_endpoint=api_endpoint)\\n            provider_key = providers.get(embedding_generation_provider, [None, []])[0]\\n            if provider_key is None:\\n                msg = (\\n                    f\\\"Unknown embedding provider '{embedding_generation_provider}'. \\\"\\n                    \\\"Pass a dimension for a bring-your-own collection, or choose a \\\"\\n                    \\\"configured vectorize provider.\\\"\\n                )\\n                raise ValueError(msg)\\n            vector_options = CollectionVectorOptions(\\n                service=VectorServiceOptions(\\n                    provider=provider_key,\\n                    model_name=embedding_generation_model,\\n                ),\\n            )\\n\\n        definition = CollectionDefinition(vector=vector_options) if vector_options else None\\n        return database.create_collection(\\n            new_collection_name,\\n            definition=definition,\\n            keyspace=keyspace,\\n        )\\n\\n    # ----------------------------------------------------------------------\\n    # Dynamic UI -- show/hide operation-specific fields.\\n    # ----------------------------------------------------------------------\\n\\n    async def update_build_config(\\n        self,\\n        build_config: dict,\\n        field_value: str | dict,\\n        field_name: str | None = None,\\n    ) -> dict:\\n        \\\"\\\"\\\"Keep the base Astra DB selector behavior and toggle operation fields.\\\"\\\"\\\"\\n        build_config = await super().update_build_config(build_config, field_value, field_name)\\n\\n        # On operation change (or first render), toggle visibility of\\n        # operation-specific inputs.\\n        if field_name == \\\"operation\\\" or field_name is None:\\n            op_value = field_value if field_name == \\\"operation\\\" else build_config.get(\\\"operation\\\", {}).get(\\\"value\\\")\\n            self._apply_operation_visibility(build_config, op_value or OP_FIND)\\n\\n        return build_config\\n\\n    @classmethod\\n    def _apply_operation_visibility(cls, build_config: dict, operation: str) -> None:\\n        \\\"\\\"\\\"Show/hide operation-specific fields based on the selected operation.\\\"\\\"\\\"\\n        active = OPERATION_FIELDS.get(operation, set())\\n        for field in _OPERATION_TOGGLE_FIELDS:\\n            if field in build_config:\\n                build_config[field][\\\"show\\\"] = field in active\\n\\n    # ----------------------------------------------------------------------\\n    # Collection accessor\\n    # ----------------------------------------------------------------------\\n\\n    def _get_collection(self) -> Collection:\\n        \\\"\\\"\\\"Return the resolved astrapy :class:`Collection` for this component.\\\"\\\"\\\"\\n        if not self.collection_name:\\n            msg = \\\"No collection selected. Choose or create a collection first.\\\"\\n            raise ValueError(msg)\\n\\n        database: Database = self.get_database_object(api_endpoint=self.get_api_endpoint())\\n        return database.get_collection(self.collection_name, keyspace=self.get_keyspace())\\n\\n    # ----------------------------------------------------------------------\\n    # Operation dispatch\\n    # ----------------------------------------------------------------------\\n\\n    def run_operation(self) -> list[Data]:\\n        \\\"\\\"\\\"Execute the selected operation and return results as ``list[Data]``.\\n\\n        For write / count operations where a ``list[Data]`` isn't semantically\\n        meaningful, a single-element list wrapping a summary :class:`Data`\\n        object is returned so the output socket stays consistent.\\n        \\\"\\\"\\\"\\n        result = self._dispatch()\\n        self.status = result\\n        return result\\n\\n    def raw_result(self) -> Data:\\n        \\\"\\\"\\\"Return the raw operation result as a single :class:`Data` object.\\n\\n        Useful for inspecting the full ``astrapy`` response envelope\\n        (``inserted_ids``, ``matched_count``, ``modified_count`` ...).\\n        \\\"\\\"\\\"\\n        raw = self._dispatch(raw=True)\\n        data = Data(data=raw if isinstance(raw, dict) else {\\\"result\\\": raw})\\n        self.status = data\\n        return data\\n\\n    def as_dataframe(self) -> DataFrame:\\n        \\\"\\\"\\\"Return results as a :class:`DataFrame` for easy tabular display.\\\"\\\"\\\"\\n        rows = self.run_operation()\\n        return DataFrame([row.data for row in rows if isinstance(row, Data)])\\n\\n    # ----------------------------------------------------------------------\\n    # Internal dispatcher\\n    # ----------------------------------------------------------------------\\n\\n    def _dispatch(self, *, raw: bool = False) -> Any:\\n        operation = getattr(self, \\\"operation\\\", OP_FIND) or OP_FIND\\n        collection = self._get_collection()\\n\\n        handlers = {\\n            OP_FIND: self._op_find,\\n            OP_FIND_ONE: self._op_find_one,\\n            OP_INSERT_ONE: self._op_insert_one,\\n            OP_INSERT_MANY: self._op_insert_many,\\n            OP_UPDATE_ONE: self._op_update_one,\\n            OP_UPDATE_MANY: self._op_update_many,\\n            OP_DELETE_ONE: self._op_delete_one,\\n            OP_DELETE_MANY: self._op_delete_many,\\n            OP_COUNT: self._op_count,\\n            OP_ESTIMATED_COUNT: self._op_estimated_count,\\n        }\\n\\n        handler = handlers.get(operation)\\n        if handler is None:\\n            msg = f\\\"Unsupported operation '{operation}'.\\\"\\n            raise ValueError(msg)\\n\\n        try:\\n            return handler(collection, raw=raw)\\n        except Exception as exc:\\n            logger.exception(\\\"Astra DB Data API operation failed: %s\\\", operation)\\n            msg = f\\\"Astra DB Data API '{operation}' failed: {exc}\\\"\\n            raise ValueError(msg) from exc\\n\\n    # -- Handlers -----------------------------------------------------\\n\\n    def _op_find(self, collection: Collection, *, raw: bool) -> Any:\\n        find_kwargs = self._build_find_kwargs()\\n        cursor = collection.find(**find_kwargs)\\n        docs = list(cursor)\\n        if raw:\\n            return {\\\"count\\\": len(docs), \\\"documents\\\": docs}\\n        return [Data(data=doc) for doc in docs]\\n\\n    def _op_find_one(self, collection: Collection, *, raw: bool) -> Any:\\n        kwargs = self._build_find_kwargs(one=True)\\n        doc = collection.find_one(**kwargs)\\n        if raw:\\n            return {\\\"document\\\": doc}\\n        return [Data(data=doc)] if doc else []\\n\\n    def _op_insert_one(self, collection: Collection, *, raw: bool) -> Any:\\n        document = self._require_mapping(\\\"document\\\", self.document, allow_empty=False)\\n        result = collection.insert_one(document)\\n        payload = {\\\"inserted_id\\\": _stringify(result.inserted_id)}\\n        if raw:\\n            return payload\\n        return [Data(data=payload)]\\n\\n    def _op_insert_many(self, collection: Collection, *, raw: bool) -> Any:\\n        documents = _coerce_documents(self.documents)\\n        if not documents:\\n            msg = \\\"Insert Many requires a non-empty list of documents.\\\"\\n            raise ValueError(msg)\\n        result = collection.insert_many(documents, ordered=bool(self.ordered))\\n        payload = {\\n            \\\"inserted_ids\\\": [_stringify(_id) for _id in result.inserted_ids],\\n            \\\"inserted_count\\\": len(result.inserted_ids),\\n        }\\n        if raw:\\n            return payload\\n        return [Data(data=payload)]\\n\\n    def _op_update_one(self, collection: Collection, *, raw: bool) -> Any:\\n        filter_q = self._require_mapping(\\\"filter_query\\\", self.filter_query, allow_empty=False)\\n        update_doc = self._require_mapping(\\\"update\\\", self.update, allow_empty=False)\\n        result = collection.update_one(filter_q, update_doc, upsert=bool(self.upsert))\\n        return self._format_update_result(result, raw=raw)\\n\\n    def _op_update_many(self, collection: Collection, *, raw: bool) -> Any:\\n        filter_q = self._require_mapping(\\\"filter_query\\\", self.filter_query, allow_empty=False)\\n        update_doc = self._require_mapping(\\\"update\\\", self.update, allow_empty=False)\\n        result = collection.update_many(filter_q, update_doc, upsert=bool(self.upsert))\\n        return self._format_update_result(result, raw=raw)\\n\\n    def _op_delete_one(self, collection: Collection, *, raw: bool) -> Any:\\n        filter_q = self._require_mapping(\\\"filter_query\\\", self.filter_query, allow_empty=False)\\n        result = collection.delete_one(filter_q)\\n        payload = {\\\"deleted_count\\\": result.deleted_count}\\n        if raw:\\n            return payload\\n        return [Data(data=payload)]\\n\\n    def _op_delete_many(self, collection: Collection, *, raw: bool) -> Any:\\n        filter_q = self._require_mapping(\\\"filter_query\\\", self.filter_query, allow_empty=False)\\n        result = collection.delete_many(filter_q)\\n        payload = {\\\"deleted_count\\\": result.deleted_count}\\n        if raw:\\n            return payload\\n        return [Data(data=payload)]\\n\\n    def _op_count(self, collection: Collection, *, raw: bool) -> Any:\\n        filter_q = self.filter_query or {}\\n        upper_bound = int(self.upper_bound or DEFAULT_COUNT_UPPER_BOUND)\\n        count = collection.count_documents(filter_q, upper_bound=upper_bound)\\n        payload = {\\\"count\\\": count, \\\"upper_bound\\\": upper_bound}\\n        if raw:\\n            return payload\\n        return [Data(data=payload)]\\n\\n    def _op_estimated_count(self, collection: Collection, *, raw: bool) -> Any:\\n        count = collection.estimated_document_count()\\n        payload = {\\\"estimated_count\\\": count}\\n        if raw:\\n            return payload\\n        return [Data(data=payload)]\\n\\n    # -- Helpers ------------------------------------------------------\\n\\n    def _build_find_kwargs(self, *, one: bool = False) -> dict[str, Any]:\\n        \\\"\\\"\\\"Build kwargs for ``find`` / ``find_one``, omitting empty values.\\\"\\\"\\\"\\n        kwargs: dict[str, Any] = {\\\"filter\\\": self.filter_query or {}}\\n\\n        if self.projection:\\n            kwargs[\\\"projection\\\"] = self.projection\\n        if self.sort:\\n            kwargs[\\\"sort\\\"] = self.sort\\n        if self.include_similarity:\\n            kwargs[\\\"include_similarity\\\"] = True\\n\\n        if not one:\\n            limit = int(self.limit) if self.limit else 0\\n            if limit > 0:\\n                kwargs[\\\"limit\\\"] = limit\\n            skip = int(self.skip) if self.skip else 0\\n            if skip > 0:\\n                kwargs[\\\"skip\\\"] = skip\\n        return kwargs\\n\\n    @staticmethod\\n    def _format_update_result(result: Any, *, raw: bool) -> Any:\\n        payload = {\\n            \\\"matched_count\\\": getattr(result, \\\"matched_count\\\", None),\\n            \\\"modified_count\\\": getattr(result, \\\"modified_count\\\", None),\\n            \\\"upserted_id\\\": _stringify(getattr(result, \\\"upserted_id\\\", None)),\\n        }\\n        if raw:\\n            return payload\\n        return [Data(data=payload)]\\n\\n    @staticmethod\\n    def _require_mapping(field_name: str, value: Any, *, allow_empty: bool = True) -> dict:\\n        \\\"\\\"\\\"Validate that a field contains a mapping; raise a clear error otherwise.\\\"\\\"\\\"\\n        if value is None or value == \\\"\\\":\\n            if allow_empty:\\n                return {}\\n            msg = f\\\"Field '{field_name}' is required for this operation.\\\"\\n            raise ValueError(msg)\\n        if not isinstance(value, dict):\\n            msg = f\\\"Field '{field_name}' must be a JSON object, got {type(value).__name__}.\\\"\\n            raise ValueError(msg)  # noqa: TRY004\\n        if not value and not allow_empty:\\n            msg = f\\\"Field '{field_name}' must not be empty for this operation.\\\"\\n            raise ValueError(msg)\\n        return value\\n\\n\\n# ----------------------------------------------------------------------\\n# Module-level helpers (kept outside the class for easy unit-testing)\\n# ----------------------------------------------------------------------\\n\\n\\ndef _stringify(value: Any) -> Any:\\n    \\\"\\\"\\\"Best-effort stringification of Data API id types for JSON-serialisable output.\\\"\\\"\\\"\\n    if value is None:\\n        return None\\n    if isinstance(value, str | int | float | bool):\\n        return value\\n    return str(value)\\n\\n\\ndef _coerce_documents(value: Any) -> list[dict[str, Any]]:\\n    \\\"\\\"\\\"Accept either a ``list[dict]`` or a single ``dict`` and normalise to a list.\\\"\\\"\\\"\\n    if value is None or value == \\\"\\\":\\n        return []\\n    if isinstance(value, dict):\\n        # Singleton -- wrap into a list for convenience.\\n        return [value]\\n    if isinstance(value, list):\\n        bad = [i for i, item in enumerate(value) if not isinstance(item, dict)]\\n        if bad:\\n            msg = f\\\"Documents list contains non-dict entries at index {bad[0]}.\\\"\\n            raise ValueError(msg)\\n        return value\\n    msg = f\\\"Documents must be a list of JSON objects, got {type(value).__name__}.\\\"\\n    raise ValueError(msg)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/datastax/src/lfx_datastax/components/datastax/astradb_tool.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"11ce79761ce90350d810a61dd7a18a4c34f540572486813885f90f34812908b0\",\"content\":\"from datetime import datetime, timezone\\nfrom typing import Any\\n\\nfrom astrapy import Collection, DataAPIClient, Database\\nfrom langchain_core.tools import StructuredTool, Tool\\nfrom pydantic import BaseModel, Field, create_model\\n\\nfrom lfx_datastax.base.astradb_base import AstraDBBaseComponent\\nfrom lfx.base.langchain_utilities.model import LCToolComponent\\nfrom lfx.io import BoolInput, DictInput, IntInput, StrInput, TableInput\\nfrom lfx.log.logger import logger\\nfrom lfx.schema.data import Data\\nfrom lfx.schema.table import EditMode\\n\\n\\nclass AstraDBToolComponent(AstraDBBaseComponent, LCToolComponent):\\n    display_name: str = \\\"Astra DB Tool\\\"\\n    description: str = \\\"Tool to run hybrid vector and metadata search on DataStax Astra DB Collection\\\"\\n    documentation: str = \\\"https://docs.langflow.org/bundles-datastax\\\"\\n    icon: str = \\\"AstraDB\\\"\\n    legacy: bool = True\\n    name = \\\"AstraDBTool\\\"\\n    replacement = [\\\"datastax.AstraDB\\\"]\\n\\n    inputs = [\\n        *AstraDBBaseComponent.inputs,\\n        StrInput(\\n            name=\\\"tool_name\\\",\\n            display_name=\\\"Tool Name\\\",\\n            info=\\\"The name of the tool to be passed to the LLM.\\\",\\n            required=True,\\n        ),\\n        StrInput(\\n            name=\\\"tool_description\\\",\\n            display_name=\\\"Tool Description\\\",\\n            info=\\\"Describe the tool to LLM. Add any information that can help the LLM to use the tool.\\\",\\n            required=True,\\n        ),\\n        StrInput(\\n            name=\\\"projection_attributes\\\",\\n            display_name=\\\"Projection Attributes\\\",\\n            info=\\\"Attributes to be returned by the tool separated by comma.\\\",\\n            required=True,\\n            value=\\\"*\\\",\\n            advanced=True,\\n        ),\\n        TableInput(\\n            name=\\\"tools_params_v2\\\",\\n            display_name=\\\"Tools Parameters\\\",\\n            info=\\\"Define the structure for the tool parameters. Describe the parameters \\\"\\n            \\\"in a way the LLM can understand how to use them.\\\",\\n            required=False,\\n            table_schema=[\\n                {\\n                    \\\"name\\\": \\\"name\\\",\\n                    \\\"display_name\\\": \\\"Name\\\",\\n                    \\\"type\\\": \\\"str\\\",\\n                    \\\"description\\\": \\\"Specify the name of the output field/parameter for the model.\\\",\\n                    \\\"default\\\": \\\"field\\\",\\n                    \\\"edit_mode\\\": EditMode.INLINE,\\n                },\\n                {\\n                    \\\"name\\\": \\\"attribute_name\\\",\\n                    \\\"display_name\\\": \\\"Attribute Name\\\",\\n                    \\\"type\\\": \\\"str\\\",\\n                    \\\"description\\\": \\\"Specify the attribute name to be filtered on the collection. \\\"\\n                    \\\"Leave empty if the attribute name is the same as the name of the field.\\\",\\n                    \\\"default\\\": \\\"\\\",\\n                    \\\"edit_mode\\\": EditMode.INLINE,\\n                },\\n                {\\n                    \\\"name\\\": \\\"description\\\",\\n                    \\\"display_name\\\": \\\"Description\\\",\\n                    \\\"type\\\": \\\"str\\\",\\n                    \\\"description\\\": \\\"Describe the purpose of the output field.\\\",\\n                    \\\"default\\\": \\\"description of field\\\",\\n                    \\\"edit_mode\\\": EditMode.POPOVER,\\n                },\\n                {\\n                    \\\"name\\\": \\\"metadata\\\",\\n                    \\\"display_name\\\": \\\"Is Metadata\\\",\\n                    \\\"type\\\": \\\"boolean\\\",\\n                    \\\"edit_mode\\\": EditMode.INLINE,\\n                    \\\"description\\\": (\\\"Indicate if the field is included in the metadata field.\\\"),\\n                    \\\"options\\\": [\\\"True\\\", \\\"False\\\"],\\n                    \\\"default\\\": \\\"False\\\",\\n                },\\n                {\\n                    \\\"name\\\": \\\"mandatory\\\",\\n                    \\\"display_name\\\": \\\"Is Mandatory\\\",\\n                    \\\"type\\\": \\\"boolean\\\",\\n                    \\\"edit_mode\\\": EditMode.INLINE,\\n                    \\\"description\\\": (\\\"Indicate if the field is mandatory.\\\"),\\n                    \\\"options\\\": [\\\"True\\\", \\\"False\\\"],\\n                    \\\"default\\\": \\\"False\\\",\\n                },\\n                {\\n                    \\\"name\\\": \\\"is_timestamp\\\",\\n                    \\\"display_name\\\": \\\"Is Timestamp\\\",\\n                    \\\"type\\\": \\\"boolean\\\",\\n                    \\\"edit_mode\\\": EditMode.INLINE,\\n                    \\\"description\\\": (\\\"Indicate if the field is a timestamp.\\\"),\\n                    \\\"options\\\": [\\\"True\\\", \\\"False\\\"],\\n                    \\\"default\\\": \\\"False\\\",\\n                },\\n                {\\n                    \\\"name\\\": \\\"operator\\\",\\n                    \\\"display_name\\\": \\\"Operator\\\",\\n                    \\\"type\\\": \\\"str\\\",\\n                    \\\"description\\\": \\\"Set the operator for the field. \\\"\\n                    \\\"https://docs.datastax.com/en/astra-db-serverless/api-reference/documents.html#operators\\\",\\n                    \\\"default\\\": \\\"$eq\\\",\\n                    \\\"options\\\": [\\n                        \\\"$gt\\\",\\n                        \\\"$gte\\\",\\n                        \\\"$lt\\\",\\n                        \\\"$lte\\\",\\n                        \\\"$eq\\\",\\n                        \\\"$ne\\\",\\n                        \\\"$in\\\",\\n                        \\\"$nin\\\",\\n                        \\\"$exists\\\",\\n                        \\\"$all\\\",\\n                        \\\"$size\\\",\\n                    ],\\n                    \\\"edit_mode\\\": EditMode.INLINE,\\n                },\\n            ],\\n            value=[],\\n        ),\\n        DictInput(\\n            name=\\\"tool_params\\\",\\n            info=\\\"DEPRECATED: Attributes to filter and description to the model. \\\"\\n            \\\"Add ! for mandatory (e.g: !customerId)\\\",\\n            display_name=\\\"Tool params\\\",\\n            is_list=True,\\n            advanced=True,\\n        ),\\n        DictInput(\\n            name=\\\"static_filters\\\",\\n            info=\\\"Attributes to filter and corresponding value\\\",\\n            display_name=\\\"Static filters\\\",\\n            advanced=True,\\n            is_list=True,\\n        ),\\n        IntInput(\\n            name=\\\"number_of_results\\\",\\n            display_name=\\\"Number of Results\\\",\\n            info=\\\"Number of results to return.\\\",\\n            advanced=True,\\n            value=5,\\n        ),\\n        BoolInput(\\n            name=\\\"use_search_query\\\",\\n            display_name=\\\"Semantic Search\\\",\\n            info=\\\"When this parameter is activated, the search query parameter will be used to search the collection.\\\",\\n            advanced=False,\\n            value=False,\\n        ),\\n        BoolInput(\\n            name=\\\"use_vectorize\\\",\\n            display_name=\\\"Use Astra DB Vectorize\\\",\\n            info=\\\"When this parameter is activated, Astra DB Vectorize method will be used to generate the embeddings.\\\",\\n            advanced=False,\\n            value=False,\\n        ),\\n        StrInput(\\n            name=\\\"semantic_search_instruction\\\",\\n            display_name=\\\"Semantic Search Instruction\\\",\\n            info=\\\"The instruction to use for the semantic search.\\\",\\n            required=True,\\n            value=\\\"Search query to find relevant documents.\\\",\\n            advanced=True,\\n        ),\\n    ]\\n\\n    _cached_client: DataAPIClient | None = None\\n    _cached_db: Database | None = None\\n    _cached_collection: Collection | None = None\\n\\n    def create_args_schema(self) -> dict[str, BaseModel]:\\n        \\\"\\\"\\\"DEPRECATED: This method is deprecated. Please use create_args_schema_v2 instead.\\n\\n        It is keep only for backward compatibility.\\n        \\\"\\\"\\\"\\n        logger.warning(\\\"This is the old way to define the tool parameters. Please use the new way.\\\")\\n        args: dict[str, tuple[Any, Field] | list[str]] = {}\\n\\n        for key in self.tool_params:\\n            if key.startswith(\\\"!\\\"):  # Mandatory\\n                args[key[1:]] = (str, Field(description=self.tool_params[key]))\\n            else:  # Optional\\n                args[key] = (\\n                    str | None,\\n                    Field(description=self.tool_params[key], default=None),\\n                )\\n\\n        if self.use_search_query:\\n            args[\\\"search_query\\\"] = (\\n                str | None,\\n                Field(description=\\\"Search query to find relevant documents.\\\", default=None),\\n            )\\n\\n        model = create_model(\\\"ToolInput\\\", **args, __base__=BaseModel)\\n        return {\\\"ToolInput\\\": model}\\n\\n    def create_args_schema_v2(self) -> dict[str, BaseModel]:\\n        \\\"\\\"\\\"Create the tool input schema using the new tool parameters configuration.\\\"\\\"\\\"\\n        args: dict[str, tuple[Any, Field] | list[str]] = {}\\n\\n        for tool_param in self.tools_params_v2:\\n            if tool_param[\\\"mandatory\\\"]:\\n                args[tool_param[\\\"name\\\"]] = (\\n                    str,\\n                    Field(description=tool_param[\\\"description\\\"]),\\n                )\\n            else:\\n                args[tool_param[\\\"name\\\"]] = (\\n                    str | None,\\n                    Field(description=tool_param[\\\"description\\\"], default=None),\\n                )\\n\\n        if self.use_search_query:\\n            args[\\\"search_query\\\"] = (\\n                str,\\n                Field(description=self.semantic_search_instruction),\\n            )\\n\\n        model = create_model(\\\"ToolInput\\\", **args, __base__=BaseModel)\\n        return {\\\"ToolInput\\\": model}\\n\\n    def build_tool(self) -> Tool:\\n        \\\"\\\"\\\"Builds an Astra DB Collection tool.\\n\\n        Returns:\\n            Tool: The built Astra DB tool.\\n        \\\"\\\"\\\"\\n        schema_dict = self.create_args_schema() if len(self.tool_params.keys()) > 0 else self.create_args_schema_v2()\\n\\n        tool = StructuredTool.from_function(\\n            name=self.tool_name,\\n            args_schema=schema_dict[\\\"ToolInput\\\"],\\n            description=self.tool_description,\\n            func=self.run_model,\\n            return_direct=False,\\n        )\\n        self.status = \\\"Astra DB Tool created\\\"\\n\\n        return tool\\n\\n    def projection_args(self, input_str: str) -> dict | None:\\n        \\\"\\\"\\\"Build the projection arguments for the Astra DB query.\\\"\\\"\\\"\\n        elements = input_str.split(\\\",\\\")\\n        result = {}\\n\\n        if elements == [\\\"*\\\"]:\\n            return None\\n\\n        # Force the projection to exclude the $vector field as it is not required by the tool\\n        result[\\\"$vector\\\"] = False\\n\\n        # Fields with ! as prefix should be removed from the projection\\n        for element in elements:\\n            if element.startswith(\\\"!\\\"):\\n                result[element[1:]] = False\\n            else:\\n                result[element] = True\\n\\n        return result\\n\\n    def parse_timestamp(self, timestamp_str: str) -> datetime:\\n        \\\"\\\"\\\"Parse a timestamp string into Astra DB REST API format.\\n\\n        Args:\\n            timestamp_str (str): Input timestamp string\\n\\n        Returns:\\n            datetime: Datetime object\\n\\n        Raises:\\n            ValueError: If the timestamp cannot be parsed\\n        \\\"\\\"\\\"\\n        # Common datetime formats to try\\n        formats = [\\n            \\\"%Y-%m-%d\\\",  # 2024-03-21\\n            \\\"%Y-%m-%dT%H:%M:%S\\\",  # 2024-03-21T15:30:00\\n            \\\"%Y-%m-%dT%H:%M:%S%z\\\",  # 2024-03-21T15:30:00+0000\\n            \\\"%Y-%m-%d %H:%M:%S\\\",  # 2024-03-21 15:30:00\\n            \\\"%d/%m/%Y\\\",  # 21/03/2024\\n            \\\"%Y/%m/%d\\\",  # 2024/03/21\\n        ]\\n\\n        for fmt in formats:\\n            try:\\n                # Parse the date string\\n                date_obj = datetime.strptime(timestamp_str, fmt).astimezone()\\n\\n                # If the parsed date has no timezone info, assume UTC\\n                if date_obj.tzinfo is None:\\n                    date_obj = date_obj.replace(tzinfo=timezone.utc)\\n\\n                # Convert to UTC and format\\n                return date_obj.astimezone(timezone.utc)\\n\\n            except ValueError:\\n                continue\\n\\n        msg = f\\\"Could not parse date: {timestamp_str}\\\"\\n        logger.error(msg)\\n        raise ValueError(msg)\\n\\n    def build_filter(self, args: dict, filter_settings: list) -> dict:\\n        \\\"\\\"\\\"Build filter dictionary for Astra DB query.\\n\\n        Args:\\n            args: Dictionary of arguments from the tool\\n            filter_settings: List of filter settings from tools_params_v2\\n        Returns:\\n            Dictionary containing the filter conditions\\n        \\\"\\\"\\\"\\n        filters = {**self.static_filters}\\n\\n        for key, value in args.items():\\n            # Skip search_query as it's handled separately\\n            if key == \\\"search_query\\\":\\n                continue\\n\\n            filter_setting = next((x for x in filter_settings if x[\\\"name\\\"] == key), None)\\n            if filter_setting and value is not None:\\n                field_name = filter_setting[\\\"attribute_name\\\"] if filter_setting[\\\"attribute_name\\\"] else key\\n                filter_key = field_name if not filter_setting[\\\"metadata\\\"] else f\\\"metadata.{field_name}\\\"\\n                if filter_setting[\\\"operator\\\"] == \\\"$exists\\\":\\n                    filters[filter_key] = {\\n                        **filters.get(filter_key, {}),\\n                        filter_setting[\\\"operator\\\"]: True,\\n                    }\\n                elif filter_setting[\\\"operator\\\"] in [\\\"$in\\\", \\\"$nin\\\", \\\"$all\\\"]:\\n                    filters[filter_key] = {\\n                        **filters.get(filter_key, {}),\\n                        filter_setting[\\\"operator\\\"]: value.split(\\\",\\\") if isinstance(value, str) else value,\\n                    }\\n                elif filter_setting[\\\"is_timestamp\\\"] == True:  # noqa: E712\\n                    try:\\n                        filters[filter_key] = {\\n                            **filters.get(filter_key, {}),\\n                            filter_setting[\\\"operator\\\"]: self.parse_timestamp(value),\\n                        }\\n                    except ValueError as e:\\n                        msg = f\\\"Error parsing timestamp: {e} - Use the prompt to specify the date in the correct format\\\"\\n                        logger.error(msg)\\n                        raise ValueError(msg) from e\\n                else:\\n                    filters[filter_key] = {\\n                        **filters.get(filter_key, {}),\\n                        filter_setting[\\\"operator\\\"]: value,\\n                    }\\n        return filters\\n\\n    def run_model(self, **args) -> Data | list[Data]:\\n        \\\"\\\"\\\"Run the query to get the data from the Astra DB collection.\\\"\\\"\\\"\\n        sort = {}\\n\\n        # Build filters using the new method\\n        filters = self.build_filter(args, self.tools_params_v2)\\n\\n        # Build the vector search on\\n        if self.use_search_query and args[\\\"search_query\\\"] is not None and args[\\\"search_query\\\"] != \\\"\\\":\\n            if self.use_vectorize:\\n                sort[\\\"$vectorize\\\"] = args[\\\"search_query\\\"]\\n            else:\\n                if self.embedding is None:\\n                    msg = \\\"Embedding model is not set. Please set the embedding model or use Astra DB Vectorize.\\\"\\n                    logger.error(msg)\\n                    raise ValueError(msg)\\n                embedding_query = self.embedding.embed_query(args[\\\"search_query\\\"])\\n                sort[\\\"$vector\\\"] = embedding_query\\n            del args[\\\"search_query\\\"]\\n\\n        find_options = {\\n            \\\"filter\\\": filters,\\n            \\\"limit\\\": self.number_of_results,\\n            \\\"sort\\\": sort,\\n        }\\n\\n        projection = self.projection_args(self.projection_attributes)\\n        if projection and len(projection) > 0:\\n            find_options[\\\"projection\\\"] = projection\\n\\n        try:\\n            database = self.get_database_object(api_endpoint=self.get_api_endpoint())\\n            collection = database.get_collection(\\n                name=self.collection_name,\\n                keyspace=self.get_keyspace(),\\n            )\\n            results = collection.find(**find_options)\\n        except Exception as e:\\n            msg = f\\\"Error on Astra DB Tool {self.tool_name} request: {e}\\\"\\n            logger.error(msg)\\n            raise ValueError(msg) from e\\n\\n        logger.info(f\\\"Tool {self.tool_name} executed`\\\")\\n\\n        data: list[Data] = [Data(data=doc) for doc in results]\\n        self.status = data\\n        return data\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/datastax/src/lfx_datastax/components/datastax/astradb_vectorize.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"a873d1ea2adc546ac6229c5b164e82e46c6c50a283e03adec6d217ebd04831cb\",\"content\":\"from typing import Any\\n\\nfrom lfx.custom.custom_component.component import Component\\nfrom lfx.inputs.inputs import DictInput, DropdownInput, MessageTextInput, SecretStrInput\\nfrom lfx.template.field.base import Output\\n\\n\\nclass AstraVectorizeComponent(Component):\\n    display_name: str = \\\"Astra Vectorize\\\"\\n    description: str = \\\"Configuration options for Astra Vectorize server-side embeddings. \\\"\\n    documentation: str = \\\"https://docs.datastax.com/en/astra-db-serverless/databases/embedding-generation.html\\\"\\n    legacy = True\\n    icon = \\\"AstraDB\\\"\\n    name = \\\"AstraVectorize\\\"\\n    replacement = [\\\"datastax.AstraDB\\\"]\\n\\n    VECTORIZE_PROVIDERS_MAPPING = {\\n        \\\"Azure OpenAI\\\": [\\n            \\\"azureOpenAI\\\",\\n            [\\n                \\\"text-embedding-3-small\\\",\\n                \\\"text-embedding-3-large\\\",\\n                \\\"text-embedding-ada-002\\\",\\n            ],\\n        ],\\n        \\\"Hugging Face - Dedicated\\\": [\\n            \\\"huggingfaceDedicated\\\",\\n            [\\\"endpoint-defined-model\\\"],\\n        ],\\n        \\\"Hugging Face - Serverless\\\": [\\n            \\\"huggingface\\\",\\n            [\\n                \\\"sentence-transformers/all-MiniLM-L6-v2\\\",\\n                \\\"intfloat/multilingual-e5-large\\\",\\n                \\\"intfloat/multilingual-e5-large-instruct\\\",\\n                \\\"BAAI/bge-small-en-v1.5\\\",\\n                \\\"BAAI/bge-base-en-v1.5\\\",\\n                \\\"BAAI/bge-large-en-v1.5\\\",\\n            ],\\n        ],\\n        \\\"Jina AI\\\": [\\n            \\\"jinaAI\\\",\\n            [\\n                \\\"jina-embeddings-v2-base-en\\\",\\n                \\\"jina-embeddings-v2-base-de\\\",\\n                \\\"jina-embeddings-v2-base-es\\\",\\n                \\\"jina-embeddings-v2-base-code\\\",\\n                \\\"jina-embeddings-v2-base-zh\\\",\\n            ],\\n        ],\\n        \\\"Mistral AI\\\": [\\\"mistral\\\", [\\\"mistral-embed\\\"]],\\n        \\\"NVIDIA\\\": [\\\"nvidia\\\", [\\\"NV-Embed-QA\\\"]],\\n        \\\"OpenAI\\\": [\\n            \\\"openai\\\",\\n            [\\n                \\\"text-embedding-3-small\\\",\\n                \\\"text-embedding-3-large\\\",\\n                \\\"text-embedding-ada-002\\\",\\n            ],\\n        ],\\n        \\\"Upstage\\\": [\\\"upstageAI\\\", [\\\"solar-embedding-1-large\\\"]],\\n        \\\"Voyage AI\\\": [\\n            \\\"voyageAI\\\",\\n            [\\n                \\\"voyage-large-2-instruct\\\",\\n                \\\"voyage-law-2\\\",\\n                \\\"voyage-code-2\\\",\\n                \\\"voyage-large-2\\\",\\n                \\\"voyage-2\\\",\\n            ],\\n        ],\\n    }\\n    VECTORIZE_MODELS_STR = \\\"\\\\n\\\\n\\\".join(\\n        [provider + \\\": \\\" + (\\\", \\\".join(models[1])) for provider, models in VECTORIZE_PROVIDERS_MAPPING.items()]\\n    )\\n\\n    inputs = [\\n        DropdownInput(\\n            name=\\\"provider\\\",\\n            display_name=\\\"Provider\\\",\\n            options=VECTORIZE_PROVIDERS_MAPPING.keys(),\\n            value=\\\"\\\",\\n            required=True,\\n        ),\\n        MessageTextInput(\\n            name=\\\"model_name\\\",\\n            display_name=\\\"Model Name\\\",\\n            info=\\\"The embedding model to use for the selected provider. Each provider has a different set of models \\\"\\n            f\\\"available (full list at https://docs.datastax.com/en/astra-db-serverless/databases/embedding-generation.html):\\\\n\\\\n{VECTORIZE_MODELS_STR}\\\",\\n            required=True,\\n        ),\\n        MessageTextInput(\\n            name=\\\"api_key_name\\\",\\n            display_name=\\\"API Key name\\\",\\n            info=\\\"The name of the embeddings provider API key stored on Astra. \\\"\\n            \\\"If set, it will override the 'ProviderKey' in the authentication parameters.\\\",\\n        ),\\n        DictInput(\\n            name=\\\"authentication\\\",\\n            display_name=\\\"Authentication parameters\\\",\\n            is_list=True,\\n            advanced=True,\\n        ),\\n        SecretStrInput(\\n            name=\\\"provider_api_key\\\",\\n            display_name=\\\"Provider API Key\\\",\\n            info=\\\"An alternative to the Astra Authentication that passes an API key for the provider with each request \\\"\\n            \\\"to Astra DB. \\\"\\n            \\\"This may be used when Vectorize is configured for the collection, \\\"\\n            \\\"but no corresponding provider secret is stored within Astra's key management system.\\\",\\n            advanced=True,\\n        ),\\n        DictInput(\\n            name=\\\"authentication\\\",\\n            display_name=\\\"Authentication Parameters\\\",\\n            is_list=True,\\n            advanced=True,\\n        ),\\n        DictInput(\\n            name=\\\"model_parameters\\\",\\n            display_name=\\\"Model Parameters\\\",\\n            advanced=True,\\n            is_list=True,\\n        ),\\n    ]\\n    outputs = [\\n        Output(\\n            display_name=\\\"Vectorize\\\",\\n            name=\\\"config\\\",\\n            method=\\\"build_options\\\",\\n            types=[\\\"dict\\\"],\\n        ),\\n    ]\\n\\n    def build_options(self) -> dict[str, Any]:\\n        provider_value = self.VECTORIZE_PROVIDERS_MAPPING[self.provider][0]\\n        authentication = {**(self.authentication or {})}\\n        api_key_name = self.api_key_name\\n        if api_key_name:\\n            authentication[\\\"providerKey\\\"] = api_key_name\\n        return {\\n            # must match astrapy.info.VectorServiceOptions\\n            \\\"collection_vector_service_options\\\": {\\n                \\\"provider\\\": provider_value,\\n                \\\"modelName\\\": self.model_name,\\n                \\\"authentication\\\": authentication,\\n                \\\"parameters\\\": self.model_parameters or {},\\n            },\\n            \\\"collection_embedding_api_key\\\": self.provider_api_key,\\n        }\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/datastax/src/lfx_datastax/components/datastax/astradb_vectorstore.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e1932dd492eda2f4f66144d7f8c6443c5f12d0aebc9624949fb57feb941d8747\",\"content\":\"from astrapy import DataAPIClient\\nfrom langchain_core.documents import Document\\n\\nfrom lfx_datastax.base.astradb_base import AstraDBBaseComponent\\nfrom lfx.base.models.unified_models import (\\n    apply_provider_variable_config_to_build_config,\\n    get_embedding_model_options,\\n    get_embeddings,\\n    update_model_options_in_build_config,\\n)\\nfrom lfx.base.vectorstores.model import (\\n    LCVectorStoreComponent,\\n    check_cached_vector_store,\\n)\\nfrom lfx.base.vectorstores.vector_store_connection_decorator import (\\n    vector_store_connection,\\n)\\nfrom lfx.helpers.data import docs_to_data\\nfrom lfx.io import (\\n    BoolInput,\\n    DropdownInput,\\n    FloatInput,\\n    IntInput,\\n    ModelInput,\\n    NestedDictInput,\\n    QueryInput,\\n    SecretStrInput,\\n    StrInput,\\n)\\nfrom lfx.schema.data import Data\\nfrom lfx.serialization import serialize\\nfrom lfx.utils.version import get_version_info\\n\\n\\n@vector_store_connection\\nclass AstraDBVectorStoreComponent(AstraDBBaseComponent, LCVectorStoreComponent):\\n    display_name: str = \\\"Astra DB\\\"\\n    description: str = \\\"Ingest and search documents in Astra DB\\\"\\n    documentation: str = \\\"https://docs.langflow.org/bundles-datastax\\\"\\n    name = \\\"AstraDB\\\"\\n    icon: str = \\\"AstraDB\\\"\\n\\n    inputs = [\\n        *AstraDBBaseComponent.inputs,\\n        *LCVectorStoreComponent.inputs,\\n        ModelInput(\\n            name=\\\"embedding_model\\\",\\n            display_name=\\\"Embedding Model\\\",\\n            info=\\\"Specify the Embedding Model. Not required for Astra Vectorize collections.\\\",\\n            required=False,\\n            show=True,\\n            model_type=\\\"embedding\\\",\\n            input_types=[\\\"Embeddings\\\"],\\n            real_time_refresh=True,\\n        ),\\n        SecretStrInput(\\n            name=\\\"api_key\\\",\\n            display_name=\\\"API Key\\\",\\n            info=\\\"Overrides global provider settings. Leave blank to use your pre-configured API Key.\\\",\\n            real_time_refresh=True,\\n            advanced=True,\\n        ),\\n        StrInput(\\n            name=\\\"content_field\\\",\\n            display_name=\\\"Content Field\\\",\\n            info=\\\"Field to use as the text content field for the vector store.\\\",\\n            advanced=True,\\n        ),\\n        StrInput(\\n            name=\\\"deletion_field\\\",\\n            display_name=\\\"Deletion Based On Field\\\",\\n            info=\\\"When this parameter is provided, documents in the target collection with \\\"\\n            \\\"metadata field values matching the input metadata field value will be deleted \\\"\\n            \\\"before new data is loaded.\\\",\\n            advanced=True,\\n        ),\\n        BoolInput(\\n            name=\\\"ignore_invalid_documents\\\",\\n            display_name=\\\"Ignore Invalid Documents\\\",\\n            info=\\\"Boolean flag to determine whether to ignore invalid documents at runtime.\\\",\\n            advanced=True,\\n        ),\\n        NestedDictInput(\\n            name=\\\"astradb_vectorstore_kwargs\\\",\\n            display_name=\\\"AstraDBVectorStore Parameters\\\",\\n            info=\\\"Optional dictionary of additional parameters for the AstraDBVectorStore.\\\",\\n            advanced=True,\\n        ),\\n        DropdownInput(\\n            name=\\\"search_method\\\",\\n            display_name=\\\"Search Method\\\",\\n            info=(\\n                \\\"Determine how your content is matched: Vector finds semantic similarity, \\\"\\n                \\\"and Hybrid Search (suggested) combines both approaches \\\"\\n                \\\"with a reranker.\\\"\\n            ),\\n            options=[\\\"Hybrid Search\\\", \\\"Vector Search\\\"],  # TODO: Restore Lexical Search?\\n            options_metadata=[{\\\"icon\\\": \\\"SearchHybrid\\\"}, {\\\"icon\\\": \\\"SearchVector\\\"}],\\n            value=\\\"Vector Search\\\",\\n            advanced=True,\\n            real_time_refresh=True,\\n        ),\\n        DropdownInput(\\n            name=\\\"reranker\\\",\\n            display_name=\\\"Reranker\\\",\\n            info=\\\"Post-retrieval model that re-scores results for optimal relevance ranking.\\\",\\n            show=False,\\n            toggle=True,\\n        ),\\n        QueryInput(\\n            name=\\\"lexical_terms\\\",\\n            display_name=\\\"Lexical Terms\\\",\\n            info=\\\"Add additional terms/keywords to augment search precision.\\\",\\n            placeholder=\\\"Enter terms to search...\\\",\\n            separator=\\\" \\\",\\n            show=False,\\n            value=\\\"\\\",\\n        ),\\n        IntInput(\\n            name=\\\"number_of_results\\\",\\n            display_name=\\\"Number of Search Results\\\",\\n            info=\\\"Number of search results to return.\\\",\\n            advanced=True,\\n            value=4,\\n        ),\\n        DropdownInput(\\n            name=\\\"search_type\\\",\\n            display_name=\\\"Search Type\\\",\\n            info=\\\"Search type to use\\\",\\n            options=[\\n                \\\"Similarity\\\",\\n                \\\"Similarity with score threshold\\\",\\n                \\\"MMR (Max Marginal Relevance)\\\",\\n            ],\\n            value=\\\"Similarity\\\",\\n            advanced=True,\\n        ),\\n        FloatInput(\\n            name=\\\"search_score_threshold\\\",\\n            display_name=\\\"Search Score Threshold\\\",\\n            info=\\\"Minimum similarity score threshold for search results. \\\"\\n            \\\"(when using 'Similarity with score threshold')\\\",\\n            value=0,\\n            advanced=True,\\n        ),\\n        NestedDictInput(\\n            name=\\\"advanced_search_filter\\\",\\n            display_name=\\\"Search Metadata Filter\\\",\\n            info=\\\"Optional dictionary of filters to apply to the search query.\\\",\\n            advanced=True,\\n        ),\\n    ]\\n\\n    async def update_build_config(\\n        self,\\n        build_config: dict,\\n        field_value: str | dict,\\n        field_name: str | None = None,\\n    ) -> dict:\\n        \\\"\\\"\\\"Update build configuration with proper handling of embedding and search options.\\\"\\\"\\\"\\n        # Update model options for ModelInput only when relevant.\\n        # Only refresh when: initial load (None), embedding_model field changes, or api_key changes.\\n        #\\n        # Note: this intentionally uses update_model_options_in_build_config directly rather than\\n        # handle_model_input_update because:\\n        #   1. The model field is named \\\"embedding_model\\\" (not \\\"model\\\"), requiring model_field_name.\\n        #   2. The refresh is conditional - we skip it for unrelated fields (e.g. database_name,\\n        #      collection_name) to avoid unnecessary work.\\n        #   3. AstraDB manages its own provider-field visibility (embedding_generation_provider\\n        #      dialog), so the generic provider-field hide/show steps in handle_model_input_update\\n        #      are not applicable here.\\n        if field_name in (None, \\\"embedding_model\\\", \\\"api_key\\\"):\\n            build_config = update_model_options_in_build_config(\\n                component=self,\\n                build_config=build_config,\\n                cache_key_prefix=\\\"embedding_model_options\\\",\\n                get_options_func=get_embedding_model_options,\\n                field_name=field_name,\\n                field_value=field_value if field_name == \\\"embedding_model\\\" else None,\\n                model_field_name=\\\"embedding_model\\\",\\n            )\\n\\n            # Auto-populate API key based on the selected embedding model's provider.\\n            # Skip when user directly edits api_key to preserve their value.\\n            if field_name != \\\"api_key\\\":\\n                model_value = build_config.get(\\\"embedding_model\\\", {}).get(\\\"value\\\")\\n                if isinstance(model_value, list) and model_value:\\n                    provider = model_value[0].get(\\\"provider\\\", \\\"\\\")\\n                    if provider:\\n                        build_config = apply_provider_variable_config_to_build_config(build_config, provider)\\n\\n            # Ensure the API key field is always visible\\n            if \\\"api_key\\\" in build_config:\\n                build_config[\\\"api_key\\\"][\\\"show\\\"] = True\\n\\n        # Handle base astra db build config updates\\n        build_config = await super().update_build_config(\\n            build_config,\\n            field_value=field_value,\\n            field_name=field_name,\\n        )\\n\\n        # Set embedding model display based on provider selection\\n        if isinstance(field_value, dict) and \\\"02_embedding_generation_provider\\\" in field_value:\\n            embedding_provider = field_value.get(\\\"02_embedding_generation_provider\\\")\\n            is_custom_provider = embedding_provider and embedding_provider != \\\"Bring your own\\\"\\n            provider = embedding_provider.lower() if is_custom_provider and embedding_provider is not None else None\\n\\n            build_config[\\\"embedding_model\\\"][\\\"show\\\"] = not bool(provider)\\n            build_config[\\\"embedding_model\\\"][\\\"required\\\"] = not bool(provider)\\n\\n        # Early return if no API endpoint is configured\\n        if not self.get_api_endpoint():\\n            return build_config\\n\\n        # Configure search method and related options\\n        return self._configure_search_options(build_config)\\n\\n    def _configure_search_options(self, build_config: dict) -> dict:\\n        \\\"\\\"\\\"Configure hybrid search, reranker, and vector search options.\\\"\\\"\\\"\\n        # Detect available hybrid search capabilities\\n        hybrid_capabilities = self._detect_hybrid_capabilities()\\n\\n        # Return if we haven't selected a collection\\n        if not build_config[\\\"collection_name\\\"][\\\"options\\\"] or not build_config[\\\"collection_name\\\"][\\\"value\\\"]:\\n            return build_config\\n\\n        # Get collection options\\n        collection_options = self._get_collection_options(build_config)\\n\\n        # Get the selected collection index\\n        index = build_config[\\\"collection_name\\\"][\\\"options\\\"].index(build_config[\\\"collection_name\\\"][\\\"value\\\"])\\n        provider = build_config[\\\"collection_name\\\"][\\\"options_metadata\\\"][index][\\\"provider\\\"]\\n        build_config[\\\"embedding_model\\\"][\\\"show\\\"] = not bool(provider)\\n        build_config[\\\"embedding_model\\\"][\\\"required\\\"] = not bool(provider)\\n\\n        # Determine search configuration\\n        is_vector_search = build_config[\\\"search_method\\\"][\\\"value\\\"] == \\\"Vector Search\\\"\\n        is_autodetect = build_config[\\\"autodetect_collection\\\"][\\\"value\\\"]\\n\\n        # Apply hybrid search configuration\\n        if hybrid_capabilities[\\\"available\\\"]:\\n            build_config[\\\"search_method\\\"][\\\"show\\\"] = True\\n            build_config[\\\"search_method\\\"][\\\"options\\\"] = [\\n                \\\"Hybrid Search\\\",\\n                \\\"Vector Search\\\",\\n            ]\\n            build_config[\\\"search_method\\\"][\\\"value\\\"] = build_config[\\\"search_method\\\"].get(\\\"value\\\", \\\"Hybrid Search\\\")\\n\\n            build_config[\\\"reranker\\\"][\\\"options\\\"] = hybrid_capabilities[\\\"reranker_models\\\"]\\n            build_config[\\\"reranker\\\"][\\\"options_metadata\\\"] = hybrid_capabilities[\\\"reranker_metadata\\\"]\\n            if hybrid_capabilities[\\\"reranker_models\\\"]:\\n                build_config[\\\"reranker\\\"][\\\"value\\\"] = hybrid_capabilities[\\\"reranker_models\\\"][0]\\n        else:\\n            build_config[\\\"search_method\\\"][\\\"show\\\"] = False\\n            build_config[\\\"search_method\\\"][\\\"options\\\"] = [\\\"Vector Search\\\"]\\n            build_config[\\\"search_method\\\"][\\\"value\\\"] = \\\"Vector Search\\\"\\n            build_config[\\\"reranker\\\"][\\\"options\\\"] = []\\n            build_config[\\\"reranker\\\"][\\\"options_metadata\\\"] = []\\n\\n        # Configure reranker visibility and state\\n        hybrid_enabled = (\\n            collection_options[\\\"rerank_enabled\\\"] and build_config[\\\"search_method\\\"][\\\"value\\\"] == \\\"Hybrid Search\\\"\\n        )\\n\\n        build_config[\\\"reranker\\\"][\\\"show\\\"] = hybrid_enabled\\n        build_config[\\\"reranker\\\"][\\\"toggle_value\\\"] = hybrid_enabled\\n        build_config[\\\"reranker\\\"][\\\"toggle_disable\\\"] = is_vector_search\\n\\n        # Configure lexical terms\\n        lexical_visible = collection_options[\\\"lexical_enabled\\\"] and not is_vector_search\\n        build_config[\\\"lexical_terms\\\"][\\\"show\\\"] = lexical_visible\\n        build_config[\\\"lexical_terms\\\"][\\\"value\\\"] = \\\"\\\" if is_vector_search else build_config[\\\"lexical_terms\\\"][\\\"value\\\"]\\n\\n        # Configure search type and score threshold\\n        build_config[\\\"search_type\\\"][\\\"show\\\"] = is_vector_search\\n        build_config[\\\"search_score_threshold\\\"][\\\"show\\\"] = is_vector_search\\n\\n        # Force similarity search for hybrid mode or autodetect\\n        if hybrid_enabled or is_autodetect:\\n            build_config[\\\"search_type\\\"][\\\"value\\\"] = \\\"Similarity\\\"\\n\\n        return build_config\\n\\n    def _detect_hybrid_capabilities(self) -> dict:\\n        \\\"\\\"\\\"Detect available hybrid search and reranking capabilities.\\\"\\\"\\\"\\n        environment = self.get_environment(self.environment)\\n        client = DataAPIClient(environment=environment)\\n        admin_client = client.get_admin()\\n        db_admin = admin_client.get_database_admin(self.get_api_endpoint(), token=self.token)\\n\\n        try:\\n            providers = db_admin.find_reranking_providers()\\n            reranker_models = [\\n                model.name for provider_data in providers.reranking_providers.values() for model in provider_data.models\\n            ]\\n            reranker_metadata = [\\n                {\\\"icon\\\": self.get_provider_icon(provider_name=model.name.split(\\\"/\\\")[0])}\\n                for provider in providers.reranking_providers.values()\\n                for model in provider.models\\n            ]\\n        except Exception as e:  # noqa: BLE001\\n            self.log(f\\\"Hybrid search not available: {e}\\\")\\n            return {\\n                \\\"available\\\": False,\\n                \\\"reranker_models\\\": [],\\n                \\\"reranker_metadata\\\": [],\\n            }\\n        else:\\n            return {\\n                \\\"available\\\": True,\\n                \\\"reranker_models\\\": reranker_models,\\n                \\\"reranker_metadata\\\": reranker_metadata,\\n            }\\n\\n    def _get_collection_options(self, build_config: dict) -> dict:\\n        \\\"\\\"\\\"Retrieve collection-level search options.\\\"\\\"\\\"\\n        database = self.get_database_object(api_endpoint=build_config[\\\"api_endpoint\\\"][\\\"value\\\"])\\n        collection = database.get_collection(\\n            name=build_config[\\\"collection_name\\\"][\\\"value\\\"],\\n            keyspace=build_config[\\\"keyspace\\\"][\\\"value\\\"],\\n        )\\n\\n        col_options = collection.options()\\n\\n        return {\\n            \\\"rerank_enabled\\\": bool(col_options.rerank and col_options.rerank.enabled),\\n            \\\"lexical_enabled\\\": bool(col_options.lexical and col_options.lexical.enabled),\\n        }\\n\\n    @check_cached_vector_store\\n    def build_vector_store(self):\\n        try:\\n            from langchain_astradb import AstraDBVectorStore\\n            from langchain_astradb.utils.astradb import HybridSearchMode\\n        except ImportError as e:\\n            msg = (\\n                \\\"Could not import langchain Astra DB integration package. \\\"\\n                \\\"Please install it with `pip install langchain-astradb`.\\\"\\n            )\\n            raise ImportError(msg) from e\\n\\n        # Resolve the embedding model from ModelInput selection to an Embeddings instance\\n        embedding = None\\n        if self.embedding_model:\\n            embedding = get_embeddings(\\n                model=self.embedding_model,\\n                user_id=self.user_id,\\n                api_key=getattr(self, \\\"api_key\\\", None),\\n            )\\n        embedding_params = {\\\"embedding\\\": embedding} if embedding else {}\\n\\n        # Get the additional parameters\\n        additional_params = self.astradb_vectorstore_kwargs or {}\\n\\n        # Get Langflow version and platform information\\n        __version__ = get_version_info()[\\\"version\\\"]\\n        langflow_prefix = \\\"\\\"\\n        # if os.getenv(\\\"AWS_EXECUTION_ENV\\\") == \\\"AWS_ECS_FARGATE\\\":  # TODO: More precise way of detecting\\n        #     langflow_prefix = \\\"ds-\\\"\\n\\n        # Get the database object\\n        database = self.get_database_object()\\n        autodetect = self.collection_name in database.list_collection_names() and self.autodetect_collection\\n\\n        # Bundle up the auto-detect parameters\\n        autodetect_params = {\\n            \\\"autodetect_collection\\\": autodetect,\\n            \\\"content_field\\\": (\\n                self.content_field\\n                if self.content_field and embedding_params\\n                else (\\n                    \\\"page_content\\\"\\n                    if embedding_params\\n                    and self.collection_data(collection_name=self.collection_name, database=database) == 0\\n                    else None\\n                )\\n            ),\\n            \\\"ignore_invalid_documents\\\": self.ignore_invalid_documents,\\n        }\\n\\n        # Choose HybridSearchMode based on the selected param\\n        hybrid_search_mode = HybridSearchMode.DEFAULT if self.search_method == \\\"Hybrid Search\\\" else HybridSearchMode.OFF\\n\\n        # Attempt to build the Vector Store object\\n        try:\\n            vector_store = AstraDBVectorStore(\\n                # Astra DB Authentication Parameters\\n                token=self.token,\\n                api_endpoint=database.api_endpoint,\\n                namespace=database.keyspace,\\n                collection_name=self.collection_name,\\n                environment=self.environment,\\n                # Hybrid Search Parameters\\n                hybrid_search=hybrid_search_mode,\\n                # Astra DB Usage Tracking Parameters\\n                ext_callers=[(f\\\"{langflow_prefix}langflow\\\", __version__)],\\n                # Astra DB Vector Store Parameters\\n                **autodetect_params,\\n                **embedding_params,\\n                **additional_params,\\n            )\\n        except ValueError as e:\\n            msg = f\\\"Error initializing AstraDBVectorStore: {e}\\\"\\n            raise ValueError(msg) from e\\n\\n        # Add documents to the vector store\\n        self._add_documents_to_vector_store(vector_store)\\n\\n        return vector_store\\n\\n    def _add_documents_to_vector_store(self, vector_store) -> None:\\n        self.ingest_data = self._prepare_ingest_data()\\n\\n        documents = []\\n        for _input in self.ingest_data or []:\\n            if isinstance(_input, Data):\\n                documents.append(_input.to_lc_document())\\n            else:\\n                msg = \\\"Vector Store Inputs must be Data objects.\\\"\\n                raise TypeError(msg)\\n\\n        documents = [\\n            Document(\\n                page_content=doc.page_content,\\n                metadata=serialize(doc.metadata, to_str=True),\\n            )\\n            for doc in documents\\n        ]\\n\\n        if documents and self.deletion_field:\\n            self.log(f\\\"Deleting documents where {self.deletion_field}\\\")\\n            try:\\n                database = self.get_database_object()\\n                collection = database.get_collection(self.collection_name, keyspace=database.keyspace)\\n                delete_values = list({doc.metadata[self.deletion_field] for doc in documents})\\n                self.log(f\\\"Deleting documents where {self.deletion_field} matches {delete_values}.\\\")\\n                collection.delete_many({f\\\"metadata.{self.deletion_field}\\\": {\\\"$in\\\": delete_values}})\\n            except ValueError as e:\\n                msg = f\\\"Error deleting documents from AstraDBVectorStore based on '{self.deletion_field}': {e}\\\"\\n                raise ValueError(msg) from e\\n\\n        if documents:\\n            self.log(f\\\"Adding {len(documents)} documents to the Vector Store.\\\")\\n            try:\\n                vector_store.add_documents(documents)\\n            except ValueError as e:\\n                msg = f\\\"Error adding documents to AstraDBVectorStore: {e}\\\"\\n                raise ValueError(msg) from e\\n        else:\\n            self.log(\\\"No documents to add to the Vector Store.\\\")\\n\\n    def _map_search_type(self) -> str:\\n        search_type_mapping = {\\n            \\\"Similarity with score threshold\\\": \\\"similarity_score_threshold\\\",\\n            \\\"MMR (Max Marginal Relevance)\\\": \\\"mmr\\\",\\n        }\\n\\n        return search_type_mapping.get(self.search_type, \\\"similarity\\\")\\n\\n    def _build_search_args(self):\\n        # Clean up the search query\\n        query = self.search_query if isinstance(self.search_query, str) and self.search_query.strip() else None\\n        lexical_terms = self.lexical_terms or None\\n\\n        # Check if we have a search query, and if so set the args\\n        if query:\\n            args = {\\n                \\\"query\\\": query,\\n                \\\"search_type\\\": self._map_search_type(),\\n                \\\"k\\\": self.number_of_results,\\n                \\\"score_threshold\\\": self.search_score_threshold,\\n                \\\"lexical_query\\\": lexical_terms,\\n            }\\n        elif self.advanced_search_filter:\\n            args = {\\n                \\\"n\\\": self.number_of_results,\\n            }\\n        else:\\n            return {}\\n\\n        filter_arg = self.advanced_search_filter or {}\\n        if filter_arg:\\n            args[\\\"filter\\\"] = filter_arg\\n\\n        return args\\n\\n    def search_documents(self, vector_store=None) -> list[Data]:\\n        vector_store = vector_store or self.build_vector_store()\\n\\n        self.log(f\\\"Search input: {self.search_query}\\\")\\n        self.log(f\\\"Search type: {self.search_type}\\\")\\n        self.log(f\\\"Number of results: {self.number_of_results}\\\")\\n        self.log(f\\\"store.hybrid_search: {vector_store.hybrid_search}\\\")\\n        self.log(f\\\"Lexical terms: {self.lexical_terms}\\\")\\n        self.log(f\\\"Reranker: {self.reranker}\\\")\\n\\n        try:\\n            search_args = self._build_search_args()\\n        except ValueError as e:\\n            msg = f\\\"Error in AstraDBVectorStore._build_search_args: {e}\\\"\\n            raise ValueError(msg) from e\\n\\n        if not search_args:\\n            self.log(\\\"No search input or filters provided. Skipping search.\\\")\\n            return []\\n\\n        docs = []\\n        search_method = \\\"search\\\" if \\\"query\\\" in search_args else \\\"metadata_search\\\"\\n\\n        try:\\n            self.log(f\\\"Calling vector_store.{search_method} with args: {search_args}\\\")\\n            docs = getattr(vector_store, search_method)(**search_args)\\n        except ValueError as e:\\n            msg = f\\\"Error performing {search_method} in AstraDBVectorStore: {e}\\\"\\n            raise ValueError(msg) from e\\n\\n        self.log(f\\\"Retrieved documents: {len(docs)}\\\")\\n\\n        data = docs_to_data(docs)\\n        self.log(f\\\"Converted documents to data: {len(data)}\\\")\\n        self.status = data\\n\\n        return data\\n\\n    def get_retriever_kwargs(self):\\n        search_args = self._build_search_args()\\n\\n        return {\\n            \\\"search_type\\\": self._map_search_type(),\\n            \\\"search_kwargs\\\": search_args,\\n        }\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/datastax/src/lfx_datastax/components/datastax/dotenv.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"343ea9aaca1bb995d483a7582621e4ad99b05849796c9974800a6c4d55a0e49f\",\"content\":\"import io\\n\\nfrom dotenv import load_dotenv\\n\\nfrom lfx.custom.custom_component.component import Component\\nfrom lfx.inputs.inputs import MultilineSecretInput\\nfrom lfx.schema.message import Message\\nfrom lfx.template.field.base import Output\\n\\n\\nclass Dotenv(Component):\\n    display_name = \\\"Dotenv\\\"\\n    description = \\\"Load .env file into env vars\\\"\\n    icon = \\\"AstraDB\\\"\\n    legacy = True\\n    inputs = [\\n        MultilineSecretInput(\\n            name=\\\"dotenv_file_content\\\",\\n            display_name=\\\"Dotenv file content\\\",\\n            info=\\\"Paste the content of your .env file directly, since contents are sensitive, \\\"\\n            \\\"using a Global variable set as 'password' is recommended\\\",\\n        )\\n    ]\\n\\n    outputs = [\\n        Output(display_name=\\\"env_set\\\", name=\\\"env_set\\\", method=\\\"process_inputs\\\"),\\n    ]\\n\\n    def process_inputs(self) -> Message:\\n        fake_file = io.StringIO(self.dotenv_file_content)\\n        result = load_dotenv(stream=fake_file, override=True)\\n\\n        message = Message(text=\\\"No variables found in .env\\\")\\n        if result:\\n            message = Message(text=\\\"Loaded .env\\\")\\n        return message\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/datastax/src/lfx_datastax/components/datastax/hcd.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"285ea1c799a9df798bed48b1a091ce42403820b57cced8c5553c3eb9d3b82976\",\"content\":\"from lfx.base.vectorstores.model import (\\n    LCVectorStoreComponent,\\n    check_cached_vector_store,\\n)\\nfrom lfx.helpers.data import docs_to_data\\nfrom lfx.inputs.inputs import DictInput, FloatInput\\nfrom lfx.io import (\\n    BoolInput,\\n    DropdownInput,\\n    HandleInput,\\n    IntInput,\\n    MultilineInput,\\n    SecretStrInput,\\n    StrInput,\\n)\\nfrom lfx.schema.data import Data\\nfrom lfx_datastax.base.astradb_base import validate_api_endpoint\\n\\n\\nclass HCDVectorStoreComponent(LCVectorStoreComponent):\\n    display_name: str = \\\"Hyper-Converged Database\\\"\\n    description: str = \\\"Implementation of Vector Store using Hyper-Converged Database (HCD) with search capabilities\\\"\\n    name = \\\"HCD\\\"\\n    documentation: str = \\\"https://docs.langflow.org/bundles-datastax\\\"\\n    icon: str = \\\"HCD\\\"\\n\\n    inputs = [\\n        StrInput(\\n            name=\\\"collection_name\\\",\\n            display_name=\\\"Collection Name\\\",\\n            info=\\\"The name of the collection within HCD where the vectors will be stored.\\\",\\n            required=True,\\n        ),\\n        StrInput(\\n            name=\\\"username\\\",\\n            display_name=\\\"HCD Username\\\",\\n            info=\\\"Authentication username for accessing HCD.\\\",\\n            value=\\\"hcd-superuser\\\",\\n            required=True,\\n        ),\\n        SecretStrInput(\\n            name=\\\"password\\\",\\n            display_name=\\\"HCD Password\\\",\\n            info=\\\"Authentication password for accessing HCD.\\\",\\n            value=\\\"HCD_PASSWORD\\\",\\n            required=True,\\n        ),\\n        SecretStrInput(\\n            name=\\\"api_endpoint\\\",\\n            display_name=\\\"HCD API Endpoint\\\",\\n            info=\\\"API endpoint URL for the HCD service.\\\",\\n            value=\\\"HCD_API_ENDPOINT\\\",\\n            required=True,\\n        ),\\n        *LCVectorStoreComponent.inputs,\\n        StrInput(\\n            name=\\\"namespace\\\",\\n            display_name=\\\"Namespace\\\",\\n            info=\\\"Optional namespace within HCD to use for the collection.\\\",\\n            value=\\\"default_namespace\\\",\\n            advanced=True,\\n        ),\\n        MultilineInput(\\n            name=\\\"ca_certificate\\\",\\n            display_name=\\\"CA Certificate\\\",\\n            info=\\\"Optional CA certificate for TLS connections to HCD.\\\",\\n            advanced=True,\\n        ),\\n        DropdownInput(\\n            name=\\\"metric\\\",\\n            display_name=\\\"Metric\\\",\\n            info=\\\"Optional distance metric for vector comparisons in the vector store.\\\",\\n            options=[\\\"cosine\\\", \\\"dot_product\\\", \\\"euclidean\\\"],\\n            advanced=True,\\n        ),\\n        IntInput(\\n            name=\\\"batch_size\\\",\\n            display_name=\\\"Batch Size\\\",\\n            info=\\\"Optional number of data to process in a single batch.\\\",\\n            advanced=True,\\n        ),\\n        IntInput(\\n            name=\\\"bulk_insert_batch_concurrency\\\",\\n            display_name=\\\"Bulk Insert Batch Concurrency\\\",\\n            info=\\\"Optional concurrency level for bulk insert operations.\\\",\\n            advanced=True,\\n        ),\\n        IntInput(\\n            name=\\\"bulk_insert_overwrite_concurrency\\\",\\n            display_name=\\\"Bulk Insert Overwrite Concurrency\\\",\\n            info=\\\"Optional concurrency level for bulk insert operations that overwrite existing data.\\\",\\n            advanced=True,\\n        ),\\n        IntInput(\\n            name=\\\"bulk_delete_concurrency\\\",\\n            display_name=\\\"Bulk Delete Concurrency\\\",\\n            info=\\\"Optional concurrency level for bulk delete operations.\\\",\\n            advanced=True,\\n        ),\\n        DropdownInput(\\n            name=\\\"setup_mode\\\",\\n            display_name=\\\"Setup Mode\\\",\\n            info=\\\"Configuration mode for setting up the vector store, with options like 'Sync', 'Async', or 'Off'.\\\",\\n            options=[\\\"Sync\\\", \\\"Async\\\", \\\"Off\\\"],\\n            advanced=True,\\n            value=\\\"Sync\\\",\\n        ),\\n        BoolInput(\\n            name=\\\"pre_delete_collection\\\",\\n            display_name=\\\"Pre Delete Collection\\\",\\n            info=\\\"Boolean flag to determine whether to delete the collection before creating a new one.\\\",\\n            advanced=True,\\n        ),\\n        StrInput(\\n            name=\\\"metadata_indexing_include\\\",\\n            display_name=\\\"Metadata Indexing Include\\\",\\n            info=\\\"Optional list of metadata fields to include in the indexing.\\\",\\n            advanced=True,\\n        ),\\n        HandleInput(\\n            name=\\\"embedding\\\",\\n            display_name=\\\"Embedding or Astra Vectorize\\\",\\n            input_types=[\\\"Embeddings\\\", \\\"dict\\\"],\\n            # TODO: This should be optional, but need to refactor langchain-astradb first.\\n            info=\\\"Allows either an embedding model or an Astra Vectorize configuration.\\\",\\n        ),\\n        StrInput(\\n            name=\\\"metadata_indexing_exclude\\\",\\n            display_name=\\\"Metadata Indexing Exclude\\\",\\n            info=\\\"Optional list of metadata fields to exclude from the indexing.\\\",\\n            advanced=True,\\n        ),\\n        StrInput(\\n            name=\\\"collection_indexing_policy\\\",\\n            display_name=\\\"Collection Indexing Policy\\\",\\n            info=\\\"Optional dictionary defining the indexing policy for the collection.\\\",\\n            advanced=True,\\n        ),\\n        IntInput(\\n            name=\\\"number_of_results\\\",\\n            display_name=\\\"Number of Results\\\",\\n            info=\\\"Number of results to return.\\\",\\n            advanced=True,\\n            value=4,\\n        ),\\n        DropdownInput(\\n            name=\\\"search_type\\\",\\n            display_name=\\\"Search Type\\\",\\n            info=\\\"Search type to use\\\",\\n            options=[\\n                \\\"Similarity\\\",\\n                \\\"Similarity with score threshold\\\",\\n                \\\"MMR (Max Marginal Relevance)\\\",\\n            ],\\n            value=\\\"Similarity\\\",\\n            advanced=True,\\n        ),\\n        FloatInput(\\n            name=\\\"search_score_threshold\\\",\\n            display_name=\\\"Search Score Threshold\\\",\\n            info=\\\"Minimum similarity score threshold for search results. \\\"\\n            \\\"(when using 'Similarity with score threshold')\\\",\\n            value=0,\\n            advanced=True,\\n        ),\\n        DictInput(\\n            name=\\\"search_filter\\\",\\n            display_name=\\\"Search Metadata Filter\\\",\\n            info=\\\"Optional dictionary of filters to apply to the search query.\\\",\\n            advanced=True,\\n            is_list=True,\\n        ),\\n    ]\\n\\n    @check_cached_vector_store\\n    def build_vector_store(self):\\n        # The HCD API endpoint is tenant-controlled and is dialed with the configured HCD\\n        # credentials; block internal/cloud-metadata hosts before the vector store is built.\\n        validate_api_endpoint(self.api_endpoint)\\n\\n        try:\\n            from langchain_astradb import AstraDBVectorStore\\n            from langchain_astradb.utils.astradb import SetupMode\\n        except ImportError as e:\\n            msg = (\\n                \\\"Could not import langchain Astra DB integration package. \\\"\\n                \\\"Please install it with `pip install langchain-astradb`.\\\"\\n            )\\n            raise ImportError(msg) from e\\n\\n        try:\\n            from astrapy.authentication import UsernamePasswordTokenProvider\\n            from astrapy.constants import Environment\\n        except ImportError as e:\\n            msg = \\\"Could not import astrapy integration package. Please install it with `pip install astrapy`.\\\"\\n            raise ImportError(msg) from e\\n\\n        try:\\n            if not self.setup_mode:\\n                self.setup_mode = self._inputs[\\\"setup_mode\\\"].options[0]\\n\\n            setup_mode_value = SetupMode[self.setup_mode.upper()]\\n        except KeyError as e:\\n            msg = f\\\"Invalid setup mode: {self.setup_mode}\\\"\\n            raise ValueError(msg) from e\\n\\n        if not isinstance(self.embedding, dict):\\n            embedding_dict = {\\\"embedding\\\": self.embedding}\\n        else:\\n            from astrapy.info import VectorServiceOptions\\n\\n            dict_options = self.embedding.get(\\\"collection_vector_service_options\\\", {})\\n            dict_options[\\\"authentication\\\"] = {\\n                k: v for k, v in dict_options.get(\\\"authentication\\\", {}).items() if k and v\\n            }\\n            dict_options[\\\"parameters\\\"] = {k: v for k, v in dict_options.get(\\\"parameters\\\", {}).items() if k and v}\\n            embedding_dict = {\\\"collection_vector_service_options\\\": VectorServiceOptions.from_dict(dict_options)}\\n            collection_embedding_api_key = self.embedding.get(\\\"collection_embedding_api_key\\\")\\n            if collection_embedding_api_key:\\n                embedding_dict[\\\"collection_embedding_api_key\\\"] = collection_embedding_api_key\\n\\n        token_provider = UsernamePasswordTokenProvider(self.username, self.password)\\n        vector_store_kwargs = {\\n            **embedding_dict,\\n            \\\"collection_name\\\": self.collection_name,\\n            \\\"token\\\": token_provider,\\n            \\\"api_endpoint\\\": self.api_endpoint,\\n            \\\"namespace\\\": self.namespace,\\n            \\\"metric\\\": self.metric or None,\\n            \\\"batch_size\\\": self.batch_size or None,\\n            \\\"bulk_insert_batch_concurrency\\\": self.bulk_insert_batch_concurrency or None,\\n            \\\"bulk_insert_overwrite_concurrency\\\": self.bulk_insert_overwrite_concurrency or None,\\n            \\\"bulk_delete_concurrency\\\": self.bulk_delete_concurrency or None,\\n            \\\"setup_mode\\\": setup_mode_value,\\n            \\\"pre_delete_collection\\\": self.pre_delete_collection or False,\\n            \\\"environment\\\": Environment.HCD,\\n        }\\n\\n        if self.metadata_indexing_include:\\n            vector_store_kwargs[\\\"metadata_indexing_include\\\"] = self.metadata_indexing_include\\n        elif self.metadata_indexing_exclude:\\n            vector_store_kwargs[\\\"metadata_indexing_exclude\\\"] = self.metadata_indexing_exclude\\n        elif self.collection_indexing_policy:\\n            vector_store_kwargs[\\\"collection_indexing_policy\\\"] = self.collection_indexing_policy\\n\\n        try:\\n            vector_store = AstraDBVectorStore(**vector_store_kwargs)\\n        except Exception as e:\\n            msg = f\\\"Error initializing AstraDBVectorStore: {e}\\\"\\n            raise ValueError(msg) from e\\n\\n        self._add_documents_to_vector_store(vector_store)\\n        return vector_store\\n\\n    def _add_documents_to_vector_store(self, vector_store) -> None:\\n        # Convert DataFrame to Data if needed using parent's method\\n        self.ingest_data = self._prepare_ingest_data()\\n\\n        documents = []\\n        for _input in self.ingest_data or []:\\n            if isinstance(_input, Data):\\n                documents.append(_input.to_lc_document())\\n            else:\\n                msg = \\\"Vector Store Inputs must be Data objects.\\\"\\n                raise TypeError(msg)\\n\\n        if documents:\\n            self.log(f\\\"Adding {len(documents)} documents to the Vector Store.\\\")\\n            try:\\n                vector_store.add_documents(documents)\\n            except Exception as e:\\n                msg = f\\\"Error adding documents to AstraDBVectorStore: {e}\\\"\\n                raise ValueError(msg) from e\\n        else:\\n            self.log(\\\"No documents to add to the Vector Store.\\\")\\n\\n    def _map_search_type(self) -> str:\\n        if self.search_type == \\\"Similarity with score threshold\\\":\\n            return \\\"similarity_score_threshold\\\"\\n        if self.search_type == \\\"MMR (Max Marginal Relevance)\\\":\\n            return \\\"mmr\\\"\\n        return \\\"similarity\\\"\\n\\n    def _build_search_args(self):\\n        args = {\\n            \\\"k\\\": self.number_of_results,\\n            \\\"score_threshold\\\": self.search_score_threshold,\\n        }\\n\\n        if self.search_filter:\\n            clean_filter = {k: v for k, v in self.search_filter.items() if k and v}\\n            if len(clean_filter) > 0:\\n                args[\\\"filter\\\"] = clean_filter\\n        return args\\n\\n    def search_documents(self) -> list[Data]:\\n        vector_store = self.build_vector_store()\\n\\n        self.log(f\\\"Search query: {self.search_query}\\\")\\n        self.log(f\\\"Search type: {self.search_type}\\\")\\n        self.log(f\\\"Number of results: {self.number_of_results}\\\")\\n\\n        if self.search_query and isinstance(self.search_query, str) and self.search_query.strip():\\n            try:\\n                search_type = self._map_search_type()\\n                search_args = self._build_search_args()\\n\\n                docs = vector_store.search(query=self.search_query, search_type=search_type, **search_args)\\n            except Exception as e:\\n                msg = f\\\"Error performing search in AstraDBVectorStore: {e}\\\"\\n                raise ValueError(msg) from e\\n\\n            self.log(f\\\"Retrieved documents: {len(docs)}\\\")\\n\\n            data = docs_to_data(docs)\\n            self.log(f\\\"Converted documents to data: {len(data)}\\\")\\n            self.status = data\\n            return data\\n        self.log(\\\"No search input provided. Skipping search.\\\")\\n        return []\\n\\n    def get_retriever_kwargs(self):\\n        search_args = self._build_search_args()\\n        return {\\n            \\\"search_type\\\": self._map_search_type(),\\n            \\\"search_kwargs\\\": search_args,\\n        }\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/datastax/src/lfx_datastax/extension.json\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"1b2c55459b7a241e0d45d17f76e7a348843dfaf837a24e78f3ba3716a855f88d\",\"content\":\"{\\n  \\\"$schema\\\": \\\"https://schemas.langflow.org/extension/v1.json\\\",\\n  \\\"id\\\": \\\"lfx-datastax\\\",\\n  \\\"version\\\": \\\"0.1.8\\\",\\n  \\\"name\\\": \\\"DataStax\\\",\\n  \\\"description\\\": \\\"DataStax component(s) as a standalone Langflow Extension Bundle.\\\",\\n  \\\"lfx\\\": {\\n    \\\"compat\\\": [\\\"1\\\"]\\n  },\\n  \\\"bundles\\\": [\\n    {\\n      \\\"name\\\": \\\"datastax\\\",\\n      \\\"path\\\": \\\"components/datastax\\\"\\n    },\\n    {\\n      \\\"name\\\": \\\"cassandra\\\",\\n      \\\"path\\\": \\\"components/cassandra\\\"\\n    }\\n  ]\\n}\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/datastax/tests/conftest.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e8c1c97326dd2bef23668924fd5787b34458acc383cc56e72435ce27bfa0ab79\",\"content\":\"\\\"\\\"\\\"Shared fixtures for the DataStax bundle tests.\\\"\\\"\\\"\\n\\nimport pytest\\n\\n# Placeholder hosts used by the offline unit tests. They do not resolve, so the connector SSRF\\n# guard on the Astra/HCD endpoint boundary would reject them before the mocked client is reached.\\n# Allowlisting them keeps the guard switched ON (blocked-host coverage lives in\\n# ``test_astradb_connector_ssrf.py``) while letting endpoint-agnostic tests use fake URLs.\\nPLACEHOLDER_ENDPOINT_HOSTS = (\\n    \\\"test.endpoint.com\\\",\\n    \\\"custom.endpoint.com\\\",\\n    \\\"x.apps.astra.datastax.com\\\",\\n)\\n\\n\\n@pytest.fixture\\ndef allow_placeholder_endpoints(monkeypatch):\\n    \\\"\\\"\\\"Allowlist the fake API endpoints used by tests that are not about SSRF.\\\"\\\"\\\"\\n    monkeypatch.setenv(\\\"LANGFLOW_SSRF_ALLOWED_HOSTS\\\", \\\",\\\".join(PLACEHOLDER_ENDPOINT_HOSTS))\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/datastax/tests/test_astradb_base_component.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"d0113236772ad6e7188f9673d19fd4553e7f476d9f656f194217c02d841654ae\",\"content\":\"from collections import defaultdict\\nfrom unittest.mock import AsyncMock, Mock, patch\\n\\nimport pytest\\n\\n# Assuming the component is imported from the module\\n# Adjust the import path as needed\\nfrom lfx_datastax.base import AstraDBBaseComponent\\n\\n\\n@pytest.fixture\\ndef mock_component():\\n    \\\"\\\"\\\"Create a mock AstraDBBaseComponent instance.\\\"\\\"\\\"\\n    component = AstraDBBaseComponent()\\n    component.token = \\\"test_token\\\"  # noqa: S105\\n    component.environment = \\\"prod\\\"\\n    component.database_name = \\\"test_db\\\"\\n    component.api_endpoint = None\\n    component.keyspace = None\\n    component.collection_name = \\\"test_collection\\\"\\n    component.log = Mock()\\n    return component\\n\\n\\n@pytest.fixture\\ndef mock_database_info():\\n    \\\"\\\"\\\"Mock database information structure.\\\"\\\"\\\"\\n    return {\\n        \\\"test_db\\\": {\\n            \\\"api_endpoints\\\": [\\\"https://test-db-id.apps.astra.datastax.com\\\"],\\n            \\\"keyspaces\\\": [\\\"default_keyspace\\\", \\\"custom_keyspace\\\"],\\n            \\\"collections\\\": 5,\\n            \\\"status\\\": \\\"ACTIVE\\\",\\n            \\\"org_id\\\": \\\"test-org-id\\\",\\n        },\\n        \\\"pending_db\\\": {\\n            \\\"api_endpoints\\\": [\\\"https://pending-db-id.apps.astra.datastax.com\\\"],\\n            \\\"keyspaces\\\": [\\\"default_keyspace\\\"],\\n            \\\"collections\\\": 0,\\n            \\\"status\\\": \\\"PENDING\\\",\\n            \\\"org_id\\\": \\\"test-org-id\\\",\\n        },\\n    }\\n\\n\\n@pytest.fixture\\ndef mock_build_config():\\n    \\\"\\\"\\\"Mock build configuration structure.\\\"\\\"\\\"\\n    return {\\n        \\\"token\\\": {\\\"value\\\": \\\"test_token\\\"},\\n        \\\"environment\\\": {\\\"value\\\": \\\"prod\\\"},\\n        \\\"database_name\\\": {\\n            \\\"value\\\": \\\"test_db\\\",\\n            \\\"options\\\": [],\\n            \\\"options_metadata\\\": [],\\n            \\\"show\\\": False,\\n            \\\"dialog_inputs\\\": {\\n                \\\"fields\\\": {\\n                    \\\"data\\\": {\\n                        \\\"node\\\": {\\n                            \\\"template\\\": {\\n                                \\\"02_cloud_provider\\\": {\\\"options\\\": []},\\n                                \\\"03_region\\\": {\\\"options\\\": [], \\\"value\\\": None},\\n                            }\\n                        }\\n                    }\\n                }\\n            },\\n        },\\n        \\\"api_endpoint\\\": {\\\"value\\\": \\\"\\\", \\\"options\\\": []},\\n        \\\"keyspace\\\": {\\\"value\\\": \\\"\\\", \\\"options\\\": []},\\n        \\\"collection_name\\\": {\\n            \\\"value\\\": \\\"\\\",\\n            \\\"options\\\": [],\\n            \\\"options_metadata\\\": [],\\n            \\\"show\\\": False,\\n            \\\"dialog_inputs\\\": {\\n                \\\"fields\\\": {\\n                    \\\"data\\\": {\\n                        \\\"node\\\": {\\n                            \\\"template\\\": {\\n                                \\\"01_new_collection_name\\\": {},\\n                                \\\"02_embedding_generation_provider\\\": {\\n                                    \\\"value\\\": None,\\n                                    \\\"options\\\": [],\\n                                    \\\"options_metadata\\\": [],\\n                                    \\\"helper_text\\\": \\\"\\\",\\n                                },\\n                                \\\"03_embedding_generation_model\\\": {\\n                                    \\\"options\\\": [],\\n                                    \\\"placeholder\\\": None,\\n                                    \\\"readonly\\\": False,\\n                                    \\\"required\\\": True,\\n                                    \\\"value\\\": None,\\n                                },\\n                                \\\"04_dimension\\\": {\\n                                    \\\"placeholder\\\": None,\\n                                    \\\"value\\\": None,\\n                                    \\\"readonly\\\": False,\\n                                    \\\"required\\\": False,\\n                                },\\n                            }\\n                        }\\n                    }\\n                }\\n            },\\n        },\\n        \\\"embedding_model\\\": {\\\"show\\\": True, \\\"required\\\": False},\\n        \\\"autodetect_collection\\\": {\\\"value\\\": True},\\n        \\\"search_method\\\": {\\\"value\\\": \\\"Vector Search\\\", \\\"show\\\": False, \\\"options\\\": []},\\n        \\\"search_type\\\": {\\\"value\\\": \\\"Similarity\\\", \\\"show\\\": True},\\n        \\\"search_score_threshold\\\": {\\\"show\\\": True},\\n        \\\"reranker\\\": {\\n            \\\"value\\\": \\\"\\\",\\n            \\\"options\\\": [],\\n            \\\"options_metadata\\\": [],\\n            \\\"show\\\": False,\\n            \\\"toggle_disable\\\": False,\\n            \\\"toggle_value\\\": True,\\n        },\\n        \\\"lexical_terms\\\": {\\\"value\\\": \\\"\\\", \\\"show\\\": False},\\n    }\\n\\n\\nclass TestCloudProviderMapping:\\n    \\\"\\\"\\\"Tests for cloud provider mapping.\\\"\\\"\\\"\\n\\n    @patch(\\\"lfx_datastax.base.astradb_base.DataAPIClient\\\")\\n    def test_map_cloud_providers_structure(self, mock_client_class):\\n        \\\"\\\"\\\"Test that map_cloud_providers returns correct structure.\\\"\\\"\\\"\\n        # Mock the admin client and its methods\\n        mock_admin = Mock()\\n        # Mock find_available_regions to return a list of region objects\\n        mock_region1 = Mock()\\n        mock_region1.cloud_provider = \\\"AWS\\\"\\n        mock_region1.name = \\\"us-east-2\\\"\\n        mock_region2 = Mock()\\n        mock_region2.cloud_provider = \\\"GCP\\\"\\n        mock_region2.name = \\\"us-central1\\\"\\n        mock_region3 = Mock()\\n        mock_region3.cloud_provider = \\\"Azure\\\"\\n        mock_region3.name = \\\"eastus\\\"\\n\\n        mock_admin.find_available_regions.return_value = [\\n            mock_region1,\\n            mock_region2,\\n            mock_region3,\\n        ]\\n\\n        mock_client = mock_client_class.return_value\\n        mock_client.get_admin.return_value = mock_admin\\n\\n        providers = AstraDBBaseComponent.map_cloud_providers(token=\\\"test_token\\\")  # noqa: S106\\n\\n        assert \\\"Amazon Web Services\\\" in providers\\n        assert \\\"Google Cloud Platform\\\" in providers\\n        assert \\\"Microsoft Azure\\\" in providers\\n\\n    @patch(\\\"lfx_datastax.base.astradb_base.DataAPIClient\\\")\\n    def test_map_cloud_providers_prod_content(self, mock_client_class):\\n        \\\"\\\"\\\"Test production environment cloud providers.\\\"\\\"\\\"\\n        # Mock the admin client and its methods\\n        mock_admin = Mock()\\n        # Mock find_available_regions to return a list of region objects\\n        mock_region1 = Mock()\\n        mock_region1.cloud_provider = \\\"AWS\\\"\\n        mock_region1.name = \\\"us-east-2\\\"\\n        mock_region2 = Mock()\\n        mock_region2.cloud_provider = \\\"AWS\\\"\\n        mock_region2.name = \\\"us-west-2\\\"\\n        mock_region3 = Mock()\\n        mock_region3.cloud_provider = \\\"GCP\\\"\\n        mock_region3.name = \\\"us-central1\\\"\\n        mock_region4 = Mock()\\n        mock_region4.cloud_provider = \\\"Azure\\\"\\n        mock_region4.name = \\\"eastus\\\"\\n\\n        mock_admin.find_available_regions.return_value = [\\n            mock_region1,\\n            mock_region2,\\n            mock_region3,\\n            mock_region4,\\n        ]\\n\\n        mock_client = mock_client_class.return_value\\n        mock_client.get_admin.return_value = mock_admin\\n\\n        providers = AstraDBBaseComponent.map_cloud_providers(token=\\\"test_token\\\")  # noqa: S106\\n\\n        assert \\\"Amazon Web Services\\\" in providers\\n        assert \\\"Google Cloud Platform\\\" in providers\\n        assert \\\"Microsoft Azure\\\" in providers\\n\\n        assert providers[\\\"Amazon Web Services\\\"][\\\"id\\\"] == \\\"aws\\\"\\n        assert \\\"us-east-2\\\" in providers[\\\"Amazon Web Services\\\"][\\\"regions\\\"]\\n        assert \\\"us-west-2\\\" in providers[\\\"Amazon Web Services\\\"][\\\"regions\\\"]\\n\\n    @patch(\\\"lfx_datastax.base.astradb_base.DataAPIClient\\\")\\n    def test_map_cloud_providers_dev_content(self, mock_client_class):\\n        \\\"\\\"\\\"Test development environment cloud providers.\\\"\\\"\\\"\\n        # Mock the admin client and its methods\\n        mock_admin = Mock()\\n        # Mock find_available_regions to return a list of region objects\\n        mock_region1 = Mock()\\n        mock_region1.cloud_provider = \\\"AWS\\\"\\n        mock_region1.name = \\\"us-east-2\\\"\\n        mock_region2 = Mock()\\n        mock_region2.cloud_provider = \\\"GCP\\\"\\n        mock_region2.name = \\\"us-central1\\\"\\n\\n        mock_admin.find_available_regions.return_value = [mock_region1, mock_region2]\\n\\n        mock_client = mock_client_class.return_value\\n        mock_client.get_admin.return_value = mock_admin\\n\\n        providers = AstraDBBaseComponent.map_cloud_providers(token=\\\"test_token\\\")  # noqa: S106\\n\\n        assert \\\"Amazon Web Services\\\" in providers\\n        assert \\\"Google Cloud Platform\\\" in providers\\n        assert providers[\\\"Amazon Web Services\\\"][\\\"id\\\"] == \\\"aws\\\"\\n\\n\\nclass TestDatabaseIdExtraction:\\n    \\\"\\\"\\\"Tests for database ID extraction from API endpoints.\\\"\\\"\\\"\\n\\n    def test_get_database_id_static_valid_uuid(self):\\n        \\\"\\\"\\\"Test extracting valid UUID from API endpoint.\\\"\\\"\\\"\\n        api_endpoint = \\\"https://12345678-1234-1234-1234-123456789abc.apps.astra.datastax.com\\\"\\n        db_id = AstraDBBaseComponent.get_database_id_static(api_endpoint)\\n\\n        assert db_id == \\\"12345678-1234-1234-1234-123456789abc\\\"\\n\\n    def test_get_database_id_static_no_uuid(self):\\n        \\\"\\\"\\\"Test extraction returns None when no UUID present.\\\"\\\"\\\"\\n        api_endpoint = \\\"https://invalid.endpoint.com\\\"\\n        db_id = AstraDBBaseComponent.get_database_id_static(api_endpoint)\\n\\n        assert db_id is None\\n\\n    def test_get_database_id_static_case_insensitive(self):\\n        \\\"\\\"\\\"Test UUID extraction is case insensitive.\\\"\\\"\\\"\\n        api_endpoint = \\\"https://ABCDEF12-ABCD-ABCD-ABCD-ABCDEFABCDEF.apps.astra.datastax.com\\\"\\n        db_id = AstraDBBaseComponent.get_database_id_static(api_endpoint)\\n\\n        assert db_id == \\\"ABCDEF12-ABCD-ABCD-ABCD-ABCDEFABCDEF\\\"\\n\\n    def test_get_database_id_instance_method(self, mock_component):\\n        \\\"\\\"\\\"Test instance method for getting database ID.\\\"\\\"\\\"\\n        with patch.object(\\n            mock_component,\\n            \\\"get_api_endpoint\\\",\\n            return_value=\\\"https://12345678-1234-1234-1234-123456789abc.apps.astra.datastax.com\\\",\\n        ):\\n            db_id = mock_component.get_database_id()\\n            assert db_id == \\\"12345678-1234-1234-1234-123456789abc\\\"\\n\\n\\nclass TestKeyspaceHandling:\\n    \\\"\\\"\\\"Tests for keyspace handling.\\\"\\\"\\\"\\n\\n    def test_get_keyspace_default(self, mock_component):\\n        \\\"\\\"\\\"Test getting default keyspace when none set.\\\"\\\"\\\"\\n        mock_component.keyspace = None\\n        assert mock_component.get_keyspace() == \\\"default_keyspace\\\"\\n\\n    def test_get_keyspace_with_value(self, mock_component):\\n        \\\"\\\"\\\"Test getting keyspace when value is set.\\\"\\\"\\\"\\n        mock_component.keyspace = \\\"custom_keyspace\\\"\\n        assert mock_component.get_keyspace() == \\\"custom_keyspace\\\"\\n\\n    def test_get_keyspace_with_empty_string(self, mock_component):\\n        \\\"\\\"\\\"Test getting keyspace with empty string returns default.\\\"\\\"\\\"\\n        mock_component.keyspace = \\\"\\\"\\n        assert mock_component.get_keyspace() == \\\"default_keyspace\\\"\\n\\n\\nclass TestCollectionDataRetrieval:\\n    \\\"\\\"\\\"Tests for collection data retrieval.\\\"\\\"\\\"\\n\\n    def test_collection_data_success(self, mock_component):\\n        \\\"\\\"\\\"Test successful collection data retrieval.\\\"\\\"\\\"\\n        mock_database = Mock()\\n        mock_collection = Mock()\\n        mock_collection.estimated_document_count.return_value = 100\\n        mock_database.get_collection.return_value = mock_collection\\n\\n        count = mock_component.collection_data(\\\"test_collection\\\", database=mock_database)\\n        assert count == 100\\n        mock_database.get_collection.assert_called_once_with(\\\"test_collection\\\")\\n        mock_collection.estimated_document_count.assert_called_once()\\n\\n    def test_collection_data_with_provided_database(self, mock_component):\\n        \\\"\\\"\\\"Test collection data retrieval with provided database object.\\\"\\\"\\\"\\n        mock_database = Mock()\\n        mock_collection = Mock()\\n        mock_collection.estimated_document_count.return_value = 50\\n\\n        mock_database.get_collection.return_value = mock_collection\\n\\n        count = mock_component.collection_data(\\\"test_collection\\\", database=mock_database)\\n        assert count == 50\\n\\n    def test_collection_data_error_handling(self, mock_component):\\n        \\\"\\\"\\\"Test collection data error handling.\\\"\\\"\\\"\\n        mock_database = Mock()\\n        mock_database.get_collection.side_effect = Exception(\\\"Connection error\\\")\\n\\n        result = mock_component.collection_data(\\\"test_collection\\\", database=mock_database)\\n        assert result is None\\n        mock_component.log.assert_called_once()\\n\\n\\nclass TestDatabaseCreation:\\n    \\\"\\\"\\\"Tests for database creation.\\\"\\\"\\\"\\n\\n    @pytest.mark.asyncio\\n    @patch(\\\"lfx_datastax.base.astradb_base.DataAPIClient\\\")\\n    async def test_create_database_api_success(self, mock_client_class):\\n        \\\"\\\"\\\"Test successful database creation.\\\"\\\"\\\"\\n        mock_admin = Mock()\\n        # Fix: Make async_create_database return a proper awaitable that yields a dict\\n        mock_admin.async_create_database = AsyncMock(return_value={\\\"id\\\": \\\"new-db-id\\\"})\\n\\n        # Mock find_available_regions to return a list of region objects\\n        mock_region = Mock()\\n        mock_region.cloud_provider = \\\"AWS\\\"\\n        mock_region.name = \\\"us-east-2\\\"\\n        mock_admin.find_available_regions.return_value = [mock_region]\\n\\n        mock_client = mock_client_class.return_value\\n        mock_client.get_admin.return_value = mock_admin\\n\\n        result = await AstraDBBaseComponent.create_database_api(\\n            new_database_name=\\\"new_db\\\",\\n            cloud_provider=\\\"Amazon Web Services\\\",\\n            region=\\\"us-east-2\\\",\\n            token=\\\"test_token\\\",  # noqa: S106\\n            environment=\\\"prod\\\",\\n        )\\n\\n        assert result == {\\\"id\\\": \\\"new-db-id\\\"}\\n        mock_admin.async_create_database.assert_called_once()\\n\\n\\n@pytest.mark.usefixtures(\\\"allow_placeholder_endpoints\\\")\\nclass TestCollectionCreation:\\n    \\\"\\\"\\\"Tests for collection creation.\\\"\\\"\\\"\\n\\n    @pytest.mark.asyncio\\n    @patch(\\\"lfx_datastax.base.astradb_base._AstraDBCollectionEnvironment\\\")\\n    @patch.object(AstraDBBaseComponent, \\\"get_vectorize_providers\\\")\\n    async def test_create_collection_api_with_vectorize(self, mock_get_providers, mock_env_class):\\n        \\\"\\\"\\\"Test collection creation with vectorize options.\\\"\\\"\\\"\\n        mock_get_providers.return_value = defaultdict(\\n            list,\\n            {\\n                \\\"NVIDIA\\\": [\\\"nvidia\\\", [\\\"model1\\\", \\\"model2\\\"]],\\n            },\\n        )\\n\\n        await AstraDBBaseComponent.create_collection_api(\\n            new_collection_name=\\\"new_collection\\\",\\n            token=\\\"test_token\\\",  # noqa: S106\\n            api_endpoint=\\\"https://test.endpoint.com\\\",\\n            keyspace=\\\"default_keyspace\\\",\\n            embedding_generation_provider=\\\"NVIDIA\\\",\\n            embedding_generation_model=\\\"model1\\\",\\n        )\\n\\n        mock_env_class.assert_called_once()\\n        call_kwargs = mock_env_class.call_args[1]\\n        assert call_kwargs[\\\"collection_name\\\"] == \\\"new_collection\\\"\\n        assert call_kwargs[\\\"collection_vector_service_options\\\"] is not None\\n\\n    @pytest.mark.asyncio\\n    @patch(\\\"lfx_datastax.base.astradb_base._AstraDBCollectionEnvironment\\\")\\n    async def test_create_collection_api_with_dimension(self, mock_env_class):\\n        \\\"\\\"\\\"Test collection creation with explicit dimension.\\\"\\\"\\\"\\n        await AstraDBBaseComponent.create_collection_api(\\n            new_collection_name=\\\"new_collection\\\",\\n            token=\\\"test_token\\\",  # noqa: S106\\n            api_endpoint=\\\"https://test.endpoint.com\\\",\\n            dimension=1536,\\n            keyspace=\\\"default_keyspace\\\",\\n        )\\n\\n        mock_env_class.assert_called_once()\\n        call_kwargs = mock_env_class.call_args[1]\\n        assert call_kwargs[\\\"embedding_dimension\\\"] == 1536\\n        assert call_kwargs[\\\"collection_vector_service_options\\\"] is None\\n\\n    @pytest.mark.asyncio\\n    async def test_create_collection_api_no_name(self):\\n        \\\"\\\"\\\"Test collection creation fails without name.\\\"\\\"\\\"\\n        with pytest.raises(ValueError, match=\\\"Collection name is required\\\"):\\n            await AstraDBBaseComponent.create_collection_api(\\n                new_collection_name=\\\"\\\",\\n                token=\\\"test_token\\\",  # noqa: S106\\n                api_endpoint=\\\"https://test.endpoint.com\\\",\\n                keyspace=\\\"default_keyspace\\\",\\n            )\\n\\n\\nclass TestUpdateBuildConfig:\\n    \\\"\\\"\\\"Tests for update_build_config method.\\\"\\\"\\\"\\n\\n    @pytest.mark.asyncio\\n    async def test_update_build_config_no_token(self, mock_component, mock_build_config):\\n        \\\"\\\"\\\"Test update_build_config with no token resets config.\\\"\\\"\\\"\\n        mock_component.token = None\\n        result = await mock_component.update_build_config(mock_build_config, \\\"\\\", \\\"database_name\\\")\\n\\n        assert result[\\\"database_name\\\"][\\\"options\\\"] == []\\n        assert result[\\\"database_name\\\"][\\\"show\\\"] is False\\n\\n    @pytest.mark.asyncio\\n    @patch.object(AstraDBBaseComponent, \\\"_initialize_database_options\\\")\\n    @patch.object(AstraDBBaseComponent, \\\"map_cloud_providers\\\")\\n    async def test_update_build_config_first_run(\\n        self, mock_map_providers, mock_init_db, mock_component, mock_build_config\\n    ):\\n        \\\"\\\"\\\"Test update_build_config on first run.\\\"\\\"\\\"\\n        # Mock the cloud providers mapping to avoid API calls\\n        mock_map_providers.return_value = {\\n            \\\"prod\\\": {\\n                \\\"Amazon Web Services\\\": {\\n                    \\\"id\\\": \\\"aws\\\",\\n                    \\\"regions\\\": [\\\"us-east-2\\\", \\\"us-west-2\\\"],\\n                }\\n            },\\n            \\\"dev\\\": {},\\n            \\\"test\\\": {},\\n        }\\n\\n        mock_init_db.return_value = [\\n            {\\n                \\\"name\\\": \\\"db1\\\",\\n                \\\"status\\\": None,\\n                \\\"collections\\\": 5,\\n                \\\"api_endpoints\\\": [\\\"https://db1.endpoint.com\\\"],\\n                \\\"keyspaces\\\": [\\\"default_keyspace\\\"],\\n                \\\"org_id\\\": \\\"org-id\\\",\\n            }\\n        ]\\n\\n        result = await mock_component.update_build_config(mock_build_config, \\\"\\\", \\\"embedding_model\\\")\\n\\n        assert \\\"db1\\\" in result[\\\"database_name\\\"][\\\"options\\\"]\\n        mock_init_db.assert_called_once()\\n\\n    @pytest.mark.asyncio\\n    async def test_update_build_config_search_method_change_to_hybrid(self, mock_component, mock_build_config):\\n        \\\"\\\"\\\"Test base update_build_config doesn't handle search_method.\\\"\\\"\\\"\\n        # The base AstraDBBaseComponent doesn't handle search_method changes\\n        # This functionality is in the AstraDBVectorStoreComponent subclass\\n        result = await mock_component.update_build_config(mock_build_config, \\\"Hybrid Search\\\", \\\"search_method\\\")\\n\\n        # Base component should return config unchanged for search_method\\n        assert result[\\\"lexical_terms\\\"][\\\"show\\\"] is False  # Default value from fixture\\n        assert result[\\\"reranker\\\"][\\\"show\\\"] is False  # Default value from fixture\\n\\n\\n@pytest.mark.usefixtures(\\\"allow_placeholder_endpoints\\\")\\nclass TestGetDatabaseObject:\\n    \\\"\\\"\\\"Tests for getting database object.\\\"\\\"\\\"\\n\\n    @patch(\\\"lfx_datastax.base.astradb_base.DataAPIClient\\\")\\n    def test_get_database_object_success(self, mock_client_class, mock_component):\\n        \\\"\\\"\\\"Test successful database object retrieval.\\\"\\\"\\\"\\n        mock_database = Mock()\\n        mock_client = mock_client_class.return_value\\n        mock_client.get_database.return_value = mock_database\\n\\n        with (\\n            patch.object(\\n                mock_component,\\n                \\\"get_api_endpoint\\\",\\n                return_value=\\\"https://test.endpoint.com\\\",\\n            ),\\n            patch.object(mock_component, \\\"get_keyspace\\\", return_value=\\\"default_keyspace\\\"),\\n        ):\\n            db = mock_component.get_database_object()\\n            assert db == mock_database\\n\\n    @patch(\\\"lfx_datastax.base.astradb_base.DataAPIClient\\\")\\n    def test_get_database_object_with_custom_endpoint(self, mock_client_class, mock_component):\\n        \\\"\\\"\\\"Test database object retrieval with custom endpoint.\\\"\\\"\\\"\\n        mock_database = Mock()\\n        mock_client = mock_client_class.return_value\\n        mock_client.get_database.return_value = mock_database\\n\\n        with patch.object(mock_component, \\\"get_keyspace\\\", return_value=\\\"default_keyspace\\\"):\\n            db = mock_component.get_database_object(api_endpoint=\\\"https://custom.endpoint.com\\\")\\n            assert db == mock_database\\n\\n    @patch(\\\"lfx_datastax.base.astradb_base.DataAPIClient\\\")\\n    def test_get_database_object_error(self, mock_client_class, mock_component):\\n        \\\"\\\"\\\"Test database object retrieval error handling.\\\"\\\"\\\"\\n        mock_client_class.side_effect = Exception(\\\"Connection error\\\")\\n\\n        with (\\n            patch.object(\\n                mock_component,\\n                \\\"get_api_endpoint\\\",\\n                return_value=\\\"https://test.endpoint.com\\\",\\n            ),\\n            pytest.raises(ValueError, match=\\\"Error fetching database object\\\"),\\n        ):\\n            mock_component.get_database_object()\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    pytest.main([__file__, \\\"-v\\\"])\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/datastax/tests/test_astradb_connector_ssrf.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"3cc6a2c52bdd42a85cafaf35babe1b3a0ed645a3eb5b4b864e3f0c62d1794e24\",\"content\":\"\\\"\\\"\\\"SSRF-block regression tests for the DataStax Data API connector path.\\n\\n``api_endpoint`` (and a ``https://``-prefixed ``database_name``) are tenant-controlled fields on\\nevery AstraDB / HCD component, and the resolved URL is handed to the astrapy client together with\\nthe configured Astra application token. These tests prove the shared connector SSRF guard now runs\\nat the endpoint-resolution boundary in :class:`AstraDBBaseComponent`, so a blocked destination is\\nrejected BEFORE any client is constructed and before the token can leave the process.\\n\\nOnly the settings service (to pin SSRF protection on) and the network sink (as a sentinel asserted\\nnever to be reached) are mocked -- the real SSRF validation logic runs.\\n\\nThe sibling ``astradb_cql`` REST path already had this guard; see\\n``lfx/tests/unit/utils/test_ssrf_protection.py`` for the validator's own coverage.\\n\\\"\\\"\\\"\\n\\nfrom contextlib import contextmanager\\nfrom unittest.mock import MagicMock, patch\\n\\nimport pytest\\n\\npytest.importorskip(\\\"lfx_datastax\\\")\\n\\n# 169.254.169.254 (cloud metadata) and 10.0.0.5 (RFC1918) are blocked regardless of\\n# ``connector_ssrf_allow_loopback``, which defaults to True and would exempt 127.0.0.1.\\nMETADATA_ENDPOINT = \\\"http://169.254.169.254\\\"\\nPRIVATE_ENDPOINT = \\\"https://10.0.0.5:8080\\\"\\nPUBLIC_ENDPOINT = \\\"https://db-id-1234.apps.astra.datastax.com\\\"\\nFAKE_TOKEN = \\\"AstraCS:regression-test-token\\\"  # pragma: allowlist secret\\n\\n\\n@contextmanager\\ndef ssrf_enabled(allowed_hosts: list[str] | None = None):\\n    \\\"\\\"\\\"Enable global and connector SSRF protection.\\\"\\\"\\\"\\n    with patch(\\\"lfx.utils.ssrf_protection.get_settings_service\\\") as mock_get:\\n        s = MagicMock()\\n        s.settings.ssrf_protection_enabled = True\\n        s.settings.connector_ssrf_validation_enabled = True\\n        s.settings.connector_ssrf_allow_loopback = True\\n        s.settings.ssrf_allowed_hosts = allowed_hosts or []\\n        s.settings.restrict_local_file_access = False\\n        mock_get.return_value = s\\n        yield\\n\\n\\ndef _component(**attrs):\\n    from lfx_datastax.base import AstraDBBaseComponent\\n\\n    component = AstraDBBaseComponent()\\n    component.token = FAKE_TOKEN\\n    component.environment = \\\"prod\\\"\\n    component.database_name = None\\n    component.api_endpoint = None\\n    component.keyspace = \\\"default_keyspace\\\"\\n    component.log = MagicMock()\\n    for key, value in attrs.items():\\n        setattr(component, key, value)\\n    return component\\n\\n\\n@pytest.mark.parametrize(\\\"blocked\\\", [METADATA_ENDPOINT, PRIVATE_ENDPOINT])\\ndef test_get_api_endpoint_blocks_internal_host(blocked):\\n    \\\"\\\"\\\"The advanced ``api_endpoint`` field cannot resolve to a guard-blocked host.\\\"\\\"\\\"\\n    from lfx.utils.ssrf_protection import SSRFProtectionError\\n\\n    component = _component(api_endpoint=blocked, database_name=\\\"ignored\\\")\\n    with ssrf_enabled(), pytest.raises(SSRFProtectionError):\\n        component.get_api_endpoint()\\n\\n\\n@pytest.mark.parametrize(\\\"blocked\\\", [\\\"https://169.254.169.254\\\", \\\"https://10.0.0.5:8080\\\"])\\ndef test_get_api_endpoint_blocks_url_shaped_database_name(blocked):\\n    \\\"\\\"\\\"A ``https://``-prefixed ``database_name`` is the same tenant-controlled sink.\\\"\\\"\\\"\\n    from lfx.utils.ssrf_protection import SSRFProtectionError\\n\\n    component = _component(database_name=blocked)\\n    with ssrf_enabled(), pytest.raises(SSRFProtectionError):\\n        component.get_api_endpoint()\\n\\n\\ndef test_get_database_object_blocks_before_client_is_built():\\n    \\\"\\\"\\\"No astrapy client is constructed -- so the Astra token never leaves the process.\\\"\\\"\\\"\\n    from lfx.utils.ssrf_protection import SSRFProtectionError\\n\\n    component = _component(api_endpoint=METADATA_ENDPOINT)\\n    with (\\n        ssrf_enabled(),\\n        patch(\\\"lfx_datastax.base.astradb_base.DataAPIClient\\\") as mock_client,\\n        pytest.raises(SSRFProtectionError),\\n    ):\\n        component.get_database_object()\\n    assert mock_client.call_count == 0\\n\\n\\ndef test_get_database_object_blocks_explicit_api_endpoint_argument():\\n    \\\"\\\"\\\"``get_database_object(api_endpoint=...)`` is fed build_config values, so guard it too.\\\"\\\"\\\"\\n    from lfx.utils.ssrf_protection import SSRFProtectionError\\n\\n    component = _component(api_endpoint=PUBLIC_ENDPOINT)\\n    with (\\n        ssrf_enabled(),\\n        patch(\\\"lfx_datastax.base.astradb_base.DataAPIClient\\\") as mock_client,\\n        pytest.raises(SSRFProtectionError),\\n    ):\\n        component.get_database_object(api_endpoint=PRIVATE_ENDPOINT)\\n    assert mock_client.call_count == 0\\n\\n\\ndef test_collection_data_blocks_before_client_is_built():\\n    \\\"\\\"\\\"``collection_data`` builds its own client from the resolved endpoint.\\\"\\\"\\\"\\n    from lfx.utils.ssrf_protection import SSRFProtectionError\\n\\n    component = _component(api_endpoint=METADATA_ENDPOINT)\\n    with (\\n        ssrf_enabled(),\\n        patch(\\\"lfx_datastax.base.astradb_base.DataAPIClient\\\") as mock_client,\\n        pytest.raises(SSRFProtectionError),\\n    ):\\n        component.collection_data(collection_name=\\\"col\\\")\\n    assert mock_client.call_count == 0\\n\\n\\ndef test_get_vectorize_providers_blocks_before_admin_client_is_built():\\n    from lfx.utils.ssrf_protection import SSRFProtectionError\\n    from lfx_datastax.base import AstraDBBaseComponent\\n\\n    with (\\n        ssrf_enabled(),\\n        patch(\\\"lfx_datastax.base.astradb_base.DataAPIClient\\\") as mock_client,\\n        pytest.raises(SSRFProtectionError),\\n    ):\\n        AstraDBBaseComponent.get_vectorize_providers(\\n            token=FAKE_TOKEN, environment=\\\"prod\\\", api_endpoint=METADATA_ENDPOINT\\n        )\\n    assert mock_client.call_count == 0\\n\\n\\nasync def test_create_collection_api_blocks_before_environment_is_built():\\n    from lfx.utils.ssrf_protection import SSRFProtectionError\\n    from lfx_datastax.base import AstraDBBaseComponent\\n\\n    with (\\n        ssrf_enabled(),\\n        patch(\\\"lfx_datastax.base.astradb_base._AstraDBCollectionEnvironment\\\") as mock_env,\\n        pytest.raises(SSRFProtectionError),\\n    ):\\n        await AstraDBBaseComponent.create_collection_api(\\n            new_collection_name=\\\"col\\\",\\n            token=FAKE_TOKEN,\\n            api_endpoint=METADATA_ENDPOINT,\\n            environment=\\\"prod\\\",\\n            dimension=4,\\n        )\\n    assert mock_env.call_count == 0\\n\\n\\nasync def test_data_api_create_collection_override_blocks_before_client_is_built():\\n    from lfx.utils.ssrf_protection import SSRFProtectionError\\n    from lfx_datastax.components.datastax.astradb_data_api import AstraDBDataAPIComponent\\n\\n    with (\\n        ssrf_enabled(),\\n        patch(\\\"lfx_datastax.components.datastax.astradb_data_api.DataAPIClient\\\") as mock_client,\\n        pytest.raises(SSRFProtectionError),\\n    ):\\n        await AstraDBDataAPIComponent.create_collection_api(\\n            new_collection_name=\\\"col\\\",\\n            token=FAKE_TOKEN,\\n            api_endpoint=METADATA_ENDPOINT,\\n            environment=\\\"prod\\\",\\n            dimension=4,\\n        )\\n    assert mock_client.call_count == 0\\n\\n\\ndef test_hcd_vector_store_blocks_internal_api_endpoint():\\n    \\\"\\\"\\\"HCD takes a free-form API endpoint and forwards it plus credentials to astrapy.\\\"\\\"\\\"\\n    from lfx.utils.ssrf_protection import SSRFProtectionError\\n    from lfx_datastax.components.datastax.hcd import HCDVectorStoreComponent\\n\\n    component = HCDVectorStoreComponent()\\n    component.collection_name = \\\"col\\\"\\n    component.username = \\\"hcd-superuser\\\"\\n    component.password = \\\"hcd-password\\\"  # noqa: S105  # pragma: allowlist secret\\n    component.api_endpoint = METADATA_ENDPOINT\\n    component.namespace = None\\n    component.ca_certificate = None\\n    component.embedding = MagicMock()\\n    component.ingest_data = []\\n    component.log = MagicMock()\\n\\n    with ssrf_enabled(), pytest.raises(SSRFProtectionError):\\n        component.build_vector_store()\\n\\n\\ndef test_allowlisted_endpoint_still_resolves():\\n    \\\"\\\"\\\"The documented escape hatch keeps private-network Astra/HCD deployments working.\\n\\n    Uses the allowlist rather than a live public host so the assertion needs no DNS.\\n    \\\"\\\"\\\"\\n    component = _component(api_endpoint=PUBLIC_ENDPOINT)\\n    with ssrf_enabled(allowed_hosts=[\\\"*.apps.astra.datastax.com\\\"]):\\n        assert component.get_api_endpoint() == PUBLIC_ENDPOINT\\n\\n    component = _component(api_endpoint=PRIVATE_ENDPOINT)\\n    with ssrf_enabled(allowed_hosts=[\\\"10.0.0.0/8\\\"]):\\n        assert component.get_api_endpoint() == PRIVATE_ENDPOINT\\n\\n\\ndef test_no_endpoint_configured_still_returns_none():\\n    \\\"\\\"\\\"An unset endpoint must stay a no-op rather than raising out of build_config paths.\\\"\\\"\\\"\\n    component = _component()\\n    with ssrf_enabled():\\n        assert component.get_api_endpoint() is None\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/datastax/tests/test_astradb_data_api_component.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"28ca1ca5adb4f6a801b2593c55b9008c69421e886785da09add2c6257f845581\",\"content\":\"\\\"\\\"\\\"Unit tests for :class:`AstraDBDataAPIComponent`.\\n\\nThese tests exercise every operation dispatch path and the astrapy-backed\\ncollection-creation override without reaching out to Astra DB; ``astrapy``\\nentry points are mocked.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom collections import defaultdict\\nfrom unittest.mock import Mock, patch\\n\\nimport pytest\\nfrom lfx_datastax.components.datastax.astradb_data_api import (\\n    ALL_OPERATIONS,\\n    DEFAULT_COUNT_UPPER_BOUND,\\n    OP_COUNT,\\n    OP_DELETE_MANY,\\n    OP_DELETE_ONE,\\n    OP_ESTIMATED_COUNT,\\n    OP_FIND,\\n    OP_FIND_ONE,\\n    OP_INSERT_MANY,\\n    OP_INSERT_ONE,\\n    OP_UPDATE_MANY,\\n    OP_UPDATE_ONE,\\n    OPERATION_FIELDS,\\n    OPERATION_ICONS,\\n    AstraDBDataAPIComponent,\\n    _coerce_documents,\\n    _stringify,\\n)\\nfrom lfx.schema.data import Data\\n\\n# ----------------------------------------------------------------------\\n# Fixtures\\n# ----------------------------------------------------------------------\\n\\n\\n@pytest.fixture\\ndef component() -> AstraDBDataAPIComponent:\\n    \\\"\\\"\\\"Minimal component with required selector attrs pre-populated.\\\"\\\"\\\"\\n    comp = AstraDBDataAPIComponent()\\n    comp.token = \\\"test_token\\\"  # noqa: S105\\n    comp.environment = \\\"prod\\\"\\n    comp.database_name = \\\"test_db\\\"\\n    comp.api_endpoint = \\\"https://abcd1234-1234-1234-1234-1234567890ab.apps.astra.datastax.com\\\"\\n    comp.keyspace = \\\"default_keyspace\\\"\\n    comp.collection_name = \\\"test_coll\\\"\\n    comp.operation = OP_FIND\\n    # Every operation-specific field starts unset.\\n    comp.filter_query = {}\\n    comp.projection = {}\\n    comp.sort = {}\\n    comp.limit = 0\\n    comp.skip = 0\\n    comp.include_similarity = False\\n    comp.document = {}\\n    comp.documents = []\\n    comp.ordered = False\\n    comp.update = {}\\n    comp.upsert = False\\n    comp.upper_bound = DEFAULT_COUNT_UPPER_BOUND\\n    comp.log = Mock()\\n    return comp\\n\\n\\n@pytest.fixture\\ndef mock_collection() -> Mock:\\n    \\\"\\\"\\\"A mocked astrapy.Collection with the operations we need.\\\"\\\"\\\"\\n    return Mock()\\n\\n\\n@pytest.fixture\\ndef component_with_collection(component, mock_collection):\\n    \\\"\\\"\\\"Component where ``_get_collection`` is patched to return ``mock_collection``.\\\"\\\"\\\"\\n    component._get_collection = Mock(return_value=mock_collection)  # type: ignore[method-assign]\\n    return component\\n\\n\\n# ----------------------------------------------------------------------\\n# Static / configuration tests\\n# ----------------------------------------------------------------------\\n\\n\\nclass TestStaticConfiguration:\\n    \\\"\\\"\\\"Tests that don't require a component instance.\\\"\\\"\\\"\\n\\n    def test_all_operations_have_icons(self):\\n        \\\"\\\"\\\"Every dropdown option has an associated icon.\\\"\\\"\\\"\\n        assert set(OPERATION_ICONS.keys()) == set(ALL_OPERATIONS)\\n\\n    def test_all_operations_have_fields(self):\\n        \\\"\\\"\\\"Every dropdown option has a field-set definition (possibly empty).\\\"\\\"\\\"\\n        assert set(OPERATION_FIELDS.keys()) == set(ALL_OPERATIONS)\\n\\n    def test_operation_field_names_exist_on_inputs(self):\\n        \\\"\\\"\\\"Every field referenced in OPERATION_FIELDS is an actual declared input.\\\"\\\"\\\"\\n        input_names = {inp.name for inp in AstraDBDataAPIComponent.inputs}\\n        for op, fields in OPERATION_FIELDS.items():\\n            for field in fields:\\n                assert field in input_names, f\\\"Operation '{op}' references unknown input field '{field}'\\\"\\n\\n    def test_component_metadata(self):\\n        \\\"\\\"\\\"Component metadata is sensible.\\\"\\\"\\\"\\n        assert AstraDBDataAPIComponent.display_name == \\\"Astra DB Data API\\\"\\n        assert AstraDBDataAPIComponent.name == \\\"AstraDBDataAPI\\\"\\n        assert AstraDBDataAPIComponent.icon == \\\"AstraDB\\\"\\n        assert AstraDBDataAPIComponent.beta is True\\n\\n    def test_outputs_defined(self):\\n        \\\"\\\"\\\"The three documented output sockets are present.\\\"\\\"\\\"\\n        names = {o.name for o in AstraDBDataAPIComponent.outputs}\\n        assert names == {\\\"data\\\", \\\"dataframe\\\", \\\"raw\\\"}\\n\\n    def test_tool_mode_inputs(self):\\n        \\\"\\\"\\\"Key agent-controllable inputs expose ``tool_mode=True``.\\\"\\\"\\\"\\n        tool_mode_names = {inp.name for inp in AstraDBDataAPIComponent.inputs if getattr(inp, \\\"tool_mode\\\", False)}\\n        expected = {\\n            \\\"operation\\\",\\n            \\\"filter_query\\\",\\n            \\\"limit\\\",\\n            \\\"document\\\",\\n            \\\"documents\\\",\\n            \\\"update\\\",\\n        }\\n        assert expected.issubset(tool_mode_names), (\\n            f\\\"Missing tool_mode on agent-controllable inputs: {expected - tool_mode_names}\\\"\\n        )\\n        # Secrets and selector fields should never be marked as tool-controllable.\\n        forbidden = {\\n            \\\"token\\\",\\n            \\\"api_endpoint\\\",\\n            \\\"database_name\\\",\\n            \\\"collection_name\\\",\\n            \\\"keyspace\\\",\\n        }\\n        assert forbidden.isdisjoint(tool_mode_names), (\\n            f\\\"Sensitive/selector fields must not be tool_mode: {forbidden & tool_mode_names}\\\"\\n        )\\n\\n\\n# ----------------------------------------------------------------------\\n# Helpers\\n# ----------------------------------------------------------------------\\n\\n\\nclass TestStringify:\\n    def test_primitives_pass_through(self):\\n        assert _stringify(\\\"abc\\\") == \\\"abc\\\"\\n        assert _stringify(1) == 1\\n        assert _stringify(1.5) == 1.5\\n        assert _stringify(True) is True  # noqa: FBT003\\n\\n    def test_none_returns_none(self):\\n        assert _stringify(None) is None\\n\\n    def test_objects_stringified(self):\\n        class Id:\\n            def __str__(self):\\n                return \\\"object-id\\\"\\n\\n        assert _stringify(Id()) == \\\"object-id\\\"\\n\\n\\nclass TestCoerceDocuments:\\n    def test_empty_value(self):\\n        assert _coerce_documents(None) == []\\n        assert _coerce_documents(\\\"\\\") == []\\n\\n    def test_single_dict_wrapped(self):\\n        result = _coerce_documents({\\\"a\\\": 1})\\n        assert result == [{\\\"a\\\": 1}]\\n\\n    def test_list_passes_through(self):\\n        docs = [{\\\"a\\\": 1}, {\\\"b\\\": 2}]\\n        assert _coerce_documents(docs) == docs\\n\\n    def test_rejects_non_dict_entries(self):\\n        with pytest.raises(ValueError, match=\\\"non-dict entries\\\"):\\n            _coerce_documents([{\\\"a\\\": 1}, \\\"not-a-dict\\\"])\\n\\n    def test_rejects_wrong_type(self):\\n        with pytest.raises(ValueError, match=\\\"Documents must be a list\\\"):\\n            _coerce_documents(42)\\n\\n\\n# ----------------------------------------------------------------------\\n# UI: operation visibility toggling\\n# ----------------------------------------------------------------------\\n\\n\\nclass TestOperationVisibility:\\n    def _make_build_config(self) -> dict:\\n        \\\"\\\"\\\"Build a config dict containing every toggle-able field.\\\"\\\"\\\"\\n        fields = set().union(*OPERATION_FIELDS.values())\\n        return {field: {\\\"show\\\": True} for field in fields}\\n\\n    def test_find_shows_query_fields(self):\\n        config = self._make_build_config()\\n        AstraDBDataAPIComponent._apply_operation_visibility(config, OP_FIND)\\n        assert config[\\\"filter_query\\\"][\\\"show\\\"] is True\\n        assert config[\\\"limit\\\"][\\\"show\\\"] is True\\n        assert config[\\\"document\\\"][\\\"show\\\"] is False\\n        assert config[\\\"update\\\"][\\\"show\\\"] is False\\n\\n    def test_insert_one_shows_document(self):\\n        config = self._make_build_config()\\n        AstraDBDataAPIComponent._apply_operation_visibility(config, OP_INSERT_ONE)\\n        assert config[\\\"document\\\"][\\\"show\\\"] is True\\n        assert config[\\\"documents\\\"][\\\"show\\\"] is False\\n        assert config[\\\"filter_query\\\"][\\\"show\\\"] is False\\n\\n    def test_insert_many_shows_documents_and_ordered(self):\\n        config = self._make_build_config()\\n        AstraDBDataAPIComponent._apply_operation_visibility(config, OP_INSERT_MANY)\\n        assert config[\\\"documents\\\"][\\\"show\\\"] is True\\n        assert config[\\\"ordered\\\"][\\\"show\\\"] is True\\n        assert config[\\\"document\\\"][\\\"show\\\"] is False\\n\\n    def test_update_ops_show_filter_update_upsert(self):\\n        for op in (OP_UPDATE_ONE, OP_UPDATE_MANY):\\n            config = self._make_build_config()\\n            AstraDBDataAPIComponent._apply_operation_visibility(config, op)\\n            assert config[\\\"filter_query\\\"][\\\"show\\\"] is True\\n            assert config[\\\"update\\\"][\\\"show\\\"] is True\\n            assert config[\\\"upsert\\\"][\\\"show\\\"] is True\\n            assert config[\\\"document\\\"][\\\"show\\\"] is False\\n\\n    def test_count_shows_upper_bound(self):\\n        config = self._make_build_config()\\n        AstraDBDataAPIComponent._apply_operation_visibility(config, OP_COUNT)\\n        assert config[\\\"filter_query\\\"][\\\"show\\\"] is True\\n        assert config[\\\"upper_bound\\\"][\\\"show\\\"] is True\\n\\n    def test_estimated_count_hides_everything(self):\\n        config = self._make_build_config()\\n        AstraDBDataAPIComponent._apply_operation_visibility(config, OP_ESTIMATED_COUNT)\\n        for key, value in config.items():\\n            assert value[\\\"show\\\"] is False, f\\\"Field '{key}' should be hidden for Estimated Count\\\"\\n\\n\\n# ----------------------------------------------------------------------\\n# Operation dispatch\\n# ----------------------------------------------------------------------\\n\\n\\nclass TestFindOperation:\\n    def test_find_returns_list_of_data(self, component_with_collection, mock_collection):\\n        mock_collection.find.return_value = iter([{\\\"_id\\\": \\\"1\\\", \\\"name\\\": \\\"Ada\\\"}, {\\\"_id\\\": \\\"2\\\", \\\"name\\\": \\\"Grace\\\"}])\\n        component_with_collection.operation = OP_FIND\\n        component_with_collection.filter_query = {\\\"active\\\": True}\\n        component_with_collection.limit = 10\\n\\n        result = component_with_collection.run_operation()\\n\\n        mock_collection.find.assert_called_once()\\n        call_kwargs = mock_collection.find.call_args.kwargs\\n        assert call_kwargs[\\\"filter\\\"] == {\\\"active\\\": True}\\n        assert call_kwargs[\\\"limit\\\"] == 10\\n\\n        assert len(result) == 2\\n        assert all(isinstance(d, Data) for d in result)\\n        assert result[0].data == {\\\"_id\\\": \\\"1\\\", \\\"name\\\": \\\"Ada\\\"}\\n\\n    def test_find_omits_empty_options(self, component_with_collection, mock_collection):\\n        mock_collection.find.return_value = iter([])\\n        component_with_collection.operation = OP_FIND\\n\\n        component_with_collection.run_operation()\\n\\n        kwargs = mock_collection.find.call_args.kwargs\\n        assert \\\"projection\\\" not in kwargs\\n        assert \\\"sort\\\" not in kwargs\\n        assert \\\"limit\\\" not in kwargs\\n        assert \\\"skip\\\" not in kwargs\\n        assert \\\"include_similarity\\\" not in kwargs\\n\\n    def test_find_respects_skip_projection_sort(self, component_with_collection, mock_collection):\\n        mock_collection.find.return_value = iter([])\\n        component_with_collection.operation = OP_FIND\\n        component_with_collection.projection = {\\\"name\\\": 1}\\n        component_with_collection.sort = {\\\"$vectorize\\\": \\\"hello\\\"}\\n        component_with_collection.skip = 5\\n        component_with_collection.limit = 20\\n        component_with_collection.include_similarity = True\\n\\n        component_with_collection.run_operation()\\n\\n        kwargs = mock_collection.find.call_args.kwargs\\n        assert kwargs[\\\"projection\\\"] == {\\\"name\\\": 1}\\n        assert kwargs[\\\"sort\\\"] == {\\\"$vectorize\\\": \\\"hello\\\"}\\n        assert kwargs[\\\"skip\\\"] == 5\\n        assert kwargs[\\\"limit\\\"] == 20\\n        assert kwargs[\\\"include_similarity\\\"] is True\\n\\n    def test_find_raw_result(self, component_with_collection, mock_collection):\\n        mock_collection.find.return_value = iter([{\\\"a\\\": 1}, {\\\"a\\\": 2}])\\n        component_with_collection.operation = OP_FIND\\n\\n        raw = component_with_collection.raw_result()\\n\\n        assert isinstance(raw, Data)\\n        assert raw.data[\\\"count\\\"] == 2\\n        assert raw.data[\\\"documents\\\"] == [{\\\"a\\\": 1}, {\\\"a\\\": 2}]\\n\\n\\nclass TestFindOneOperation:\\n    def test_find_one_with_match(self, component_with_collection, mock_collection):\\n        mock_collection.find_one.return_value = {\\\"_id\\\": \\\"1\\\", \\\"name\\\": \\\"Ada\\\"}\\n        component_with_collection.operation = OP_FIND_ONE\\n        component_with_collection.filter_query = {\\\"_id\\\": \\\"1\\\"}\\n\\n        result = component_with_collection.run_operation()\\n\\n        mock_collection.find_one.assert_called_once()\\n        kwargs = mock_collection.find_one.call_args.kwargs\\n        assert kwargs[\\\"filter\\\"] == {\\\"_id\\\": \\\"1\\\"}\\n        # ``limit`` / ``skip`` are not valid for find_one -- make sure we don't leak them.\\n        assert \\\"limit\\\" not in kwargs\\n        assert \\\"skip\\\" not in kwargs\\n        assert len(result) == 1\\n        assert result[0].data == {\\\"_id\\\": \\\"1\\\", \\\"name\\\": \\\"Ada\\\"}\\n\\n    def test_find_one_no_match_returns_empty(self, component_with_collection, mock_collection):\\n        mock_collection.find_one.return_value = None\\n        component_with_collection.operation = OP_FIND_ONE\\n        component_with_collection.filter_query = {\\\"_id\\\": \\\"missing\\\"}\\n\\n        assert component_with_collection.run_operation() == []\\n\\n\\nclass TestInsertOneOperation:\\n    def test_insert_one_success(self, component_with_collection, mock_collection):\\n        mock_result = Mock()\\n        mock_result.inserted_id = \\\"inserted-id-123\\\"\\n        mock_collection.insert_one.return_value = mock_result\\n\\n        component_with_collection.operation = OP_INSERT_ONE\\n        component_with_collection.document = {\\\"name\\\": \\\"Ada\\\"}\\n\\n        result = component_with_collection.run_operation()\\n\\n        mock_collection.insert_one.assert_called_once_with({\\\"name\\\": \\\"Ada\\\"})\\n        assert len(result) == 1\\n        assert result[0].data == {\\\"inserted_id\\\": \\\"inserted-id-123\\\"}\\n\\n    def test_insert_one_rejects_non_dict(self, component_with_collection):\\n        component_with_collection.operation = OP_INSERT_ONE\\n        component_with_collection.document = \\\"not-a-dict\\\"\\n\\n        with pytest.raises(ValueError, match=\\\"Astra DB Data API 'Insert One' failed\\\"):\\n            component_with_collection.run_operation()\\n\\n\\nclass TestInsertManyOperation";
